window.HP_DATA=[{"id": "sleep", "label": "8 hrs sleep", "title": "8 hours of sleep", "tier": "daily", "group": null, "blurb": "Eight hours a night, same bedtime and wake time every day, including weekends.", "sources": [{"title": "Sleep duration and all-cause mortality: a systematic review and meta-analysis of prospective studies", "authors": "Cappuccio FP, D'Elia L, Strazzullo P, et al.", "year": 2010, "journal": "Sleep", "doi": "10.1093/sleep/33.5.585", "pmid": "20469800", "pmcid": "PMC2864873", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2864873/", "type": "meta-analysis", "summary": "Pooled 16 prospective studies (27 cohorts, about 1.38 million adults, 112,566 deaths) relating self-reported sleep duration to all-cause mortality. Short sleep (usually under 6-7 hours) carried a 12% higher risk of death (RR 1.12) and long sleep (usually over 8-9 hours) a 30% higher risk (RR 1.30). Sleep was self-reported and long sleep may partly mark existing illness, so the takeaway is a U-shaped curve with the sweet spot around 7-8 hours, not that more is always better.", "highlight": "short duration of sleep was associated with a greater risk of death (RR: 1.12; 95% CI 1.06 to 1.18; P < 0.01)", "apa": "Cappuccio, F. P., D&#x27;Elia, L., Strazzullo, P., &amp; Miller, M. A. (2010). Sleep Duration and All-Cause Mortality: A Systematic Review and Meta-Analysis of Prospective Studies. <i>Sleep</i>, <i>33</i>(5), 585–592. <a href=\"https://doi.org/10.1093/sleep/33.5.585\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/sleep/33.5.585</a>"}, {"title": "Sleep regularity is a stronger predictor of mortality risk than sleep duration: A prospective cohort study", "authors": "Windred DP, Burns AC, Lane JM, et al.", "year": 2024, "journal": "Sleep", "doi": "10.1093/sleep/zsad253", "pmid": "37738616", "pmcid": "PMC10782501", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10782501/", "type": "cohort", "summary": "Prospective UK Biobank cohort of 60,977 adults whose sleep timing was measured by wrist accelerometer for a week and who were followed for about 6.3 years. People in the more regular sleep-timing quintiles had a 20-48% lower risk of all-cause death than the least regular quintile, and regularity predicted mortality better than duration did. It is observational and based on one week of data in older UK adults, but it suggests keeping consistent bed and wake times matters as much as the hours.", "highlight": "Higher sleep regularity was associated with a 20%-48% lower risk of all-cause mortality", "apa": "Windred, D. P., Burns, A. C., Lane, J. M., Saxena, R., Rutter, M. K., Cain, S. W., &amp; Phillips, A. J. K. (2023). Sleep regularity is a stronger predictor of mortality risk than sleep duration: A prospective cohort study. <i>Sleep</i>, <i>47</i>(1), zsad253. <a href=\"https://doi.org/10.1093/sleep/zsad253\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/sleep/zsad253</a>"}, {"title": "Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society", "authors": "Watson NF, Badr MS, Belenky G, et al.", "year": 2015, "journal": "Sleep", "doi": "10.5665/sleep.4716", "pmid": "26039963", "pmcid": "PMC4434546", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4434546/", "type": "guideline", "summary": "A 15-member AASM and Sleep Research Society expert panel used a modified RAND Appropriateness Method to review the evidence and vote on how much sleep adults need. The panel concluded that adults should sleep 7 or more hours per night on a regular basis, and that habitually sleeping under 7 hours is linked to weight gain, diabetes, hypertension, heart disease, depression, impaired immunity and more errors. It is expert consensus rather than new data, and it notes that more than 9 hours may help young adults or people recovering from sleep debt or illness but is otherwise uncertain.", "highlight": "developed a consensus recommendation for the amount of sleep needed to promote optimal health in adults", "apa": "Watson, N. F., Badr, M. S., Belenky, G., Bliwise, D. L., Buxton, O. M., Buysse, D., Dinges, D. F., Gangwisch, J., Grandner, M. A., Kushida, C., Malhotra, R. K., Martin, J. L., Patel, S. R., Quan, S., &amp; Tasali, E. (2015). Recommended Amount of Sleep for a Healthy Adult: A Joint Consensus Statement of the American Academy of Sleep Medicine and Sleep Research Society. <i>Sleep</i>. <a href=\"https://doi.org/10.5665/sleep.4716\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.5665/sleep.4716</a>"}]}, {"id": "wake", "label": "Fixed wake time", "title": "Fixed wake time", "tier": "daily", "group": null, "blurb": "", "sources": [{"title": "Irregular sleep/wake patterns are associated with poorer academic performance and delayed circadian and sleep/wake timing", "authors": "Phillips AJK, Clerx WM, O'Brien CS, et al.", "year": 2017, "journal": "Scientific Reports", "doi": "10.1038/s41598-017-03171-4", "pmid": "28607474", "pmcid": "PMC5468315", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5468315/", "type": "cohort", "summary": "", "highlight": "We studied 61 undergraduates for 30 days using sleep diaries, and quantified sleep regularity using a novel metric, the sleep regularity index (SRI)", "apa": "Phillips, A. J. K., Clerx, W. M., O’Brien, C. S., Sano, A., Barger, L. K., Picard, R. W., Lockley, S. W., Klerman, E. B., &amp; Czeisler, C. A. (2017). Irregular sleep/wake patterns are associated with poorer academic performance and delayed circadian and sleep/wake timing. <i>Scientific Reports</i>, <i>7</i>(1), 3216. <a href=\"https://doi.org/10.1038/s41598-017-03171-4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41598-017-03171-4</a>"}, {"title": "Validation of the Sleep Regularity Index in Older Adults and Associations with Cardiometabolic Risk", "authors": "Lunsford-Avery JR, Engelhard MM, Navar AM, Kollins SH", "year": 2018, "journal": "Scientific Reports", "doi": "10.1038/s41598-018-32402-5", "pmid": "30242174", "pmcid": "PMC6154967", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6154967/", "type": "cohort", "summary": "", "highlight": "Greater sleep irregularity was also correlated with 10-year risk of cardiovascular disease", "apa": "Lunsford-Avery, J. R., Engelhard, M. M., Navar, A. M., &amp; Kollins, S. H. (2018). Validation of the Sleep Regularity Index in Older Adults and Associations with Cardiometabolic Risk. <i>Scientific Reports</i>, <i>8</i>(1), 14158. <a href=\"https://doi.org/10.1038/s41598-018-32402-5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41598-018-32402-5</a>"}, {"title": "Cross-sectional and Prospective Associations of Actigraphy-Assessed Sleep Regularity With Metabolic Abnormalities: The Multi-Ethnic Study of Atherosclerosis", "authors": "Huang T, Redline S", "year": 2019, "journal": "Diabetes Care", "doi": "10.2337/dc19-0596", "pmid": "31167888", "pmcid": "PMC6647049", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6647049/", "type": "cohort", "summary": "", "highlight": "every 1-h increase in the sleep duration SD was associated with 27%", "apa": "Huang, T., &amp; Redline, S. (2019). Cross-sectional and Prospective Associations of Actigraphy-Assessed Sleep Regularity With Metabolic Abnormalities: The Multi-Ethnic Study of Atherosclerosis. <i>Diabetes Care</i>, <i>42</i>(8), 1422–1429. <a href=\"https://doi.org/10.2337/dc19-0596\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.2337/dc19-0596</a>"}]}, {"id": "sunlight", "label": "Morning sunlight", "title": "Morning sunlight", "tier": "daily", "group": null, "blurb": "10–20 minutes outside within an hour of waking, no sunglasses (never look at the sun). Longer on cloudy days.", "sources": [{"title": "Time spent in outdoor light is associated with mood, sleep, and circadian rhythm-related outcomes: A cross-sectional and longitudinal study in over 400,000 UK Biobank participants", "authors": "Burns AC, Saxena R, Vetter C, et al.", "year": 2021, "journal": "Journal of affective disorders", "doi": "10.1016/j.jad.2021.08.056", "pmid": "34488088", "pmcid": "PMC8892387", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8892387/", "type": "cohort", "summary": "Cross-sectional and longitudinal analysis of about 400,000 UK Biobank adults who reported how much daylight time they spent outdoors. Each extra hour outdoors per day was tied to lower odds of depression and antidepressant use, fewer insomnia symptoms, less tiredness, and easier waking (OR about 1.46-1.49 for ease of getting up). Outdoor time was self-reported and light intensity at the eye was not measured, so this shows association, not proof that morning light specifically causes the benefit.", "highlight": "low daytime light exposure is an important environmental risk factor for mood, sleep, and circadian-related outcomes", "apa": "Burns, A. C., Saxena, R., Vetter, C., Phillips, A. J., Lane, J. M., &amp; Cain, S. W. (2021). Time spent in outdoor light is associated with mood, sleep, and circadian rhythm-related outcomes: A cross-sectional and longitudinal study in over 400,000 UK Biobank participants. <i>Journal of Affective Disorders</i>, <i>295</i>, 347–352. <a href=\"https://doi.org/10.1016/j.jad.2021.08.056\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jad.2021.08.056</a>"}, {"title": "Brighter nights and darker days predict higher mortality risk: A prospective analysis of personal light exposure in >88,000 individuals", "authors": "Windred DP, Burns AC, Lane JM, et al.", "year": 2024, "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.2405924121", "pmid": "39405349", "pmcid": "PMC11513964", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11513964/", "type": "cohort", "summary": "Prospective UK Biobank study of 88,905 adults who wore a wrist light sensor for one week, followed for about 8 years (3,750 deaths). Those with the brightest daytime light had up to 17-34% lower all-cause mortality (aHR 0.66-0.83 for the top decile), while bright light at night raised risk by up to 21-34%. It is observational with one week of measurement, but it supports the practical rule: bright days, dark nights.", "highlight": "Minimizing night light, maximizing day light, and keeping regular light-dark patterns that enhance circadian rhythms may promote cardiometabolic health and longevity", "apa": "Windred, D. P., Burns, A. C., Lane, J. M., Olivier, P., Rutter, M. K., Saxena, R., Phillips, A. J. K., &amp; Cain, S. W. (2024). Brighter nights and darker days predict higher mortality risk: A prospective analysis of personal light exposure in &amp;gt;88,000 individuals. <i>Proceedings of the National Academy of Sciences</i>, <i>121</i>(43), e2405924121. <a href=\"https://doi.org/10.1073/pnas.2405924121\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1073/pnas.2405924121</a>"}, {"title": "Effects of light on human circadian rhythms, sleep and mood", "authors": "Blume C, Garbazza C, Spitschan M", "year": 2019, "journal": "Somnologie : Schlafforschung und Schlafmedizin = Somnology : sleep research and sleep medicine", "doi": "10.1007/s11818-019-00215-x", "pmid": "31534436", "pmcid": "PMC6751071", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6751071/", "type": "review", "summary": "Narrative review of how light reaches the brain's master clock (the suprachiasmatic nucleus) via the retina and how light timing shapes circadian rhythms, sleep and mood. Light is the main signal that sets the body clock; morning light advances it, evening and night light delays it and suppresses melatonin, and bright light therapy is an effective low-risk treatment for some sleep and mood problems. This is a mechanism review rather than an outcome trial, so it explains why morning light should help more than it quantifies how much.", "highlight": "light can also be used as an effective and noninvasive therapeutic option with little to no side effects, to improve sleep,mood and general well-being", "apa": "Blume, C., Garbazza, C., &amp; Spitschan, M. (2019). Effects of light on human circadian rhythms, sleep and mood. <i>Somnologie</i>, <i>23</i>(3), 147–156. <a href=\"https://doi.org/10.1007/s11818-019-00215-x\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s11818-019-00215-x</a>"}]}, {"id": "water", "label": "Water (1 gal)", "title": "Water, 1 gallon", "tier": "daily", "group": null, "blurb": "About a gallon (3.8 L) through the day. That is above the usual guidance of about 2.7–3.7 L of total water from all food and drink, so spread it out and add electrolytes on sweaty days.", "sources": [{"title": "Middle-age high normal serum sodium as a risk factor for accelerated biological aging, chronic diseases, and premature mortality", "authors": "Dmitrieva NI, Gagarin A, Liu D, et al.", "year": 2023, "journal": "EBioMedicine", "doi": "10.1016/j.ebiom.2022.104404", "pmid": "36599719", "pmcid": "PMC9873684", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9873684/", "type": "cohort", "summary": "NIH analysis of 15,752 adults from the ARIC cohort enrolled at ages 45-66 and followed for 25 years, using serum sodium as a marker of habitual hydration. Mid-life serum sodium above 142 mmol/L was linked to 39% higher risk of chronic disease (HR 1.39), up to 50% higher odds of being biologically older than chronological age, and above 144 mmol/L to 21% higher premature mortality. Serum sodium is an indirect proxy and no one was told to drink more, so this supports staying well hydrated, not a specific target like a gallon a day.", "highlight": "have increased risk to be biologically older, develop chronic diseases and die at younger age", "apa": "Dmitrieva, N. I., Gagarin, A., Liu, D., Wu, C. O., &amp; Boehm, M. (2023). Middle-age high normal serum sodium as a risk factor for accelerated biological aging, chronic diseases, and premature mortality. <i>eBioMedicine</i>, <i>87</i>, 104404. <a href=\"https://doi.org/10.1016/j.ebiom.2022.104404\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.ebiom.2022.104404</a>"}, {"title": "Treatment effect, adherence, and safety of high fluid intake for the prevention of incident and recurrent kidney stones: a systematic review and meta-analysis", "authors": "Cheungpasitporn W, Rossetti S, Friend K, et al.", "year": 2016, "journal": "Journal of nephrology", "doi": "10.1007/s40620-015-0210-4", "pmid": "26022722", "pmcid": "PMC4831051", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4831051/", "type": "meta-analysis", "summary": "Meta-analysis of 9 studies (2 RCTs with 269 patients, 7 observational studies with about 274,000 people) comparing high versus low fluid intake for kidney stone prevention. High fluid intake cut the risk of kidney stones by roughly half to 60% (RR 0.40 in RCTs, 0.49 in observational studies), including recurrent stones. This is the best-established hard benefit of drinking more water, and it matters most for people prone to stones; safety data were thin.", "highlight": "This analysis demonstrated a significantly reduced risk of incident kidney stones among individuals with high fluid consumption", "apa": "Cheungpasitporn, W., Rossetti, S., Friend, K., Erickson, S. B., &amp; Lieske, J. C. (2015). Treatment effect, adherence, and safety of high fluid intake for the prevention of incident and recurrent kidney stones: a systematic review and meta-analysis. <i>Journal of Nephrology</i>, <i>29</i>(2), 211–219. <a href=\"https://doi.org/10.1007/s40620-015-0210-4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s40620-015-0210-4</a>"}, {"title": "Water, hydration, and health", "authors": "Popkin BM, D'Anci KE, Rosenberg IH", "year": 2010, "journal": "Nutrition reviews", "doi": "10.1111/j.1753-4887.2010.00304.x", "pmid": "20646222", "pmcid": "PMC2908954", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2908954/", "type": "review", "summary": "Narrative review in Nutrition Reviews of water intake, hydration physiology, and effects on energy intake, weight, kidney function, physical and cognitive performance. It reports that mild dehydration impairs mood and performance and that replacing sugary drinks with water reduces calorie intake, while noting that US guidance (the NASEM Adequate Intake of about 3.7 L/day for men and 2.7 L/day for women) counts total water including roughly 20% from food. There are no long-term randomized trials of higher water intake, and 1 gallon (about 3.8 L) of plain water per day exceeds typical guidance for most people unless they are large, very active or in heat; very high intake can rarely cause hyponatremia.", "highlight": "there are also few longer-term systematic interventions and no published randomized, controlled longer-term trials", "apa": "Popkin, B. M., D&#x27;Anci, K. E., &amp; Rosenberg, I. H. (2010). Water, hydration, and health. <i>Nutrition Reviews</i>, <i>68</i>(8), 439–458. <a href=\"https://doi.org/10.1111/j.1753-4887.2010.00304.x\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1111/j.1753-4887.2010.00304.x</a>"}]}, {"id": "sauna", "label": "Sauna", "title": "Sauna", "tier": "daily", "group": null, "blurb": "Regular heat exposure, roughly 20 minutes at 80°C+, ideally 4–7 sessions a week.", "sources": [{"title": "Association between sauna bathing and fatal cardiovascular and all-cause mortality events", "authors": "Laukkanen T, Khan H, Zaccardi F, Laukkanen JA", "year": 2015, "journal": "JAMA Intern Med", "doi": "10.1001/jamainternmed.2014.8187", "pmid": "25705824", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25705824/", "type": "cohort", "summary": "Prospective cohort of 2,315 middle-aged Finnish men (Kuopio study) followed for a median of 20.7 years. Men using the sauna 4-7 times a week had a 63% lower risk of sudden cardiac death (HR 0.37) than once-a-week users, with similar trends for heart disease and all-cause death. It is one observational cohort of men only, and frequent sauna use may partly mark better health, wealth and leisure time.", "highlight": "Increased frequency of sauna bathing is associated with a reduced risk of SCD, CHD, CVD, and all-cause mortality.", "apa": "Laukkanen, T., Khan, H., Zaccardi, F., &amp; Laukkanen, J. A. (2015). Association Between Sauna Bathing and Fatal Cardiovascular and All-Cause Mortality Events. <i>JAMA Internal Medicine</i>, <i>175</i>(4), 542. <a href=\"https://doi.org/10.1001/jamainternmed.2014.8187\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jamainternmed.2014.8187</a>"}, {"title": "Sauna bathing is inversely associated with dementia and Alzheimer's disease in middle-aged Finnish men", "authors": "Laukkanen T, Kunutsor S, Kauhanen J, Laukkanen JA", "year": 2017, "journal": "Age Ageing", "doi": "10.1093/ageing/afw212", "pmid": "27932366", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/27932366/", "type": "cohort", "summary": "Same Kuopio cohort of 2,315 men aged 42-60, followed about 20 years for dementia and Alzheimer's diagnoses. Compared with once a week, sauna use 4-7 times a week was associated with a 66% lower dementia risk (HR 0.34) and 65% lower Alzheimer's risk. Case numbers in the top group were small and the cohort is all male and Finnish, so this is a hypothesis, not proof.", "highlight": "moderate to high frequency of sauna bathing was associated with lowered risks of dementia and Alzheimer's disease", "apa": "Laukkanen, T., Kunutsor, S., Kauhanen, J., &amp; Laukkanen, J. A. (2016). Sauna bathing is inversely associated with dementia and Alzheimer&#x27;s disease in middle-aged Finnish men. <i>Age and Ageing</i>, <i>46</i>(2), 245–249. <a href=\"https://doi.org/10.1093/ageing/afw212\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/ageing/afw212</a>"}, {"title": "Cardiovascular and Other Health Benefits of Sauna Bathing: A Review of the Evidence", "authors": "Laukkanen JA, Laukkanen T, Kunutsor SK", "year": 2018, "journal": "Mayo Clin Proc", "doi": "10.1016/j.mayocp.2018.04.008", "pmid": "30077204", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/30077204/", "type": "review", "summary": "Narrative review of observational, experimental and interventional studies on Finnish sauna bathing and health. It reports links to lower blood pressure, cardiovascular disease, dementia and mortality, with plausible mechanisms such as better endothelial function and reduced arterial stiffness. It is written largely by the same group that produced the main cohort data, and randomized evidence on hard outcomes is lacking.", "highlight": "regular sauna bathing may improve cardiovascular function via improved endothelium-dependent dilatation, reduced arterial stiffness, modulation of the autonomic nervous system", "apa": "Laukkanen, J. A., Laukkanen, T., &amp; Kunutsor, S. K. (2018). Cardiovascular and Other Health Benefits of Sauna Bathing: A Review of the Evidence. <i>Mayo Clinic Proceedings</i>, <i>93</i>(8), 1111–1121. <a href=\"https://doi.org/10.1016/j.mayocp.2018.04.008\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.mayocp.2018.04.008</a>"}]}, {"id": "wimhof", "label": "Wim Hof breathing", "title": "Wim Hof breathing", "tier": "daily", "group": null, "blurb": "Rounds of deep cyclic breathing followed by breath holds. Sit or lie down, never in water or while driving.", "sources": [{"title": "Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans", "authors": "Kox M, van Eijk LT, Zwaag J, et al.", "year": 2014, "journal": "Proc Natl Acad Sci U S A", "doi": "10.1073/pnas.1322174111", "pmid": "24799686", "pmcid": "PMC4034215", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4034215/", "type": "RCT", "summary": "Small randomized trial in which 12 healthy men trained 10 days in Wim Hof-style breathing, meditation and cold exposure, versus 12 untrained controls, before an injection of bacterial endotoxin. The trained group had sharply higher adrenaline, higher anti-inflammatory IL-10, lower inflammatory cytokines and fewer flu-like symptoms. With 24 young men, a lab endotoxin model and no long-term outcomes, it shows a physiological effect, not a health benefit in daily life.", "highlight": "voluntary activation of the sympathetic nervous system results in epinephrine release and subsequent suppression of the innate immune response in humans in vivo", "apa": "Kox, M., van Eijk, L. T., Zwaag, J., van den Wildenberg, J., Sweep, F. C. G. J., van der Hoeven, J. G., &amp; Pickkers, P. (2014). Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans. <i>Proceedings of the National Academy of Sciences</i>, <i>111</i>(20), 7379–7384. <a href=\"https://doi.org/10.1073/pnas.1322174111\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1073/pnas.1322174111</a>"}, {"title": "Effect of breathwork on stress and mental health: A meta-analysis of randomised-controlled trials", "authors": "Fincham GW, Strauss C, Montero-Marin J, Cavanagh K", "year": 2023, "journal": "Sci Rep", "doi": "10.1038/s41598-022-27247-y", "pmid": "36624160", "pmcid": "PMC9828383", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9828383/", "type": "meta-analysis", "summary": "Meta-analysis of 12 RCTs (785 adults) on breathwork of many styles versus non-breathwork controls, with secondary analyses on anxiety and depression. Breathwork produced a small-to-medium reduction in self-reported stress (g = -0.35), with similar effects on anxiety and depressive symptoms. Most trials had moderate risk of bias and few tested Wim Hof breathing specifically, and the authors warn against hype outrunning evidence.", "highlight": "we urge caution and advocate for nuanced research approaches with low risk-of-bias study designs to avoid a miscalibration between hype and evidence", "apa": "Fincham, G. W., Strauss, C., Montero-Marin, J., &amp; Cavanagh, K. (2023). Effect of breathwork on stress and mental health: A meta-analysis of randomised-controlled trials. <i>Scientific Reports</i>, <i>13</i>(1), 432. <a href=\"https://doi.org/10.1038/s41598-022-27247-y\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41598-022-27247-y</a>"}, {"title": "Does the Wim Hof Method have a beneficial impact on physiological and psychological outcomes in healthy and non-healthy participants? A systematic review", "authors": "Almahayni O, Hammond L", "year": 2024, "journal": "PLoS One", "doi": "10.1371/journal.pone.0286933", "pmid": "38478473", "pmcid": "PMC10936795", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10936795/", "type": "systematic review", "summary": "Systematic review of studies on the Wim Hof Method or its breathing component, finding only nine papers from eight trials. The most consistent signal was an anti-inflammatory effect via raised adrenaline; effects on exercise performance and breathing parameters were mixed. The evidence base is tiny and heterogeneous, so claims beyond short-term inflammation changes are not well supported.", "highlight": "the findings of this review show promising use of WHM in the inflammatory response category", "apa": "Almahayni, O., &amp; Hammond, L. (2024). Does the Wim Hof Method have a beneficial impact on physiological and psychological outcomes in healthy and non-healthy participants? A systematic review. <i>Plos One</i>, <i>19</i>(3), e0286933. <a href=\"https://doi.org/10.1371/journal.pone.0286933\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1371/journal.pone.0286933</a>"}]}, {"id": "stretching", "label": "20 min stretching", "title": "20 minutes of stretching", "tier": "daily", "group": null, "blurb": "Twenty minutes a day of static or dynamic stretching, hitting hips, hamstrings, chest and shoulders.", "sources": [{"title": "Chronic effects of stretching on range of motion with consideration of potential moderating variables: A systematic review with meta-analysis", "authors": "Konrad A, Alizadeh S, Daneshjoo A, Anvar SH, et al.", "year": 2024, "journal": "Journal of Sport and Health Science", "doi": "10.1016/j.jshs.2023.06.002", "pmid": "37301370", "pmcid": "PMC10980866", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10980866/", "type": "meta-analysis", "summary": "This meta-analysis pooled 77 studies (186 effect sizes) on regular stretch training in healthy people. Stretching reliably increased range of motion with a moderate effect (effect size about 1.0), with static and PNF stretching beating dynamic stretching. Volume, intensity and frequency did not clearly change the gains, so 20 minutes a day is likely more than needed for flexibility alone.", "highlight": "stretch training can increase ROM with a moderate effect compared to the controls", "apa": "Konrad, A., Alizadeh, S., Daneshjoo, A., Anvar, S. H., Graham, A., Zahiri, A., Goudini, R., Edwards, C., Scharf, C., &amp; Behm, D. G. (2024). Chronic effects of stretching on range of motion with consideration of potential moderating variables: A systematic review with meta-analysis. <i>Journal of Sport and Health Science</i>, <i>13</i>(2), 186–194. <a href=\"https://doi.org/10.1016/j.jshs.2023.06.002\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jshs.2023.06.002</a>"}, {"title": "Stretching is Superior to Brisk Walking for Reducing Blood Pressure in People With High-Normal Blood Pressure or Stage I Hypertension", "authors": "Ko J, Deprez D, Shaw K, Alcorn J, et al.", "year": 2021, "journal": "Journal of Physical Activity & Health", "doi": "10.1123/jpah.2020-0365", "pmid": "33338988", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/33338988/", "type": "RCT", "summary": "Forty adults (mean age 62) with high-normal blood pressure or stage 1 hypertension were randomized to 30 minutes of stretching or brisk walking, five days a week for eight weeks. Stretching lowered sitting systolic pressure from 146 to 140 mmHg and reduced other measures more than walking did. It is a single small trial, and walking's lack of effect is unusual, so treat this as promising rather than settled.", "highlight": "An 8-week stretching program was superior to brisk walking for reducing blood pressure in individuals with high-normal blood pressure or stage 1 hypertension.", "apa": "Ko, J., Deprez, D., Shaw, K., Alcorn, J., Hadjistavropoulos, T., Tomczak, C., Foulds, H., &amp; Chilibeck, P. D. (2021). Stretching is Superior to Brisk Walking for Reducing Blood Pressure in People With High–Normal Blood Pressure or Stage I Hypertension. <i>Journal of Physical Activity and Health</i>, <i>18</i>(1), 21–28. <a href=\"https://doi.org/10.1123/jpah.2020-0365\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1123/jpah.2020-0365</a>"}, {"title": "The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials", "authors": "Lauersen JB, Bertelsen DM, Andersen LB", "year": 2014, "journal": "British Journal of Sports Medicine", "doi": "10.1136/bjsports-2013-092538", "pmid": "24100287", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/24100287/", "type": "meta-analysis", "summary": "This meta-analysis pooled 25 randomized trials with 26,610 participants and 3,464 injuries, comparing stretching, strength, balance and combined programs for injury prevention. Stretching showed no protective effect (RR 0.96, confidence interval crossing 1), while strength training cut injuries to under a third (RR 0.32). Stretch for range of motion and how it feels, but do not count on it to prevent injuries; strength work does that better.", "highlight": "consistently favourable estimates were obtained for all injury prevention measures except for stretching", "apa": "Lauersen, J. B., Bertelsen, D. M., &amp; Andersen, L. B. (2013). The effectiveness of exercise interventions to prevent sports injuries: a systematic review and meta-analysis of randomised controlled trials. <i>British Journal of Sports Medicine</i>, <i>48</i>(11), 871–877. <a href=\"https://doi.org/10.1136/bjsports-2013-092538\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bjsports-2013-092538</a>"}]}, {"id": "protein_target", "label": "Protein target", "title": "Protein target", "tier": "daily", "group": null, "blurb": "", "sources": [{"title": "A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults", "authors": "Morton RW, Murphy KT, McKellar SR, et al.", "year": 2018, "journal": "British Journal of Sports Medicine", "doi": "10.1136/bjsports-2017-097608", "pmid": "28698222", "pmcid": "PMC5867436", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5867436/", "type": "meta-analysis", "summary": "", "highlight": "Data from 49 studies with 1863 participants showed that dietary protein supplementation significantly", "apa": "Morton, R. W., Murphy, K. T., McKellar, S. R., Schoenfeld, B. J., Henselmans, M., Helms, E., Aragon, A. A., Devries, M. C., Banfield, L., Krieger, J. W., &amp; Phillips, S. M. (2017). A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults. <i>British Journal of Sports Medicine</i>, <i>52</i>(6), 376–384. <a href=\"https://doi.org/10.1136/bjsports-2017-097608\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bjsports-2017-097608</a>"}, {"title": "Evidence-Based Recommendations for Optimal Dietary Protein Intake in Older People: A Position Paper From the PROT-AGE Study Group", "authors": "Bauer J, Biolo G, Cederholm T, et al.", "year": 2013, "journal": "Journal of the American Medical Directors Association", "doi": "10.1016/j.jamda.2013.05.021", "pmid": "23867520", "pmcid": null, "url": "https://doi.org/10.1016/j.jamda.2013.05.021", "type": "guideline", "summary": "", "highlight": "older adults need more dietary protein than do younger adults to support good health", "apa": "Bauer, J., Biolo, G., Cederholm, T., Cesari, M., Cruz-Jentoft, A. J., Morley, J. E., Phillips, S., Sieber, C., Stehle, P., Teta, D., Visvanathan, R., Volpi, E., &amp; Boirie, Y. (2013). Evidence-Based Recommendations for Optimal Dietary Protein Intake in Older People: A Position Paper From the PROT-AGE Study Group. <i>Journal of the American Medical Directors Association</i>, <i>14</i>(8), 542–559. <a href=\"https://doi.org/10.1016/j.jamda.2013.05.021\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jamda.2013.05.021</a>"}, {"title": "International Society of Sports Nutrition Position Stand: protein and exercise", "authors": "Jäger R, Kerksick CM, Campbell BI, et al.", "year": 2017, "journal": "Journal of the International Society of Sports Nutrition", "doi": "10.1186/s12970-017-0177-8", "pmid": "28642676", "pmcid": "PMC5477153", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/", "type": "guideline", "summary": "", "highlight": "an overall daily protein intake in the range of 1.4-2.0 g protein/kg body weight/day", "apa": "Jäger, R., Kerksick, C. M., Campbell, B. I., Cribb, P. J., Wells, S. D., Skwiat, T. M., Purpura, M., Ziegenfuss, T. N., Ferrando, A. A., Arent, S. M., Smith-Ryan, A. E., Stout, J. R., Arciero, P. J., Ormsbee, M. J., Taylor, L. W., Wilborn, C. D., Kalman, D. S., Kreider, R. B., Willoughby, D. S., . . . Antonio, J. (2017). International Society of Sports Nutrition Position Stand: protein and exercise. <i>Journal of the International Society of Sports Nutrition</i>, <i>14</i>(1), 20. <a href=\"https://doi.org/10.1186/s12970-017-0177-8\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1186/s12970-017-0177-8</a>"}]}, {"id": "creatine", "label": "Creatine", "title": "Creatine monohydrate", "tier": "supplements", "group": null, "blurb": "Blueprint: 2.5 g in the Longevity Mix plus 5 g on its own.", "sources": [{"title": "Effect of creatine supplementation during resistance training on lean tissue mass and muscular strength in older adults: a meta-analysis", "authors": "Chilibeck PD, Kaviani M, Candow DG, et al.", "year": 2017, "journal": "Open Access Journal of Sports Medicine", "doi": "10.2147/OAJSM.S123529", "pmid": "29138605", "pmcid": "PMC5679696", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5679696/", "type": "meta-analysis", "summary": "This meta-analysis pooled 22 randomized trials (721 adults, mean age 57-70) comparing creatine with placebo during 7-52 weeks of resistance training. Creatine added about 1.4 kg more lean mass (95% CI 0.97-1.76 kg) and modestly larger gains in chest press and leg press strength. The benefit depends on lifting at the same time, and the strength effects are small to moderate.", "highlight": "creatine supplementation increases lean tissue mass and upper and lower body muscular strength during resistance training of older adults", "apa": "Chilibeck, P., Kaviani, M., Candow, D., &amp; Zello, G. A. (2017). Effect of creatine supplementation during resistance training on lean tissue mass and muscular strength in older adults: a meta-analysis. <i>Open Access Journal of Sports Medicine</i>, <i>Volume 8</i>, 213–226. <a href=\"https://doi.org/10.2147/OAJSM.S123529\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.2147/OAJSM.S123529</a>"}, {"title": "Effects of creatine supplementation on cognitive function of healthy individuals: A systematic review of randomized controlled trials", "authors": "Avgerinos KI, Spyrou N, Bougioukas KI, et al.", "year": 2018, "journal": "Experimental Gerontology", "doi": "10.1016/j.exger.2018.04.013", "pmid": "29704637", "pmcid": "PMC6093191", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6093191/", "type": "systematic review", "summary": "This systematic review looked at 6 randomized trials (281 healthy people) testing oral creatine on cognitive tests. Short-term memory and reasoning may improve, while results for attention, executive function, and reaction time were conflicting and young people showed no change. The evidence base is small, so the cognitive case is promising but unproven, with the best signal in older, stressed, or vegetarian people.", "highlight": "Oral creatine administration may improve short-term memory and intelligence/reasoning of healthy individuals but its effect on other cognitive domains remains unclear", "apa": "Avgerinos, K. I., Spyrou, N., Bougioukas, K. I., &amp; Kapogiannis, D. (2018). Effects of creatine supplementation on cognitive function of healthy individuals: A systematic review of randomized controlled trials. <i>Experimental Gerontology</i>, <i>108</i>, 166–173. <a href=\"https://doi.org/10.1016/j.exger.2018.04.013\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.exger.2018.04.013</a>"}, {"title": "International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine", "authors": "Kreider RB, Kalman DS, Antonio J, et al.", "year": 2017, "journal": "Journal of the International Society of Sports Nutrition", "doi": "10.1186/s12970-017-0173-z", "pmid": "28615996", "pmcid": "PMC5469049", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5469049/", "type": "guideline", "summary": "This position stand from the International Society of Sports Nutrition reviews the research on creatine for performance, recovery, aging, and clinical uses. It concludes creatine reliably improves high-intensity exercise performance and training adaptations, and that doses up to 30 g/day for 5 years have been safe in healthy people. It is a consensus review by an industry-adjacent society rather than a fresh meta-analysis, but the core guidance of about 3-5 g/day is well supported.", "highlight": "short and long-term supplementation (up to 30 g/day for 5 years) is safe and well-tolerated in healthy individuals", "apa": "Kreider, R. B., Kalman, D. S., Antonio, J., Ziegenfuss, T. N., Wildman, R., Collins, R., Candow, D. G., Kleiner, S. M., Almada, A. L., &amp; Lopez, H. L. (2017). International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. <i>Journal of the International Society of Sports Nutrition</i>, <i>14</i>(1), 18. <a href=\"https://doi.org/10.1186/s12970-017-0173-z\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1186/s12970-017-0173-z</a>"}]}, {"id": "collagen", "label": "Collagen", "title": "Collagen peptides", "tier": "supplements", "group": null, "blurb": "Blueprint: collagen peptides at breakfast and mid-morning.", "sources": [{"title": "Effects of Oral Collagen for Skin Anti-Aging: A Systematic Review and Meta-Analysis", "authors": "Pu SY, Huang YL, Pu CM, et al.", "year": 2023, "journal": "Nutrients", "doi": "10.3390/nu15092080", "pmid": "37432180", "pmcid": "PMC10180699", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10180699/", "type": "meta-analysis", "summary": "This meta-analysis pooled 26 randomized trials (1,721 participants) of hydrolyzed collagen versus placebo for skin. Collagen significantly improved skin hydration and elasticity (both p < 0.00001), with hydration effects varying by collagen source and duration. The authors flag bias in many included trials, several of which are industry-funded, so the effect is real-looking but likely overstated.", "highlight": "the findings suggest that HC supplementation can have positive effects on skin health, but further large-scale randomized control trials are necessary", "apa": "Pu, S.-Y., Huang, Y.-L., Pu, C.-M., Kang, Y.-N., Hoang, K. D., Chen, K.-H., &amp; Chen, C. (2023). Effects of Oral Collagen for Skin Anti-Aging: A Systematic Review and Meta-Analysis. <i>Nutrients</i>, <i>15</i>(9), 2080. <a href=\"https://doi.org/10.3390/nu15092080\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu15092080</a>"}, {"title": "The effects of collagen peptide supplementation on body composition, collagen synthesis, and recovery from joint injury and exercise: a systematic review", "authors": "Khatri M, Naughton RJ, Clifford T, et al.", "year": 2021, "journal": "Amino Acids", "doi": "10.1007/s00726-021-03072-x", "pmid": "34491424", "pmcid": "PMC8521576", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8521576/", "type": "systematic review", "summary": "This systematic review covered 15 randomized trials of collagen peptides combined with exercise, mostly in recreational athletes. The clearest benefit was improved joint function and less joint pain, with 15 g/day raising collagen synthesis but not muscle protein synthesis compared with higher-quality protein. Collagen is not a substitute for regular protein for muscle, and the trials were small.", "highlight": "The results indicated that COL is most beneficial in improving joint functionality and reducing joint pain", "apa": "Khatri, M., Naughton, R. J., Clifford, T., Harper, L. D., &amp; Corr, L. (2021). The effects of collagen peptide supplementation on body composition, collagen synthesis, and recovery from joint injury and exercise: a systematic review. <i>Amino Acids</i>, <i>53</i>(10), 1493–1506. <a href=\"https://doi.org/10.1007/s00726-021-03072-x\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s00726-021-03072-x</a>"}, {"title": "Effect of collagen supplementation on knee osteoarthritis: an updated systematic review and meta-analysis of randomised controlled trials", "authors": "Simental-Mendía M, Ortega-Mata D, Acosta-Olivo CA, et al.", "year": 2025, "journal": "Clinical and Experimental Rheumatology", "doi": "10.55563/clinexprheumatol/kflfr5", "pmid": "39212129", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/39212129/", "type": "meta-analysis", "summary": "This meta-analysis pooled 11 randomized trials (870 people with knee osteoarthritis) of oral collagen-based supplements versus placebo. Collagen improved pain scores (mean difference -13.6) and function scores (mean difference -6.5). Heterogeneity was very high (I2 75-88%) and the collagen products varied, so the size of the benefit is uncertain.", "highlight": "The results of this meta-analysis suggest that oral collagen administration relieves OA symptoms", "apa": "Simental-Mendía, M., Ortega-Mata, D., Acosta-Olivo, C. A., Simental-Mendía, L. E., Peña-Martínez, V. M., &amp; Vilchez-Cavazos, F. (2024). Effect of collagen supplementation on knee osteoarthritis: an updated systematic review and meta-analysis of randomised controlled trials. <i>Clinical and Experimental Rheumatology</i>. <a href=\"https://doi.org/10.55563/clinexprheumatol/kflfr5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.55563/clinexprheumatol/kflfr5</a>"}]}, {"id": "omega3", "label": "Omega-3", "title": "Omega-3 (EPA/DHA)", "tier": "supplements", "group": null, "blurb": "Blueprint: EPA/DHA softgels.", "sources": [{"title": "Marine Omega-3 Supplementation and Cardiovascular Disease: An Updated Meta-Analysis of 13 Randomized Controlled Trials Involving 127 477 Participants", "authors": "Hu Y, Hu FB, Manson JE", "year": 2019, "journal": "Journal of the American Heart Association", "doi": "10.1161/JAHA.119.013543", "pmid": "31567003", "pmcid": "PMC6806028", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6806028/", "type": "meta-analysis", "summary": "This meta-analysis pooled 13 randomized trials (127,477 participants, mean 5 years) of marine omega-3 supplements. Even excluding REDUCE-IT, omega-3 lowered heart attack risk by about 8% (RR 0.92) and cardiovascular death by about 7% (RR 0.93), with larger doses linked to larger reductions. The relative reductions are small, so the absolute benefit for a healthy person is modest.", "highlight": "Marine omega-3 supplementation lowers risk for myocardial infarction, CHD death, total CHD, CVD death, and total CVD, even after exclusion of REDUCE-IT", "apa": "Hu, Y., Hu, F. B., &amp; Manson, J. E. (2019). Marine Omega‐3 Supplementation and Cardiovascular Disease: An Updated Meta‐Analysis of 13 Randomized Controlled Trials Involving 127 477 Participants. <i>Journal of the American Heart Association</i>, <i>8</i>(19), e013543. <a href=\"https://doi.org/10.1161/JAHA.119.013543\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/JAHA.119.013543</a>"}, {"title": "Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease", "authors": "Abdelhamid AS, Brown TJ, Brainard JS, et al.", "year": 2020, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD003177.pub5", "pmid": "32114706", "pmcid": "PMC7049091", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7049091/", "type": "systematic review", "summary": "This Cochrane review analyzed 86 randomized trials (162,796 participants) lasting at least a year. Long-chain omega-3 had little or no effect on all-cause mortality (RR 0.97) or total cardiovascular events (RR 0.96), may slightly reduce coronary events (NNT 167), and cut triglycerides by about 15%. It is the most sober read of the evidence: fish oil is a triglyceride tool, not a broad heart-protection pill.", "highlight": "increasing LCn3 slightly reduces risk of coronary heart disease mortality and events, and reduces serum triglycerides", "apa": "Abdelhamid, A. S., Brown, T. J., Brainard, J. S., Biswas, P., Thorpe, G. C., Moore, H. J., Deane, K. H., Summerbell, C. D., Worthington, H. V., Song, F., &amp; Hooper, L. (2020). Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease. <i>Cochrane Database of Systematic Reviews</i>, <i>2020</i>(3). <a href=\"https://doi.org/10.1002/14651858.CD003177.pub5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD003177.pub5</a>"}, {"title": "Omega-3 Fatty Acids for the Management of Hypertriglyceridemia: A Science Advisory From the American Heart Association", "authors": "Skulas-Ray AC, Wilson PWF, Harris WS, et al.", "year": 2019, "journal": "Circulation", "doi": "10.1161/CIR.0000000000000709", "pmid": "31422671", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31422671/", "type": "guideline", "summary": "This American Heart Association science advisory reviews trial data on prescription-strength omega-3 (about 4 g/day EPA+DHA or EPA alone) for high triglycerides. At 4 g/day, omega-3 lowers very high triglycerides by 30% or more, and EPA-only cut major cardiovascular events by 25% in REDUCE-IT among statin-treated high-risk patients. These results apply to pharmacological doses in people with high triglycerides, not to a typical 1 g fish oil capsule.", "highlight": "In treatment of very high triglycerides with 4 g/d, EPA+DHA agents reduce triglycerides by ≥30%", "apa": "Skulas-Ray, A. C., Wilson, P. W., Harris, W. S., Brinton, E. A., Kris-Etherton, P. M., Richter, C. K., Jacobson, T. A., Engler, M. B., Miller, M., Robinson, J. G., Blum, C. B., Rodriguez-Leyva, D., de Ferranti, S. D., Welty, F. K., &amp; On behalf of the American Heart Association Council on Arteriosclerosis, Thrombosis and Vascular Biology; Council on Lifestyle and Cardiometabolic Health; Council on Cardiovascular Disease in the Young; Council on Cardiovascular and Stroke Nursing; and Council on Clinical Cardiology (2019). Omega-3 Fatty Acids for the Management of Hypertriglyceridemia: A Science Advisory From the American Heart Association. <i>Circulation</i>, <i>140</i>(12). <a href=\"https://doi.org/10.1161/CIR.0000000000000709\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/CIR.0000000000000709</a>"}]}, {"id": "d3", "label": "Vitamin D3", "title": "Vitamin D3", "tier": "supplements", "group": null, "blurb": "Blueprint: 2,000 IU in the Essential Capsules.", "sources": [{"title": "Vitamin D Supplements and Prevention of Cancer and Cardiovascular Disease", "authors": "Manson JE, Cook NR, Lee IM, et al.", "year": 2019, "journal": "The New England Journal of Medicine", "doi": "10.1056/NEJMoa1809944", "pmid": "30415629", "pmcid": "PMC6425757", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6425757/", "type": "RCT", "summary": "The VITAL trial randomized 25,871 US adults aged 50+ (men) or 55+ (women) to 2,000 IU/day vitamin D3 or placebo, following them for a median of 5.3 years. Vitamin D3 did not lower invasive cancer (HR 0.96) or major cardiovascular events (HR 0.97), and all-cause mortality was unchanged (HR 0.99), though cancer death showed a non-significant trend (HR 0.83). Participants were mostly not vitamin D deficient, so the results argue against routine D3 for disease prevention in replete adults rather than against correcting a deficiency.", "highlight": "Supplementation with vitamin D did not result in a lower incidence of invasive cancer or cardiovascular events than placebo.", "apa": "Manson, J. E., Cook, N. R., Lee, I.-M., Christen, W., Bassuk, S. S., Mora, S., Gibson, H., Gordon, D., Copeland, T., D’Agostino, D., Friedenberg, G., Ridge, C., Bubes, V., Giovannucci, E. L., Willett, W. C., &amp; Buring, J. E. (2019). Vitamin D Supplements and Prevention of Cancer and Cardiovascular Disease. <i>New England Journal of Medicine</i>, <i>380</i>(1), 33–44. <a href=\"https://doi.org/10.1056/NEJMoa1809944\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1056/NEJMoa1809944</a>"}, {"title": "Vitamin D supplementation to prevent acute respiratory tract infections: systematic review and meta-analysis of individual participant data", "authors": "Martineau AR, Jolliffe DA, Hooper RL, et al.", "year": 2017, "journal": "BMJ", "doi": "10.1136/bmj.i6583", "pmid": "28202713", "pmcid": "PMC5310969", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5310969/", "type": "meta-analysis", "summary": "This individual-participant-data meta-analysis pooled 25 randomized, double-blind, placebo-controlled trials covering 11,321 people aged 0-95. Vitamin D cut the odds of an acute respiratory infection by 12% overall (OR 0.88), and by 70% in people who started out severely deficient (below 25 nmol/L) and took it daily or weekly. Large monthly or yearly bolus doses did not help, so steady daily dosing matters, and the biggest gains go to people who are deficient.", "highlight": "Patients who were very vitamin D deficient and those not receiving bolus doses experienced the most benefit.", "apa": "Martineau, A. R., Jolliffe, D. A., Hooper, R. L., Greenberg, L., Aloia, J. F., Bergman, P., Dubnov-Raz, G., Esposito, S., Ganmaa, D., Ginde, A. A., Goodall, E. C., Grant, C. C., Griffiths, C. J., Janssens, W., Laaksi, I., Manaseki-Holland, S., Mauger, D., Murdoch, D. R., Neale, R., . . . Camargo, C. A. (2017). Vitamin D supplementation to prevent acute respiratory tract infections: systematic review and meta-analysis of individual participant data. <i>BMJ</i>, i6583. <a href=\"https://doi.org/10.1136/bmj.i6583\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bmj.i6583</a>"}, {"title": "The D-Health Trial: a randomised controlled trial of the effect of vitamin D on mortality", "authors": "Neale RE, Baxter C, Romero BD, et al.", "year": 2022, "journal": "The Lancet Diabetes & Endocrinology", "doi": "10.1016/S2213-8587(21)00345-4", "pmid": "35026158", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/35026158/", "type": "RCT", "summary": "D-Health randomized 21,315 Australians aged 60 and older to 60,000 IU of vitamin D3 or placebo once a month for 5 years. Vitamin D did not reduce deaths from any cause (5.3% vs 5.1%; HR 1.04), and exploratory analyses hinted at more cancer deaths. Most participants were not deficient to begin with, so for people with adequate levels, high-dose monthly D3 is not a longevity tool.", "highlight": "Administering vitamin D3 monthly to unscreened older people did not reduce all-cause mortality.", "apa": "Neale, R. E., Baxter, C., Romero, B. D., McLeod, D. S. A., English, D. R., Armstrong, B. K., Ebeling, P. R., Hartel, G., Kimlin, M. G., O&#x27;Connell, R., van der Pols, J. C., Venn, A. J., Webb, P. M., Whiteman, D. C., &amp; Waterhouse, M. (2022). The D-Health Trial: a randomised controlled trial of the effect of vitamin D on mortality. <i>The Lancet Diabetes &amp;amp; Endocrinology</i>, <i>10</i>(2), 120–128. <a href=\"https://doi.org/10.1016/S2213-8587(21)00345-4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/S2213-8587(21)00345-4</a>"}]}, {"id": "b12", "label": "Vitamin B12", "title": "Vitamin B12", "tier": "supplements", "group": null, "blurb": "Blueprint: 125 mcg methylcobalamin in the Essential Capsules.", "sources": [{"title": "Oral vitamin B12 versus intramuscular vitamin B12 for vitamin B12 deficiency", "authors": "Wang H, Li L, Qin LL, et al.", "year": 2018, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD004655.pub3", "pmid": "29543316", "pmcid": "PMC6494183", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6494183/", "type": "systematic review", "summary": "This Cochrane review found three randomized trials (153 people) comparing oral and intramuscular B12 for deficiency over 3-4 months. High-dose oral B12 (1,000-2,000 mcg/day) raised blood B12 as well as injections did, and cost less. The evidence is low quality because the trials were few and small, and none measured symptoms or quality of life.", "highlight": "Low quality evidence shows oral and IM vitamin B12 having similar effects in terms of normalising serum vitamin B12 levels, but oral treatment costs less.", "apa": "Wang, H., Li, L., Qin, L. L., Song, Y., Vidal-Alaball, J., &amp; Liu, T. H. (2018). Oral vitamin B\n                    12\n                    versus intramuscular vitamin B\n                    12\n                    for vitamin B\n                    12\n                    deficiency. <i>Cochrane Database of Systematic Reviews</i>, <i>2018</i>(3). <a href=\"https://doi.org/10.1002/14651858.CD004655.pub3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD004655.pub3</a>"}, {"title": "Long-term Metformin Use and Vitamin B12 Deficiency in the Diabetes Prevention Program Outcomes Study", "authors": "Aroda VR, Edelstein SL, Goldberg RB, et al.", "year": 2016, "journal": "Journal of Clinical Endocrinology and Metabolism", "doi": "10.1210/jc.2015-3754", "pmid": "26900641", "pmcid": "PMC4880159", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4880159/", "type": "cohort", "summary": "This secondary analysis of the Diabetes Prevention Program followed about 2,000 adults with prediabetes randomized to metformin or placebo, with B12 measured at 5 and 13 years. Each year of metformin use raised the odds of B12 deficiency by 13%, and low or borderline B12 was about twice as common on metformin at 5 years (19.1% vs 9.5%). Anyone on long-term metformin should have B12 checked; the study shows risk, not that routine supplements fix outcomes.", "highlight": "Long-term use of metformin in DPPOS was associated with biochemical B12 deficiency and anemia.", "apa": "Aroda, V. R., Edelstein, S. L., Goldberg, R. B., Knowler, W. C., Marcovina, S. M., Orchard, T. J., Bray, G. A., Schade, D. S., Temprosa, M. G., White, N. H., Crandall, J. P., &amp; the Diabetes Prevention Program Research Group (2016). Long-term Metformin Use and Vitamin B12 Deficiency in the Diabetes Prevention Program Outcomes Study. <i>The Journal of Clinical Endocrinology &amp;amp; Metabolism</i>, <i>101</i>(4), 1754–1761. <a href=\"https://doi.org/10.1210/jc.2015-3754\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1210/jc.2015-3754</a>"}, {"title": "How prevalent is vitamin B(12) deficiency among vegetarians?", "authors": "Pawlak R, Parrott SJ, Raj S, et al.", "year": 2013, "journal": "Nutrition Reviews", "doi": "10.1111/nure.12001", "pmid": "23356638", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23356638/", "type": "review", "summary": "This literature review pulled 18 studies that measured B12 deficiency in vegetarians and vegans using sensitive markers (methylmalonic acid, holotranscobalamin). Deficiency rates were high across groups, including 11-90% of older adults and 62% of pregnant women, and were higher in vegans than vegetarians. It is a narrative review of varied studies, but the message is consistent: people eating little or no animal food should take B12.", "highlight": "vegetarians develop B12 depletion or deficiency regardless of demographic characteristics, place of residency, age, or type of vegetarian diet", "apa": "Pawlak, R., Parrott, S. J., Raj, S., Cullum-Dugan, D., &amp; Lucus, D. (2013). How prevalent is vitamin B12deficiency among vegetarians? <i>Nutrition Reviews</i>, <i>71</i>(2), 110–117. <a href=\"https://doi.org/10.1111/nure.12001\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1111/nure.12001</a>"}]}, {"id": "bcomplex", "label": "B vitamins + folate", "title": "B vitamins & folate", "tier": "supplements", "group": null, "blurb": "Blueprint: B1, B2, B3, B5, B6, biotin and methylfolate in the Essential Capsules.", "sources": [{"title": "Homocysteine-lowering by B vitamins slows the rate of accelerated brain atrophy in mild cognitive impairment: a randomized controlled trial", "authors": "Smith AD, Smith SM, de Jager CA, et al.", "year": 2010, "journal": "PLoS One", "doi": "10.1371/journal.pone.0012244", "pmid": "20838622", "pmcid": "PMC2935890", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2935890/", "type": "RCT", "summary": "VITACOG was a 2-year randomized, double-blind trial giving 271 adults over 70 with mild cognitive impairment folic acid 0.8 mg, B12 0.5 mg and B6 20 mg daily or placebo, with MRI scans in 168 completers. Brain shrinkage slowed from 1.08% to 0.76% per year, and by 53% in people whose starting homocysteine was above 13 umol/L. The benefit was concentrated in people with high homocysteine, and brain volume is a surrogate; the trial did not show fewer dementia cases.", "highlight": "The accelerated rate of brain atrophy in elderly with mild cognitive impairment can be slowed by treatment with homocysteine-lowering B vitamins.", "apa": "Smith, A. D., Smith, S. M., de Jager, C. A., Whitbread, P., Johnston, C., Agacinski, G., Oulhaj, A., Bradley, K. M., Jacoby, R., &amp; Refsum, H. (2010). Homocysteine-Lowering by B Vitamins Slows the Rate of Accelerated Brain Atrophy in Mild Cognitive Impairment: A Randomized Controlled Trial. <i>PLoS ONE</i>, <i>5</i>(9), e12244. <a href=\"https://doi.org/10.1371/journal.pone.0012244\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1371/journal.pone.0012244</a>"}, {"title": "Efficacy of folic acid therapy in primary prevention of stroke among adults with hypertension in China: the CSPPT randomized clinical trial", "authors": "Huo Y, Li J, Qin X, et al.", "year": 2015, "journal": "JAMA", "doi": "10.1001/jama.2015.2274", "pmid": "25771069", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25771069/", "type": "RCT", "summary": "The China Stroke Primary Prevention Trial randomized 20,702 adults with high blood pressure to enalapril plus 0.8 mg folic acid or enalapril alone for a median of 4.5 years. Adding folic acid cut first strokes by 21% (2.7% vs 3.4%; HR 0.79). China has no folic acid food fortification, so baseline folate was low; the benefit is unlikely to be as large in countries like the US where flour is fortified.", "highlight": "the combined use of enalapril and folic acid, compared with enalapril alone, significantly reduced the risk of first stroke", "apa": "Huo, Y., Li, J., Qin, X., Huang, Y., Wang, X., Gottesman, R. F., Tang, G., Wang, B., Chen, D., He, M., Fu, J., Cai, Y., Shi, X., Zhang, Y., Cui, Y., Sun, N., Li, X., Cheng, X., Wang, J., . . . Hou, F. F. (2015). Efficacy of Folic Acid Therapy in Primary Prevention of Stroke Among Adults With Hypertension in China. <i>Jama</i>, <i>313</i>(13), 1325. <a href=\"https://doi.org/10.1001/jama.2015.2274\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2015.2274</a>"}, {"title": "Homocysteine-lowering interventions for preventing cardiovascular events", "authors": "Martí-Carvajal AJ, Solà I, Lathyris D, Dayer M", "year": 2017, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD006612.pub5", "pmid": "28816346", "pmcid": "PMC6483699", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6483699/", "type": "meta-analysis", "summary": "This Cochrane review pooled 15 randomized trials (71,422 people) of B6, folic acid and/or B12 given to lower homocysteine. B vitamins did not reduce heart attacks or deaths, but slightly lowered stroke risk (4.3% vs 5.1%; RR 0.90). Lowering homocysteine with B vitamins is not a heart-attack prevention strategy; the small stroke benefit is the only consistent signal.", "highlight": "there were no differences in effects of homocysteine-lowering interventions in the form of supplements of vitamins B6, B9 or B12", "apa": "Martí-Carvajal, A. J., Solà, I., Lathyris, D., &amp; Dayer, M. (2017). Homocysteine-lowering interventions for preventing cardiovascular events. <i>Cochrane Database of Systematic Reviews</i>, <i>2021</i>(9). <a href=\"https://doi.org/10.1002/14651858.CD006612.pub5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD006612.pub5</a>"}]}, {"id": "vitaminc", "label": "Vitamin C", "title": "Vitamin C", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Vitamin C for preventing and treating the common cold", "authors": "Hemilä H, Chalker E", "year": 2013, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD000980.pub4", "pmid": "23440782", "pmcid": "PMC8078152", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8078152/", "type": "meta-analysis", "summary": "This Cochrane review pooled placebo-controlled trials of at least 0.2 g/day vitamin C, including 29 comparisons with 11,306 people for cold incidence and 31 comparisons for cold duration. Regular use did not prevent colds in the general population (RR 0.97) but shortened colds by 8% in adults and 14% in children, and halved cold risk in people under heavy physical stress such as marathon runners and soldiers. Starting vitamin C only after symptoms begin showed no consistent benefit, so the payoff comes from taking it daily, and it is small.", "highlight": "In adults the duration of colds was reduced by 8% (3% to 12%) and in children by 14% (7% to 21%).", "apa": "Hemilä, H., &amp; Chalker, E. (2013). Vitamin C for preventing and treating the common cold. <i>Cochrane Database of Systematic Reviews</i>, <i>2013</i>(5). <a href=\"https://doi.org/10.1002/14651858.CD000980.pub4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD000980.pub4</a>"}, {"title": "Effects of vitamin C supplementation on blood pressure: a meta-analysis of randomized controlled trials", "authors": "Juraschek SP, Guallar E, Appel LJ, Miller ER", "year": 2012, "journal": "American Journal of Clinical Nutrition", "doi": "10.3945/ajcn.111.027995", "pmid": "22492364", "pmcid": "PMC3325833", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3325833/", "type": "meta-analysis", "summary": "This meta-analysis pooled 29 randomized controlled trials (median 500 mg/day for a median of 8 weeks, 10-120 people each) of oral vitamin C and blood pressure. Vitamin C lowered systolic pressure by 3.84 mm Hg and diastolic by 1.48 mm Hg on average. The trials were small and short, and no long-term trials have shown fewer heart attacks or strokes.", "highlight": "The pooled changes in SBP and DBP were -3.84 mm Hg (95% CI: -5.29, -2.38 mm Hg; P < 0.01) and -1.48 mm Hg", "apa": "Juraschek, S. P., Guallar, E., Appel, L. J., &amp; Miller, E. R. (2012). Effects of vitamin C supplementation on blood pressure: a meta-analysis of randomized controlled trials. <i>The American Journal of Clinical Nutrition</i>, <i>95</i>(5), 1079–1088. <a href=\"https://doi.org/10.3945/ajcn.111.027995\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3945/ajcn.111.027995</a>"}, {"title": "Extra Dose of Vitamin C Based on a Daily Supplementation Shortens the Common Cold: A Meta-Analysis of 9 Randomized Controlled Trials", "authors": "Ran L, Zhao W, Wang J, et al.", "year": 2018, "journal": "BioMed Research International", "doi": "10.1155/2018/1837634", "pmid": "30069463", "pmcid": "PMC6057395", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6057395/", "type": "meta-analysis", "summary": "This meta-analysis of 9 randomized placebo-controlled trials asked whether an extra dose of vitamin C at the start of a cold helps people who already take it daily. The extra dose shortened colds by about half a day (MD -0.56 days) and reduced time stuck indoors, fever and chills. The effect is small and the pooled trials vary in dose and quality, so it is a modest, low-cost option rather than a cure.", "highlight": "Extra doses of vitamin C could benefit some patients who contract the common cold despite taking daily vitamin C supplements.", "apa": "Ran, L., Zhao, W., Wang, J., Wang, H., Zhao, Y., Tseng, Y., &amp; Bu, H. (2018). Extra Dose of Vitamin C Based on a Daily Supplementation Shortens the Common Cold: A Meta-Analysis of 9 Randomized Controlled Trials. <i>BioMed Research International</i>, <i>2018</i>, 1–12. <a href=\"https://doi.org/10.1155/2018/1837634\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1155/2018/1837634</a>"}]}, {"id": "vitamine", "label": "Vitamin E", "title": "Vitamin E", "tier": "supplements", "group": null, "blurb": "Blueprint: 67 mg d-alpha-tocopherol in the Essential Capsules.", "sources": [{"title": "Vitamin E and the risk of prostate cancer: the Selenium and Vitamin E Cancer Prevention Trial (SELECT)", "authors": "Klein EA, Thompson IM, Tangen CM, et al.", "year": 2011, "journal": "JAMA", "doi": "10.1001/jama.2011.1437", "pmid": "21990298", "pmcid": "PMC4169010", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4169010/", "type": "RCT", "summary": "SELECT randomized 35,533 healthy men (aged 55 or older, or 50 or older for Black men) to 400 IU/day vitamin E, selenium, both, or placebo, with follow-up extended after the supplements were stopped. Men taking vitamin E alone had 17% more prostate cancer than placebo (HR 1.17), about 1.6 extra cases per 1,000 person-years. This is direct trial evidence of harm from a common supplement dose in healthy men.", "highlight": "Dietary supplementation with vitamin E significantly increased the risk of prostate cancer among healthy men.", "apa": "Klein, E. A., Thompson, I. M., Tangen, C. M., Crowley, J. J., Lucia, M. S., Goodman, P. J., Minasian, L. M., Ford, L. G., Parnes, H. L., Gaziano, J. M., Karp, D. D., Lieber, M. M., Walther, P. J., Klotz, L., Parsons, J. K., Chin, J. L., Darke, A. K., Lippman, S. M., Goodman, G. E., . . . Baker, L. H. (2011). Vitamin E and the Risk of Prostate Cancer. <i>Jama</i>, <i>306</i>(14), 1549. <a href=\"https://doi.org/10.1001/jama.2011.1437\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2011.1437</a>"}, {"title": "Vitamins E and C in the prevention of cardiovascular disease in men: the Physicians' Health Study II randomized controlled trial", "authors": "Sesso HD, Buring JE, Christen WG, et al.", "year": 2008, "journal": "JAMA", "doi": "10.1001/jama.2008.600", "pmid": "18997197", "pmcid": "PMC2586922", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2586922/", "type": "RCT", "summary": "The Physicians' Health Study II randomized 14,641 US male physicians aged 50 and older to 400 IU vitamin E every other day and/or 500 mg vitamin C daily, followed for a mean 8 years. Vitamin E had no effect on major cardiovascular events (HR 1.01) or death, and was linked to more hemorrhagic strokes (HR 1.74). The participants were healthy, well-nourished doctors, but the result is a clear null for heart protection.", "highlight": "neither vitamin E nor vitamin C supplementation reduced the risk of major cardiovascular events", "apa": "Sesso, H. D. (2008). Vitamins E and C in the Prevention of Cardiovascular Disease in Men. <i>Jama</i>, <i>300</i>(18), 2123. <a href=\"https://doi.org/10.1001/jama.2008.600\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2008.600</a>"}, {"title": "Meta-analysis: high-dosage vitamin E supplementation may increase all-cause mortality", "authors": "Miller ER, Pastor-Barriuso R, Dalal D, et al.", "year": 2005, "journal": "Annals of Internal Medicine", "doi": "10.7326/0003-4819-142-1-200501040-00110", "pmid": "15537682", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/15537682/", "type": "meta-analysis", "summary": "This dose-response meta-analysis pooled 19 randomized trials with 135,967 participants taking 16.5-2,000 IU/day of vitamin E. Doses of 400 IU/day or more raised deaths by 39 per 10,000 people, with risk starting to climb above about 150 IU/day. Many high-dose trials enrolled people with chronic disease, so the size of the harm in healthy adults is uncertain, but no trial shows a benefit that would justify the risk.", "highlight": "High-dosage (> or =400 IU/d) vitamin E supplements may increase all-cause mortality and should be avoided.", "apa": "Miller, E. R., Pastor-Barriuso, R., Dalal, D., Riemersma, R. A., Appel, L. J., &amp; Guallar, E. (2005). Meta-Analysis: High-Dosage Vitamin E Supplementation May Increase All-Cause Mortality. <i>Annals of Internal Medicine</i>, <i>142</i>(1), 37–46. <a href=\"https://doi.org/10.7326/0003-4819-142-1-200501040-00110\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.7326/0003-4819-142-1-200501040-00110</a>"}]}, {"id": "vitamink", "label": "Vitamin K1 + K2", "title": "Vitamin K1 + K2", "tier": "supplements", "group": null, "blurb": "Blueprint: K1, K2 MK-4 and K2 MK-7 in the Advanced Antioxidants softgel.", "sources": [{"title": "Effect of vitamin K on bone mineral density and fractures in adults: an updated systematic review and meta-analysis of randomised controlled trials", "authors": "Mott A, Bradley T, Wright K, et al.", "year": 2019, "journal": "Osteoporosis International", "doi": "10.1007/s00198-019-04949-0", "pmid": "31076817", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31076817/", "type": "meta-analysis", "summary": "This updated systematic review identified 36 randomized trials of oral vitamin K (K1 and K2 forms) on bone mineral density and fractures in adults. In postmenopausal or osteoporotic patients, vitamin K was linked to lower odds of clinical fracture (OR 0.72), but this weakened to a non-significant OR 0.76 when restricted to low risk-of-bias trials, and vertebral fractures were unchanged. The authors conclude there is no evidence vitamin K improves bone density and the fracture signal is insufficient to confirm.", "highlight": "For post-menopausal or osteoporotic patients, there is no evidence that vitamin K affects bone mineral density or vertebral fractures", "apa": "Mott, A., Bradley, T., Wright, K., Cockayne, E. S., Shearer, M. J., Adamson, J., Lanham-New, S. A., &amp; Torgerson, D. J. (2019). Effect of vitamin K on bone mineral density and fractures in adults: an updated systematic review and meta-analysis of randomised controlled trials. <i>Osteoporosis International</i>, <i>30</i>(8), 1543–1559. <a href=\"https://doi.org/10.1007/s00198-019-04949-0\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s00198-019-04949-0</a>"}, {"title": "Three-year low-dose menaquinone-7 supplementation helps decrease bone loss in healthy postmenopausal women", "authors": "Knapen MH, Drummen NE, Smit E, et al.", "year": 2013, "journal": "Osteoporosis International", "doi": "10.1007/s00198-013-2325-6", "pmid": "23525894", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23525894/", "type": "RCT", "summary": "This 3-year randomized placebo-controlled trial gave 244 healthy postmenopausal women 180 µg/day of vitamin K2 as MK-7 or placebo, measuring bone density by DXA. MK-7 improved vitamin K status and slowed the age-related decline in bone density and bone mineral content at the lumbar spine and femoral neck, but not at the total hip. It is a single trial in one population measuring bone density rather than fractures, so it supports but does not prove a fracture benefit.", "highlight": "MK-7 intake significantly improved vitamin K status and decreased the age-related decline in BMC and BMD at the lumbar spine and femoral neck", "apa": "Knapen, M. H. J., Drummen, N. E., Smit, E., Vermeer, C., &amp; Theuwissen, E. (2013). Three-year low-dose menaquinone-7 supplementation helps decrease bone loss in healthy postmenopausal women. <i>Osteoporosis International</i>, <i>24</i>(9), 2499–2507. <a href=\"https://doi.org/10.1007/s00198-013-2325-6\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s00198-013-2325-6</a>"}, {"title": "Vitamin K supplementation and vascular calcification: a systematic review and meta-analysis of randomized controlled trials", "authors": "Li T, Wang Y, Tu WP", "year": 2023, "journal": "Frontiers in Nutrition", "doi": "10.3389/fnut.2023.1115069", "pmid": "37252246", "pmcid": "PMC10218696", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10218696/", "type": "meta-analysis", "summary": "This meta-analysis pooled 14 randomized trials (1,533 patients, many with kidney or cardiovascular disease) testing vitamin K supplementation on vascular calcification. Vitamin K slowed coronary artery calcification score progression (mean difference -17.37, p = 0.04) and lowered dp-ucMGP, a marker of poor vitamin K status, with no excess adverse events. The calcification effect was small and borderline, came largely from patient populations, and the authors call for more rigorous trials.", "highlight": "VK supplementation has a significant effect on CAC scores, slowing down the progression of CAC", "apa": "Li, T., Wang, Y., &amp; Tu, W.-p. (2023). Vitamin K supplementation and vascular calcification: a systematic review and meta-analysis of randomized controlled trials. <i>Frontiers in Nutrition</i>, <i>10</i>, 1115069. <a href=\"https://doi.org/10.3389/fnut.2023.1115069\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3389/fnut.2023.1115069</a>"}]}, {"id": "magnesium", "label": "Magnesium", "title": "Magnesium", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Effects of Magnesium Supplementation on Blood Pressure: A Meta-Analysis of Randomized Double-Blind Placebo-Controlled Trials", "authors": "Zhang X, Li Y, Del Gobbo LC, et al.", "year": 2016, "journal": "Hypertension", "doi": "10.1161/HYPERTENSIONAHA.116.07664", "pmid": "27402922", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/27402922/", "type": "meta-analysis", "summary": "This meta-analysis pooled 34 randomized, double-blind, placebo-controlled trials (2,028 adults) of oral magnesium and blood pressure. A median 368 mg/day for about 3 months lowered systolic pressure by 2.00 mm Hg and diastolic by 1.78 mm Hg, and about 300 mg/day for a month was enough to see an effect. The drop is modest, and the trials varied enough that results differ across studies.", "highlight": "Our findings indicate a causal effect of Mg supplementation on lowering BPs in adults.", "apa": "Zhang, X., Li, Y., Del Gobbo, L. C., Rosanoff, A., Wang, J., Zhang, W., &amp; Song, Y. (2016). Effects of Magnesium Supplementation on Blood Pressure. <i>Hypertension</i>, <i>68</i>(2), 324–333. <a href=\"https://doi.org/10.1161/HYPERTENSIONAHA.116.07664\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/HYPERTENSIONAHA.116.07664</a>"}, {"title": "Oral magnesium supplementation for insomnia in older adults: a Systematic Review & Meta-Analysis", "authors": "Mah J, Pitre T", "year": 2021, "journal": "BMC Complementary Medicine and Therapies", "doi": "10.1186/s12906-021-03297-z", "pmid": "33865376", "pmcid": "PMC8053283", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8053283/", "type": "meta-analysis", "summary": "This systematic review found only three randomized trials (151 older adults) comparing oral magnesium with placebo for insomnia. Magnesium cut the time to fall asleep by about 17 minutes, while the 16-minute gain in total sleep time was not statistically significant. All trials had moderate-to-high risk of bias and the evidence was rated low to very low quality, so the sleep claims for magnesium rest on thin evidence.", "highlight": "Pooled analysis showed that post-intervention sleep onset latency time was 17.36", "apa": "Mah, J., &amp; Pitre, T. (2021). Oral magnesium supplementation for insomnia in older adults: a Systematic Review &amp;amp; Meta-Analysis. <i>BMC Complementary Medicine and Therapies</i>, <i>21</i>(1), 125. <a href=\"https://doi.org/10.1186/s12906-021-03297-z\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1186/s12906-021-03297-z</a>"}, {"title": "Oral Magnesium Supplementation for Treating Glucose Metabolism Parameters in People with or at Risk of Diabetes: A Systematic Review and Meta-Analysis of Double-Blind Randomized Controlled Trials", "authors": "Veronese N, Dominguez LJ, Pizzol D, et al.", "year": 2021, "journal": "Nutrients", "doi": "10.3390/nu13114074", "pmid": "34836329", "pmcid": "PMC8619199", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8619199/", "type": "meta-analysis", "summary": "This meta-analysis pooled double-blind randomized trials of oral magnesium versus placebo in people with diabetes or at high risk of it. Magnesium lowered fasting glucose in people with diabetes, and in at-risk people it improved glucose after a 2-hour glucose tolerance test and markers of insulin sensitivity. The benefit is clearest in people with diabetes or prediabetes, who often have low magnesium; it says little about healthy people with normal levels.", "highlight": "Mg supplementation may improve insulin-sensitivity parameters in those at high risk of diabetes", "apa": "Veronese, N., Dominguez, L. J., Pizzol, D., Demurtas, J., Smith, L., &amp; Barbagallo, M. (2021). Oral Magnesium Supplementation for Treating Glucose Metabolism Parameters in People with or at Risk of Diabetes: A Systematic Review and Meta-Analysis of Double-Blind Randomized Controlled Trials. <i>Nutrients</i>, <i>13</i>(11), 4074. <a href=\"https://doi.org/10.3390/nu13114074\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu13114074</a>"}]}, {"id": "zinccopper", "label": "Zinc + Copper", "title": "Zinc + copper", "tier": "supplements", "group": null, "blurb": "Blueprint: 15 mg zinc bisglycinate in the Essential Capsules. Copper is my addition: long-term zinc without copper can cause copper deficiency.", "sources": [{"title": "Zinc lozenges and the common cold: a meta-analysis comparing zinc acetate and zinc gluconate, and the role of zinc dosage.", "authors": "Hemilä H", "year": 2017, "journal": "JRSM Open", "doi": "10.1177/2054270417694291", "pmid": "28515951", "pmcid": "PMC5418896", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5418896/", "type": "meta-analysis", "summary": "This meta-analysis pooled seven placebo-controlled trials (575 people with natural colds) that used zinc lozenges at more than 75 mg/day. Colds were 33% shorter on average with zinc, with acetate and gluconate lozenges performing similarly. The benefit applies to short courses started at the first sign of a cold, and doses above 100 mg/day added nothing.", "highlight": "The mean common cold duration was 33% (95% CI 21% to 45%) shorter for the zinc groups of the seven included trials.", "apa": "Hemilä, H. (2017). Zinc lozenges and the common cold: a meta-analysis comparing zinc acetate and zinc gluconate, and the role of zinc dosage. <i>JRSM Open</i>, <i>8</i>(5), 2054270417694291. <a href=\"https://doi.org/10.1177/2054270417694291\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1177/2054270417694291</a>"}, {"title": "A randomized, placebo-controlled, clinical trial of high-dose supplementation with vitamins C and E, beta carotene, and zinc for age-related macular degeneration and vision loss: AREDS report no. 8.", "authors": "Age-Related Eye Disease Study Research Group", "year": 2001, "journal": "Arch Ophthalmol", "doi": "10.1001/archopht.119.10.1417", "pmid": "11594942", "pmcid": "PMC1462955", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC1462955/", "type": "RCT", "summary": "AREDS randomized 3,640 adults aged 55-80 to antioxidants, zinc 80 mg plus copper 2 mg, both, or placebo for an average of 6.3 years. Antioxidants plus zinc cut the odds of progressing to advanced macular degeneration (OR 0.72), with the clearest benefit in people already at higher risk. Copper was added specifically to prevent zinc-induced copper deficiency, and the benefit was not shown in people with only early AMD.", "highlight": "demonstrated a statistically significant odds reduction for the development of advanced AMD with antioxidants plus zinc", "apa": "Age-Related Eye Disease Study Research Group (2001). A Randomized, Placebo-Controlled, Clinical Trial of High-Dose Supplementation With Vitamins C and E, Beta Carotene, and Zinc for Age-Related Macular Degeneration and Vision Loss. <i>Archives of Ophthalmology</i>, <i>119</i>(10), 1417. <a href=\"https://doi.org/10.1001/archopht.119.10.1417\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/archopht.119.10.1417</a>"}, {"title": "Zinc-Induced Hematologic Toxicities: A Systematic Review of Descriptive Studies.", "authors": "Dutta A, Chaudhary V, Kumari S, et al.", "year": 2026, "journal": "Biol Trace Elem Res", "doi": "10.1007/s12011-026-05136-z", "pmid": "42087025", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/42087025/", "type": "systematic review", "summary": "This systematic review collected 37 published cases (1972-2025) of blood disorders caused by excess zinc from supplements, denture creams, or swallowed coins. Serum copper was low in every patient, with anemia and neutropenia common at doses from about 50 mg/day up to over 1,500 mg/day. It is case-level evidence and rare, but it is the reason long-term zinc should be paired with copper; stopping zinc and adding copper usually fixed the blood counts, while nerve damage recovered slowly or incompletely.", "highlight": "Zinc-induced hematologic toxicity is an uncommon but underrecognized and largely reversible condition.", "apa": "Dutta, A., Chaudhary, V., Kumari, S., Rohita, Sharma, K. K., &amp; Pal, B. (2026). Zinc-Induced Hematologic Toxicities: A Systematic Review of Descriptive Studies. <i>Biological Trace Element Research</i>, <i>204</i>(9), 6628–6642. <a href=\"https://doi.org/10.1007/s12011-026-05136-z\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s12011-026-05136-z</a>"}]}, {"id": "selenium", "label": "Selenium", "title": "Selenium", "tier": "supplements", "group": null, "blurb": "Blueprint: 28 mcg selenomethionine in the Essential Capsules.", "sources": [{"title": "Effect of selenium and vitamin E on risk of prostate cancer and other cancers: the Selenium and Vitamin E Cancer Prevention Trial (SELECT).", "authors": "Lippman SM, Klein EA, Goodman PJ, et al.", "year": 2009, "journal": "JAMA", "doi": "10.1001/jama.2008.864", "pmid": "19066370", "pmcid": "PMC3682779", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3682779/", "type": "RCT", "summary": "SELECT randomized 35,533 healthy men to 200 mcg/day selenium, vitamin E, both, or placebo, with a median follow-up of 5.5 years. Selenium did not reduce prostate cancer (HR 1.04) or any other prespecified cancer. There was a non-significant uptick in type 2 diabetes with selenium, so in people who already get enough, extra selenium offers no cancer protection.", "highlight": "Selenium or vitamin E, alone or in combination at the doses and formulations used, did not prevent prostate cancer", "apa": "Lippman, S. M., Klein, E. A., Goodman, P. J., Lucia, M. S., Thompson, I. M., Ford, L. G., Parnes, H. L., Minasian, L. M., Gaziano, J. M., Hartline, J. A., Parsons, J. K., Bearden, J. D., Crawford, E. D., Goodman, G. E., Claudio, J., Winquist, E., Cook, E. D., Karp, D. D., Walther, P., . . . Coltman, C. A. (2009). Effect of Selenium and Vitamin E on Risk of Prostate Cancer and Other Cancers. <i>Jama</i>, <i>301</i>(1), 39. <a href=\"https://doi.org/10.1001/jama.2008.864\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2008.864</a>"}, {"title": "Selenium Supplementation in Patients with Hashimoto Thyroiditis: A Systematic Review and Meta-Analysis of Randomized Clinical Trials.", "authors": "Huwiler VV, Maissen-Abgottspon S, Stanga Z, et al.", "year": 2024, "journal": "Thyroid", "doi": "10.1089/thy.2023.0556", "pmid": "38243784", "pmcid": "PMC10951571", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10951571/", "type": "meta-analysis", "summary": "This meta-analysis of 35 randomized trials looked at selenium supplements in people with Hashimoto thyroiditis. Selenium modestly lowered TSH in people not on thyroid hormone (SMD -0.21) and lowered TPO antibodies more clearly (SMD -0.96), with side effects similar to placebo. These are lab markers rather than symptoms or disease progression, and the antibody results varied a lot between trials (I2 = 90%).", "highlight": "In people with HT without THRT, selenium was effective and safe in lowering TSH, TPOAb, and MDA levels.", "apa": "Huwiler, V. V., Maissen-Abgottspon, S., Stanga, Z., Mühlebach, S., Trepp, R., Bally, L., &amp; Bano, A. (2024). Selenium Supplementation in Patients with Hashimoto Thyroiditis: A Systematic Review and Meta-Analysis of Randomized Clinical Trials. <i>Thyroid®</i>, <i>34</i>(3), 295–313. <a href=\"https://doi.org/10.1089/thy.2023.0556\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1089/thy.2023.0556</a>"}, {"title": "Selenium intake, status, and health: a complex relationship.", "authors": "Rayman MP", "year": 2020, "journal": "Hormones (Athens)", "doi": "10.1007/s42000-019-00125-5", "pmid": "31388899", "pmcid": "PMC7033057", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7033057/", "type": "review", "summary": "This review by a leading selenium researcher covers how both too little and too much selenium affect health worldwide. Many outcomes, including mortality, follow a U-shaped curve, with harm at both low and high selenium status. The practical point is that selenium helps people who are low and may harm people who are already replete, so baseline status and dose matter more than the supplement itself.", "highlight": "Some health effects, such as increased mortality, are associated with both low and high Se status.", "apa": "Rayman, M. P. (2019). Selenium intake, status, and health: a complex relationship. <i>Hormones</i>, <i>19</i>(1), 9–14. <a href=\"https://doi.org/10.1007/s42000-019-00125-5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s42000-019-00125-5</a>"}]}, {"id": "iodine", "label": "Iodine", "title": "Iodine", "tier": "supplements", "group": null, "blurb": "Blueprint: 200 mcg in the Essential Capsules.", "sources": [{"title": "Iodine deficiency and thyroid disorders.", "authors": "Zimmermann MB, Boelaert K", "year": 2015, "journal": "Lancet Diabetes Endocrinol", "doi": "10.1016/S2213-8587(14)70225-6", "pmid": "25591468", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25591468/", "type": "review", "summary": "This review summarizes how population iodine intake shapes thyroid disease in adults. Severe deficiency causes goitre and hypothyroidism, while milder deficiency drives nodular goitre and hyperthyroidism over time; correcting it brings a small, possibly temporary rise in subclinical hypothyroidism and thyroid autoimmunity. The goal is adequate intake, not more, and the review is narrative rather than a pooled analysis.", "highlight": "Iodine deficiency early in life impairs cognition and growth, but iodine status is also a key determinant of thyroid disorders in adults.", "apa": "Zimmermann, M. B., &amp; Boelaert, K. (2015). Iodine deficiency and thyroid disorders. <i>The Lancet Diabetes &amp;amp; Endocrinology</i>, <i>3</i>(4), 286–295. <a href=\"https://doi.org/10.1016/S2213-8587(14)70225-6\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/S2213-8587(14)70225-6</a>"}, {"title": "Systematic review and meta-analysis of iodine nutrition in modern vegan and vegetarian diets.", "authors": "Eveleigh ER, Coneyworth L, Welham SJM", "year": 2023, "journal": "Br J Nutr", "doi": "10.1017/S000711452300051X", "pmid": "36912094", "pmcid": "PMC10551477", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10551477/", "type": "meta-analysis", "summary": "This systematic review and meta-analysis pooled 11 observational studies covering 4,421 adults on vegan, vegetarian, or omnivorous diets. Vegans had the lowest iodine intake (about 17 mcg/day versus a 150 mcg/day adult target) and none of the diet groups reached the optimal urinary iodine range. Risk was worst where salt is not routinely iodized, so plant-based eaters should use iodized salt or a modest supplement rather than rely on food.", "highlight": "Vegetarians and particularly vegans living in countries with no current USI programme continue to have increased risk of low iodine status", "apa": "Eveleigh, E. R., Coneyworth, L., &amp; Welham, S. J. M. (2023). Systematic review and meta-analysis of iodine nutrition in modern vegan and vegetarian diets. <i>British Journal of Nutrition</i>, <i>130</i>(9), 1580–1594. <a href=\"https://doi.org/10.1017/S000711452300051X\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1017/S000711452300051X</a>"}, {"title": "Effect of inadequate iodine status in UK pregnant women on cognitive outcomes in their children: results from the Avon Longitudinal Study of Parents and Children (ALSPAC).", "authors": "Bath SC, Steer CD, Golding J, et al.", "year": 2013, "journal": "Lancet", "doi": "10.1016/S0140-6736(13)60436-5", "pmid": "23706508", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23706508/", "type": "cohort", "summary": "This cohort study measured iodine in first-trimester urine from 1,040 UK pregnant women and followed their children's IQ and reading into school age. Children of mothers with low iodine were more likely to score in the bottom quarter for verbal IQ (OR 1.58) and reading accuracy (OR 1.69). It is observational, so it shows association rather than proof, but it shows that even mild deficiency in a wealthy country can matter.", "highlight": "Our results show the importance of adequate iodine status during early gestation and emphasise the risk that iodine deficiency can pose to the developing infant", "apa": "Bath, S. C., Steer, C. D., Golding, J., Emmett, P., &amp; Rayman, M. P. (2013). Effect of inadequate iodine status in UK pregnant women on cognitive outcomes in their children: results from the Avon Longitudinal Study of Parents and Children (ALSPAC). <i>The Lancet</i>, <i>382</i>(9889), 331–337. <a href=\"https://doi.org/10.1016/S0140-6736(13)60436-5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/S0140-6736(13)60436-5</a>"}]}, {"id": "calcium_mn", "label": "Calcium + Manganese", "title": "Calcium & manganese", "tier": "supplements", "group": null, "blurb": "Blueprint: small doses (50 mg calcium, 1 mg manganese) in the Essential Capsules.", "sources": [{"title": "Calcium intake and risk of fracture: systematic review.", "authors": "Bolland MJ, Leung W, Tai V, et al.", "year": 2015, "journal": "BMJ", "doi": "10.1136/bmj.h4580", "pmid": "26420387", "pmcid": "PMC4784799", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4784799/", "type": "systematic review", "summary": "This systematic review covered 44 cohort studies of dietary calcium and 26 randomized trials of calcium supplements in adults over 50. Supplements cut total fractures by about 11% (RR 0.89) across all trials, but the best-quality trials (44,505 people) showed no effect at any site, and dietary calcium was not linked to fracture risk. High-dose calcium is a weak fracture strategy; a low dose that fills a dietary gap is the defensible use.", "highlight": "Evidence that calcium supplements prevent fractures is weak and inconsistent.", "apa": "Bolland, M. J., Leung, W., Tai, V., Bastin, S., Gamble, G. D., Grey, A., &amp; Reid, I. R. (2015). Calcium intake and risk of fracture: systematic review. <i>BMJ</i>, h4580. <a href=\"https://doi.org/10.1136/bmj.h4580\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bmj.h4580</a>"}, {"title": "Effect of calcium supplements on risk of myocardial infarction and cardiovascular events: meta-analysis.", "authors": "Bolland MJ, Avenell A, Baron JA, et al.", "year": 2010, "journal": "BMJ", "doi": "10.1136/bmj.c3691", "pmid": "20671013", "pmcid": "PMC2912459", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2912459/", "type": "meta-analysis", "summary": "This meta-analysis pooled 15 placebo-controlled trials of calcium supplements (500 mg/day or more) without vitamin D, using patient-level data from 8,151 people and trial-level data from 11,921. People on calcium had about 30% more heart attacks (HR 1.31). The finding is still debated and the trials were not designed to measure heart outcomes, but it argues for getting calcium mostly from food and keeping supplement doses low.", "highlight": "Calcium supplements (without coadministered vitamin D) are associated with an increased risk of myocardial infarction.", "apa": "Bolland, M. J., Avenell, A., Baron, J. A., Grey, A., MacLennan, G. S., Gamble, G. D., &amp; Reid, I. R. (2010). Effect of calcium supplements on risk of myocardial infarction and cardiovascular events: meta-analysis. <i>BMJ</i>, <i>341</i>(jul29 1), c3691–c3691. <a href=\"https://doi.org/10.1136/bmj.c3691\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bmj.c3691</a>"}, {"title": "Nutritional aspects of manganese homeostasis.", "authors": "Aschner JL, Aschner M", "year": 2005, "journal": "Mol Aspects Med", "doi": "10.1016/j.mam.2005.07.003", "pmid": "16099026", "pmcid": "PMC6309959", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6309959/", "type": "review", "summary": "This narrative review covers manganese as an essential mineral: where it occurs in food, how it is absorbed and excreted, and when it becomes toxic. The body tightly regulates manganese levels, and ordinary diets supply enough, while excess exposure can build up in the brain and cause a Parkinson-like syndrome (manganism). There are no trials showing benefit from supplementing manganese, so only a small dose, if any, makes sense.", "highlight": "Humans maintain stable tissue levels of Mn. This is achieved via tight homeostatic control of both absorption and excretion.", "apa": "Aschner, J. L., &amp; Aschner, M. (2005). Nutritional aspects of manganese homeostasis. <i>Molecular Aspects of Medicine</i>, <i>26</i>(4-5), 353–362. <a href=\"https://doi.org/10.1016/j.mam.2005.07.003\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.mam.2005.07.003</a>"}]}, {"id": "boron", "label": "Boron", "title": "Boron", "tier": "supplements", "group": null, "blurb": "Blueprint: 3 mg boron glycinate in the Essential Capsules.", "sources": [{"title": "Nothing Boring About Boron.", "authors": "Pizzorno L", "year": 2015, "journal": "Integrative Medicine (Encinitas, Calif.)", "doi": null, "pmid": "26770156", "pmcid": "PMC4712861", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4712861/", "type": "review", "summary": "This narrative review collects animal, cell and small human studies on boron's roles in bone, hormones, vitamin D, magnesium and inflammation. It reports benefits for bone maintenance and lower inflammatory markers such as hs-CRP and TNF-α, and suggests 3 mg/day for people eating few fruits and vegetables or at risk of osteoporosis. It is written for an integrative-medicine audience and is more enthusiastic than the thin human trial base supports.", "highlight": "In none of the numerous studies conducted to date, however, do boron's beneficial effects appear at intakes > 3 mg/d.", "apa": "Pizzorno, L. (2015). Nothing Boring About Boron. <i>Integrative Medicine (Encinitas, Calif.)</i>. <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4712861/\" target=\"_blank\" rel=\"noopener\">https://pmc.ncbi.nlm.nih.gov/articles/PMC4712861/</a>"}, {"title": "Comparative effects of daily and weekly boron supplementation on plasma steroid hormones and proinflammatory cytokines.", "authors": "Naghii MR, Mofid M, Asgari AR, et al.", "year": 2011, "journal": "Journal of Trace Elements in Medicine and Biology", "doi": "10.1016/j.jtemb.2010.10.001", "pmid": "21129941", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/21129941/", "type": "clinical trial", "summary": "Eight healthy men took 10 mg of boron daily for one week, with blood drawn before and after in an uncontrolled, placebo-day comparison. Free testosterone rose, estradiol fell, and hs-CRP and TNF-α decreased after one week. With only eight subjects, no parallel control group and a dose well above typical intake, this is a pilot signal, not evidence of lasting benefit.", "highlight": "After one week (in samples taken at 8.00 A.M, only), the mean plasma free testosterone increased and the mean plasma estradiol decreased significantly.", "apa": "Naghii, M. R., Mofid, M., Asgari, A. R., Hedayati, M., &amp; Daneshpour, M.-S. (2011). Comparative effects of daily and weekly boron supplementation on plasma steroid hormones and proinflammatory cytokines. <i>Journal of Trace Elements in Medicine and Biology</i>, <i>25</i>(1), 54–58. <a href=\"https://doi.org/10.1016/j.jtemb.2010.10.001\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jtemb.2010.10.001</a>"}, {"title": "Dietary Lithium, Silicon, and Boron: An Updated Critical Review of Their Roles in Metabolic Regulation, Neurobiology, Bone Health, and the Gut Microbiome.", "authors": "Melenikioti E, Pavlidou E, Dakanalis A, et al.", "year": 2026, "journal": "Nutrients", "doi": "10.3390/nu18030386", "pmid": "41683210", "pmcid": "PMC12899721", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12899721/", "type": "review", "summary": "This critical narrative review searched three databases through January 2025 and graded evidence for boron, lithium and silicon by human, animal and cell tiers. For boron, human support comes from metabolic, inflammatory and cognitive studies of modest size. The authors conclude current human data are insufficient to justify supplementation, which is the more sober counterweight to enthusiastic reviews.", "highlight": "current human data are insufficient to justify dietary recommendations or supplementation", "apa": "Melenikioti, E., Pavlidou, E., Dakanalis, A., Giaginis, C., &amp; Papadopoulou, S. K. (2026). Dietary Lithium, Silicon, and Boron: An Updated Critical Review of Their Roles in Metabolic Regulation, Neurobiology, Bone Health, and the Gut Microbiome. <i>Nutrients</i>, <i>18</i>(3), 386. <a href=\"https://doi.org/10.3390/nu18030386\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu18030386</a>"}]}, {"id": "lithium", "label": "Lithium (1 mg)", "title": "Low-dose lithium", "tier": "supplements", "group": null, "blurb": "Blueprint: 1 mg lithium orotate in the Essential Capsules. A trace dose, hundreds of times below psychiatric doses.", "sources": [{"title": "Lithium deficiency and the onset of Alzheimer's disease.", "authors": "Aron L, Ngian ZK, Qiu C, et al.", "year": 2025, "journal": "Nature", "doi": "10.1038/s41586-025-09335-x", "pmid": "40770094", "pmcid": "PMC12443616", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12443616/", "type": "cohort", "summary": "This study measured metals in human post-mortem brain tissue and then depleted or replaced dietary lithium in wild-type and Alzheimer's mouse models. Lithium was the only metal significantly reduced in brains of people with mild cognitive impairment, and halving cortical lithium in mice accelerated amyloid, tau pathology and memory loss, while low-dose lithium orotate prevented them. It is a striking mechanistic result but the treatment evidence is entirely in mice; no human trial of lithium orotate has yet shown benefit.", "highlight": "Of the metals we analysed, Li was the only one that was significantly reduced in the brain in individuals with mild cognitive impairment (MCI)", "apa": "Aron, L., Ngian, Z. K., Qiu, C., Choi, J., Liang, M., Drake, D. M., Hamplova, S. E., Lacey, E. K., Roche, P., Yuan, M., Hazaveh, S. S., Lee, E. A., Bennett, D. A., &amp; Yankner, B. A. (2025). Lithium deficiency and the onset of Alzheimer’s disease. <i>Nature</i>, <i>645</i>(8081), 712–721. <a href=\"https://doi.org/10.1038/s41586-025-09335-x\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41586-025-09335-x</a>"}, {"title": "Association between naturally occurring lithium in drinking water and suicide rates: systematic review and meta-analysis of ecological studies.", "authors": "Memon A, Rogers I, Fitzsimmons SMDD, et al.", "year": 2020, "journal": "The British Journal of Psychiatry", "doi": "10.1192/bjp.2020.128", "pmid": "32716281", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/32716281/", "type": "meta-analysis", "summary": "This meta-analysis pooled 15 ecological studies comparing natural lithium levels in public drinking water with regional suicide rates. Higher water lithium was consistently associated with lower total suicide mortality (pooled β -0.27), with high heterogeneity. Ecological data compare regions, not individuals, so confounding is likely and the authors call for randomized community trials before any recommendation.", "highlight": "The random-effects meta-analysis showed a consistent protective (or inverse) association between lithium levels/concentration in publicly available drinking water and total", "apa": "Memon, A., Rogers, I., Fitzsimmons, S. M. D. D., Carter, B., Strawbridge, R., Hidalgo-Mazzei, D., &amp; Young, A. H. (2020). Association between naturally occurring lithium in drinking water and suicide rates: systematic review and meta-analysis of ecological studies. <i>The British Journal of Psychiatry</i>, <i>217</i>(6), 667–678. <a href=\"https://doi.org/10.1192/bjp.2020.128\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1192/bjp.2020.128</a>"}, {"title": "Microdose lithium treatment stabilized cognitive impairment in patients with Alzheimer's disease.", "authors": "Nunes MA, Viel TA, Buck HS", "year": 2013, "journal": "Current Alzheimer Research", "doi": "10.2174/1567205011310010014", "pmid": "22746245", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22746245/", "type": "RCT", "summary": "This small controlled trial gave Alzheimer's patients a microdose of 300 μg lithium daily or placebo for 15 months and tracked Mini-Mental State Examination scores. The lithium group showed no decline while controls worsened, with differences appearing from three months onward. It was a small single-center study that has not been replicated, so supplement-dose lithium for brain health remains preliminary.", "highlight": "the treated group showed no decreased performance in the mini-mental state examination test, in opposition to the lower scores observed for the control group", "apa": "Andrade Nunes, M., Araujo Viel, T., &amp; Sousa Buck, H. (2013). Microdose Lithium Treatment Stabilized Cognitive Impairment in Patients with Alzheimer’s Disease. <i>Current Alzheimer Research</i>, <i>10</i>(1), 104–107. <a href=\"https://doi.org/10.2174/1567205011310010014\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.2174/1567205011310010014</a>"}]}, {"id": "caakg", "label": "CaAKG", "title": "Calcium alpha-ketoglutarate (CaAKG)", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Alpha-Ketoglutarate, an Endogenous Metabolite, Extends Lifespan and Compresses Morbidity in Aging Mice", "authors": "Asadi Shahmirzadi A, Edgar D, Liao CY, et al.", "year": 2020, "journal": "Cell Metabolism", "doi": "10.1016/j.cmet.2020.08.004", "pmid": "32877690", "pmcid": "PMC8508957", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8508957/", "type": "animal study", "summary": "This study fed middle-aged C57BL/6 mice calcium alpha-ketoglutarate (CaAKG) in their diet and tracked lifespan alongside longitudinal frailty and healthspan measures. CaAKG extended lifespan, reduced frailty and lowered systemic inflammatory cytokines, an effect the authors tie to induction of IL-10. These are mouse results only; no human lifespan or hard-outcome data exist for CaAKG.", "highlight": "We find that CaAKG promotes a longer, healthier life associated with a decrease in levels of systemic inflammatory cytokines.", "apa": "Asadi Shahmirzadi, A., Edgar, D., Liao, C.-Y., Hsu, Y.-M., Lucanic, M., Asadi Shahmirzadi, A., Wiley, C. D., Gan, G., Kim, D. E., Kasler, H. G., Kuehnemann, C., Kaplowitz, B., Bhaumik, D., Riley, R. R., Kennedy, B. K., &amp; Lithgow, G. J. (2020). Alpha-Ketoglutarate, an Endogenous Metabolite, Extends Lifespan and Compresses Morbidity in Aging Mice. <i>Cell Metabolism</i>, <i>32</i>(3), 447–456.e6. <a href=\"https://doi.org/10.1016/j.cmet.2020.08.004\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.cmet.2020.08.004</a>"}, {"title": "Rejuvant, a potential life-extending compound formulation with alpha-ketoglutarate and vitamins, conferred an average 8 year reduction in biological aging, after an average of 7 months of use, in the TruAge DNA methylation test", "authors": "Demidenko O, Barardo D, Budovskii V, et al.", "year": 2021, "journal": "Aging", "doi": "10.18632/aging.203736", "pmid": "34847066", "pmcid": "PMC8660611", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8660611/", "type": "cohort", "summary": "This retrospective analysis looked at DNA methylation age in 42 people who took Rejuvant, a CaAKG-plus-vitamin formulation, for an average of 7 months. Their measured biological age fell by an average of about 8 years. There was no placebo or control group, the sample was small and self-selected, and the authors themselves state placebo-controlled testing is required, so this is very weak evidence.", "highlight": "individuals showed an average decrease in biological aging of 8 years (p-value=6.538x10-12)", "apa": "Demidenko, O., Barardo, D., Budovskii, V., Finnemore, R., Palmer, F. R., Kennedy, B. K., &amp; Budovskaya, Y. V. (2021). Rejuvant®, a potential life-extending compound formulation with alpha-ketoglutarate and vitamins, conferred an average 8 year reduction in biological aging, after an average of 7 months of use, in the TruAge DNA methylation test. <i>Aging</i>, <i>13</i>(22), 24485–24499. <a href=\"https://doi.org/10.18632/aging.203736\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.18632/aging.203736</a>"}, {"title": "Alpha-ketoglutarate supplementation and BiologicaL agE in middle-aged adults (ABLE)-intervention study protocol", "authors": "Sandalova E, Goh J, Lim ZX, et al.", "year": 2023, "journal": "GeroScience", "doi": "10.1007/s11357-023-00813-6", "pmid": "37217632", "pmcid": "PMC10643463", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10643463/", "type": "RCT", "summary": "This paper describes the ABLE trial, a double-blind placebo-controlled RCT of 1 g/day sustained-release CaAKG for 6 months in 120 healthy 40-60-year-olds whose DNA methylation age exceeds their chronological age. The primary outcome is change in DNA methylation age, with secondary outcomes including inflammation, strength, arterial stiffness and aerobic capacity. It is a protocol, not results, and its existence underlines that properly controlled human evidence for CaAKG is still pending.", "highlight": "Alpha-Ketoglutarate (AKG) has been studied widely in model animals, but there are few studies testing its geroprotective properties in humans.", "apa": "Sandalova, E., Goh, J., Lim, Z. X., Lim, Z. M., Barardo, D., Dorajoo, R., Kennedy, B. K., &amp; Maier, A. B. (2023). Alpha-ketoglutarate supplementation and BiologicaL agE in middle-aged adults (ABLE)—intervention study protocol. <i>GeroScience</i>, <i>45</i>(5), 2897–2907. <a href=\"https://doi.org/10.1007/s11357-023-00813-6\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s11357-023-00813-6</a>"}]}, {"id": "glutathione", "label": "Glutathione", "title": "Glutathione", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Randomized controlled trial of oral glutathione supplementation on body stores of glutathione", "authors": "Richie JP, Nichenametla S, Neidig W, et al.", "year": 2015, "journal": "European Journal of Nutrition", "doi": "10.1007/s00394-014-0706-z", "pmid": "24791752", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/24791752/", "type": "RCT", "summary": "This 6-month randomized, double-blind, placebo-controlled trial gave 54 healthy non-smoking adults 250 or 1,000 mg/day of oral glutathione and measured glutathione in blood and tissue cells. At 6 months the high dose raised glutathione 30-35% in erythrocytes, plasma and lymphocytes, and natural killer cell activity more than doubled at 3 months. Levels fell back to baseline within a month of stopping, and the study measured biomarkers rather than any health outcome.", "highlight": "daily consumption of GSH supplements was effective at increasing body compartment stores of GSH", "apa": "Richie, J. P., Nichenametla, S., Neidig, W., Calcagnotto, A., Haley, J. S., Schell, T. D., &amp; Muscat, J. E. (2014). Randomized controlled trial of oral glutathione supplementation on body stores of glutathione. <i>European Journal of Nutrition</i>, <i>54</i>(2), 251–263. <a href=\"https://doi.org/10.1007/s00394-014-0706-z\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s00394-014-0706-z</a>"}, {"title": "Effects of oral glutathione supplementation on systemic oxidative stress biomarkers in human volunteers", "authors": "Allen J, Bradley RD", "year": 2011, "journal": "Journal of Alternative and Complementary Medicine", "doi": "10.1089/acm.2010.0716", "pmid": "21875351", "pmcid": "PMC3162377", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3162377/", "type": "RCT", "summary": "This randomized, double-blind, placebo-controlled trial gave 40 healthy adults 500 mg of oral glutathione twice daily for 4 weeks. It found no change in urinary oxidative stress markers (F2-isoprostanes, 8-OHdG) or in red blood cell glutathione status. Together with the longer Richie trial, it suggests any effect of oral glutathione is slow, modest, and not reliably detectable over a short course.", "highlight": "No significant changes were observed in biomarkers of oxidative stress, including glutathione status, in this clinical trial of oral glutathione supplementation in healthy adults.", "apa": "Allen, J., &amp; Bradley, R. D. (2011). Effects of Oral Glutathione Supplementation on Systemic Oxidative Stress Biomarkers in Human Volunteers. <i>The Journal of Alternative and Complementary Medicine</i>, <i>17</i>(9), 827–833. <a href=\"https://doi.org/10.1089/acm.2010.0716\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1089/acm.2010.0716</a>"}, {"title": "Efficacy of glutathione for the treatment of nonalcoholic fatty liver disease: an open-label, single-arm, multicenter, pilot study", "authors": "Honda Y, Kessoku T, Sumida Y, et al.", "year": 2017, "journal": "BMC Gastroenterology", "doi": "10.1186/s12876-017-0652-3", "pmid": "28789631", "pmcid": "PMC5549431", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5549431/", "type": "RCT", "summary": "This open-label, single-arm pilot study gave 34 patients with fatty liver disease 300 mg/day of oral glutathione for 4 months after 3 months of lifestyle changes. ALT (a liver enzyme) fell significantly, along with triglycerides and ferritin, and liver fat dropped in the responders. With no control group and only 29 completers, this is hypothesis-generating; the authors themselves call for large trials.", "highlight": "This pilot study demonstrates the potential therapeutic effects of oral administration of glutathione in practical dose for patients with NAFLD.", "apa": "Honda, Y., Kessoku, T., Sumida, Y., Kobayashi, T., Kato, T., Ogawa, Y., Tomeno, W., Imajo, K., Fujita, K., Yoneda, M., Kataoka, K., Taguri, M., Yamanaka, T., Seko, Y., Tanaka, S., Saito, S., Ono, M., Oeda, S., Eguchi, Y., . . . Nakajima, A. (2017). Efficacy of glutathione for the treatment of nonalcoholic fatty liver disease: an open-label, single-arm, multicenter, pilot study. <i>BMC Gastroenterology</i>, <i>17</i>(1), 96. <a href=\"https://doi.org/10.1186/s12876-017-0652-3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1186/s12876-017-0652-3</a>"}]}, {"id": "lysine", "label": "Lysine", "title": "L-lysine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Lysine for Herpes Simplex Prophylaxis: A Review of the Evidence", "authors": "Mailoo VJ, Rampes S", "year": 2017, "journal": "Integrative Medicine (Encinitas)", "doi": null, "pmid": "30881246", "pmcid": "PMC6419779", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6419779/", "type": "systematic review", "summary": "Two reviewers searched four databases and summarized the clinical trials of oral L-lysine for preventing herpes simplex recurrences. Lysine looked ineffective below 1 g/day unless paired with a low-arginine diet, while doses above 3 g/day seemed to improve patients' subjective experience of outbreaks. The trials are small, old and heterogeneous, so dose matters and the evidence is weak.", "highlight": "L-lysine supplementation appears to be ineffective for prophylaxis or treatment of herpes simplex lesions with doses of less than 1 g/d without low-arginine diets.", "apa": "Mailoo, V. J., &amp; Rampes, S. (2017). Lysine for Herpes Simplex Prophylaxis: A Review of the Evidence. <i>Integrative Medicine (Encinitas)</i>. <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC6419779/\" target=\"_blank\" rel=\"noopener\">https://pmc.ncbi.nlm.nih.gov/articles/PMC6419779/</a>"}, {"title": "Interventions for prevention of herpes simplex labialis (cold sores on the lips)", "authors": "Chi CC, Wang SH, Delamere FM, et al.", "year": 2015, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD010095.pub2", "pmid": "26252373", "pmcid": "PMC6461191", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6461191/", "type": "systematic review", "summary": "This Cochrane review pooled 32 randomized trials (2,640 people) covering 19 different ways to prevent cold sores. Long-term oral antivirals such as aciclovir or valaciclovir modestly reduced recurrences, but the reviewers found no evidence of efficacy for lysine. If cold-sore prevention is the goal, prescription antivirals have better evidence than lysine.", "highlight": "We failed to find any evidence of efficacy for lysine, LongoVital® supplementation, gamma globulin", "apa": "Chi, C.-C., Wang, S.-H., Delamere, F. M., Wojnarowska, F., Peters, M. C., &amp; Kanjirath, P. P. (2015). Interventions for prevention of herpes simplex labialis (cold sores on the lips). <i>Cochrane Database of Systematic Reviews</i>, <i>2016</i>(10). <a href=\"https://doi.org/10.1002/14651858.CD010095.pub2\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD010095.pub2</a>"}, {"title": "Lysine fortification reduces anxiety and lessens stress in family members in economically weak communities in Northwest Syria", "authors": "Smriga M, Ghosh S, Mouneimne Y, et al.", "year": 2004, "journal": "Proceedings of the National Academy of Sciences of the United States of America", "doi": "10.1073/pnas.0402550101", "pmid": "15159538", "pmcid": "PMC420386", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC420386/", "type": "RCT", "summary": "This 3-month randomized double-blind study fortified wheat flour with lysine for families in poor Syrian communities whose diets relied on wheat, which is low in lysine. Fortification lowered trait anxiety in men and blunted stress responses (cortisol in women, skin conductance in men). The people studied likely had low lysine intake, so the result may not carry over to well-fed adults eating plenty of protein.", "highlight": "Lysine fortification also significantly reduced chronic anxiety as measured by the trait anxiety inventory in males.", "apa": "Smriga, M., Ghosh, S., Mouneimne, Y., Pellett, P. L., &amp; Scrimshaw, N. S. (2004). Lysine fortification reduces anxiety and lessens stress in family members in economically weak communities in Northwest Syria. <i>Proceedings of the National Academy of Sciences</i>, <i>101</i>(22), 8285–8288. <a href=\"https://doi.org/10.1073/pnas.0402550101\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1073/pnas.0402550101</a>"}]}, {"id": "arginine", "label": "L-arginine", "title": "L-arginine", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": [{"title": "Effect of oral L-arginine supplementation on blood pressure: a meta-analysis of randomized, double-blind, placebo-controlled trials.", "authors": "Dong JY, Qin LQ, Zhang Z, et al.", "year": 2011, "journal": "Am Heart J", "doi": "10.1016/j.ahj.2011.09.012", "pmid": "22137067", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22137067/", "type": "meta-analysis", "summary": "This meta-analysis pooled 11 double-blind, placebo-controlled trials with 387 people taking 4-24 g/day of oral L-arginine. Arginine lowered systolic blood pressure by 5.4 mmHg and diastolic by 2.7 mmHg compared with placebo. The trials were small and short, and the doses are large, so this is a modest effect on a lab number rather than proof of fewer heart attacks.", "highlight": "This meta-analysis provides further evidence that oral L-arginine supplementation significantly lowers both systolic and diastolic BP.", "apa": "Dong, J.-Y., Qin, L.-Q., Zhang, Z., Zhao, Y., Wang, J., Arigoni, F., &amp; Zhang, W. (2011). Effect of oral l-arginine supplementation on blood pressure: A meta-analysis of randomized, double-blind, placebo-controlled trials. <i>American Heart Journal</i>, <i>162</i>(6), 959–965. <a href=\"https://doi.org/10.1016/j.ahj.2011.09.012\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.ahj.2011.09.012</a>"}, {"title": "Association of l-Arginine Supplementation with Markers of Endothelial Function in Patients with Cardiovascular or Metabolic Disorders: A Systematic Review and Meta-Analysis.", "authors": "Rodrigues-Krause J, Krause M, Rocha IMGD, et al.", "year": 2018, "journal": "Nutrients", "doi": "10.3390/nu11010015", "pmid": "30577559", "pmcid": "PMC6357192", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6357192/", "type": "meta-analysis", "summary": "This meta-analysis pooled 13 randomized trials of oral L-arginine versus placebo in people with heart disease, obesity, or diabetes, with flow-mediated dilation as the main outcome. Overall there was no significant improvement in endothelial function (SMD 0.30, 95% CI -0.85 to 1.46), and nitric oxide markers did not change. Results were extremely inconsistent between trials (I2 = 96%), so the endothelial-function rationale for arginine is not well supported.", "highlight": "Overall, the results indicated that oral l-arginine supplementation was not associated with improvements on selected variables in these patients", "apa": "Rodrigues-Krause, J., Krause, M., Rocha, I. M. G. d., Umpierre, D., &amp; Fayh, A. P. T. (2018). Association of l-Arginine Supplementation with Markers of Endothelial Function in Patients with Cardiovascular or Metabolic Disorders: A Systematic Review and Meta-Analysis. <i>Nutrients</i>, <i>11</i>(1), 15. <a href=\"https://doi.org/10.3390/nu11010015\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu11010015</a>"}, {"title": "L-arginine therapy in acute myocardial infarction: the Vascular Interaction With Age in Myocardial Infarction (VINTAGE MI) randomized clinical trial.", "authors": "Schulman SP, Becker LC, Kass DA, et al.", "year": 2006, "journal": "JAMA", "doi": "10.1001/jama.295.1.58", "pmid": "16391217", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/16391217/", "type": "RCT", "summary": "This randomized, double-blind trial gave 153 heart attack survivors L-arginine (goal 9 g/day) or placebo for 6 months. Arginine did not improve vascular stiffness or heart pumping function, and 6 people (8.6%) on arginine died versus none on placebo, so the trial was stopped early. It is a single small trial in a specific group, but it is a clear warning against using arginine after a heart attack.", "highlight": "L-arginine, when added to standard postinfarction therapies, does not improve vascular stiffness measurements or ejection fraction and may be associated with higher postinfarction mortality.", "apa": "Schulman, S. P., Becker, L. C., Kass, D. A., Champion, H. C., Terrin, M. L., Forman, S., Ernst, K. V., Kelemen, M. D., Townsend, S. N., Capriotti, A., Hare, J. M., &amp; Gerstenblith, G. (2006). L-Arginine Therapy in Acute Myocardial Infarction. <i>Jama</i>, <i>295</i>(1), 58. <a href=\"https://doi.org/10.1001/jama.295.1.58\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.295.1.58</a>"}]}, {"id": "theanine", "label": "L-theanine", "title": "L-theanine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Longevity Mix.", "sources": [{"title": "Effects of L-Theanine Administration on Stress-Related Symptoms and Cognitive Functions in Healthy Adults: A Randomized Controlled Trial", "authors": "Hidese S, Ogawa S, Ota M, et al.", "year": 2019, "journal": "Nutrients", "doi": "10.3390/nu11102362", "pmid": "31623400", "pmcid": "PMC6836118", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6836118/", "type": "RCT", "summary": "This double-blind, placebo-controlled crossover trial gave 30 healthy adults 200 mg/day of L-theanine for four weeks. Depression, trait-anxiety and sleep-quality (PSQI) scores improved, with shorter sleep latency and less sleep disturbance versus placebo, and verbal fluency and executive function scores rose. It is a small study, so treat the results as encouraging rather than settled.", "highlight": "The PSQI subscale scores for sleep latency, sleep disturbance, and use of sleep medication reduced after L-theanine administration, compared to the placebo administration", "apa": "Hidese, S., Ogawa, S., Ota, M., Ishida, I., Yasukawa, Z., Ozeki, M., &amp; Kunugi, H. (2019). Effects of L-Theanine Administration on Stress-Related Symptoms and Cognitive Functions in Healthy Adults: A Randomized Controlled Trial. <i>Nutrients</i>, <i>11</i>(10), 2362. <a href=\"https://doi.org/10.3390/nu11102362\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu11102362</a>"}, {"title": "The Effects of Green Tea Amino Acid L-Theanine Consumption on the Ability to Manage Stress and Anxiety Levels: a Systematic Review", "authors": "Williams JL, Everett JM, D'Cunha NM, et al.", "year": 2020, "journal": "Plant Foods for Human Nutrition", "doi": "10.1007/s11130-019-00771-5", "pmid": "31758301", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31758301/", "type": "systematic review", "summary": "This PRISMA systematic review gathered 9 randomized controlled trials of pure L-theanine supplements on stress and anxiety. It concluded that 200-400 mg/day may help reduce stress and anxiety in people under stressful conditions. The trials were small and short, and the authors say longer, larger studies are needed before calling it a therapy.", "highlight": "may assist in the reduction of stress and anxiety in people exposed to stressful conditions", "apa": "Williams, J. L., Everett, J. M., D’Cunha, N. M., Sergi, D., Georgousopoulou, E. N., Keegan, R. J., McKune, A. J., Mellor, D. D., Anstice, N., &amp; Naumovski, N. (2019). The Effects of Green Tea Amino Acid L-Theanine Consumption on the Ability to Manage Stress and Anxiety Levels: a Systematic Review. <i>Plant Foods for Human Nutrition</i>, <i>75</i>(1), 12–23. <a href=\"https://doi.org/10.1007/s11130-019-00771-5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s11130-019-00771-5</a>"}, {"title": "Acute effects of tea constituents L-theanine, caffeine, and epigallocatechin gallate on cognitive function and mood: a systematic review and meta-analysis", "authors": "Camfield DA, Stough C, Farrimond J, Scholey AB", "year": 2014, "journal": "Nutrition Reviews", "doi": "10.1111/nure.12120", "pmid": "24946991", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/24946991/", "type": "meta-analysis", "summary": "This meta-analysis pooled 11 randomized placebo-controlled studies of single doses of L-theanine, EGCG and caffeine on mood and attention. Caffeine plus L-theanine produced moderate improvements in alertness and attention-switching accuracy in the first 2 hours. Effect size tracked the caffeine dose more than the theanine dose, so much of the attention boost may come from the caffeine.", "highlight": "Evidence of moderate effect sizes in favor of combined caffeine and L-theanine in the first 2 hours postdose were found", "apa": "Camfield, D. A., Stough, C., Farrimond, J., &amp; Scholey, A. B. (2014). Acute effects of tea constituents L-theanine, caffeine, and epigallocatechin gallate on cognitive function and mood: a systematic review and meta-analysis. <i>Nutrition Reviews</i>, <i>72</i>(8), 507–522. <a href=\"https://doi.org/10.1111/nure.12120\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1111/nure.12120</a>"}]}, {"id": "coq10", "label": "CoQ10", "title": "CoQ10 (ubiquinol)", "tier": "supplements", "group": null, "blurb": "Blueprint: 50 mg ubiquinol in the Essential Capsules.", "sources": [{"title": "The effect of coenzyme Q10 on morbidity and mortality in chronic heart failure: results from Q-SYMBIO: a randomized double-blind trial.", "authors": "Mortensen SA, Rosenfeldt F, Kumar A, et al.", "year": 2014, "journal": "JACC: Heart Failure", "doi": "10.1016/j.jchf.2014.06.008", "pmid": "25282031", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25282031/", "type": "RCT", "summary": "Q-SYMBIO randomized 420 patients with moderate to severe heart failure to CoQ10 100 mg three times daily or placebo on top of standard therapy for 2 years. Major adverse cardiovascular events occurred in 15% on CoQ10 versus 26% on placebo (hazard ratio 0.50), with lower all-cause mortality (10% vs 18%). Short-term endpoints did not change, the trial was modest in size and slow to recruit, and it has not been replicated by a large independent trial.", "highlight": "The primary long-term endpoint was reached by 15% of the patients in the CoQ10 group versus 26% in the placebo group", "apa": "Mortensen, S. A., Rosenfeldt, F., Kumar, A., Dolliner, P., Filipiak, K. J., Pella, D., Alehagen, U., Steurer, G., &amp; Littarru, G. P. (2014). The Effect of Coenzyme Q 10 on Morbidity and Mortality in Chronic Heart Failure. <i>JACC: Heart Failure</i>, <i>2</i>(6), 641–649. <a href=\"https://doi.org/10.1016/j.jchf.2014.06.008\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jchf.2014.06.008</a>"}, {"title": "Effects of Coenzyme Q10 on Statin-Induced Myopathy: An Updated Meta-Analysis of Randomized Controlled Trials.", "authors": "Qu H, Guo M, Chai H, et al.", "year": 2018, "journal": "Journal of the American Heart Association", "doi": "10.1161/JAHA.118.009835", "pmid": "30371340", "pmcid": "PMC6404871", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6404871/", "type": "meta-analysis", "summary": "This meta-analysis pooled 12 randomized trials with 575 statin users to test whether CoQ10 eases statin-associated muscle symptoms. CoQ10 reduced muscle pain scores (weighted mean difference -1.60), plus weakness, cramps and tiredness, but did not change creatine kinase. The trials were small and heterogeneous, and an earlier meta-analysis (Banach 2015) and a later one (Kennedy 2020) found no clear benefit, so the evidence is genuinely mixed.", "highlight": "Compared with placebo, CoQ10 supplementation ameliorated statin-associated muscle symptoms, such as muscle pain", "apa": "Qu, H., Guo, M., Chai, H., Wang, W., Gao, Z., &amp; Shi, D. (2018). Effects of Coenzyme Q10 on Statin‐Induced Myopathy: An Updated Meta‐Analysis of Randomized Controlled Trials. <i>Journal of the American Heart Association</i>, <i>7</i>(19), e009835. <a href=\"https://doi.org/10.1161/JAHA.118.009835\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/JAHA.118.009835</a>"}, {"title": "Dose-Response Effect of Coenzyme Q10 Supplementation on Blood Pressure among Patients with Cardiometabolic Disorders: A Grading of Recommendations Assessment, Development, and Evaluation (GRADE)-Assessed Systematic Review and Meta-Analysis of Randomized Controlled Trials.", "authors": "Zhao D, Liang Y, Dai S, et al.", "year": 2022, "journal": "Advances in Nutrition", "doi": "10.1093/advances/nmac100", "pmid": "36130103", "pmcid": "PMC9776655", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9776655/", "type": "meta-analysis", "summary": "This GRADE-assessed dose-response meta-analysis pooled 26 randomized trials with 1,831 people with cardiometabolic disease. CoQ10 lowered systolic blood pressure by about 4.8 mmHg, with the largest effect around 100-200 mg/day and longer use beyond 12 weeks. Evidence certainty was moderate for systolic and low for diastolic pressure, so it is an adjunct at best, not a replacement for blood pressure drugs.", "highlight": "100-200 mg/d of CoQ10 supplementation may achieve the greatest benefit on SBP in patients with cardiometabolic diseases", "apa": "Zhao, D., Liang, Y., Dai, S., Hou, S., Liu, Z., Liu, M., Dong, X., Zhan, Y., Tian, Z., &amp; Yang, Y. (2022). Dose-Response Effect of Coenzyme Q10 Supplementation on Blood Pressure among Patients with Cardiometabolic Disorders: A Grading of Recommendations Assessment, Development, and Evaluation (GRADE)-Assessed Systematic Review and Meta-Analysis of Randomized Controlled Trials. <i>Advances in Nutrition</i>, <i>13</i>(6), 2180–2194. <a href=\"https://doi.org/10.1093/advances/nmac100\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/advances/nmac100</a>"}]}, {"id": "spermidine", "label": "Spermidine", "title": "Spermidine", "tier": "supplements", "group": null, "blurb": "Blueprint: in the Essential Capsules.", "sources": [{"title": "Cardioprotection and lifespan extension by the natural polyamine spermidine.", "authors": "Eisenberg T, Abdellatif M, Schroeder S, et al.", "year": 2016, "journal": "Nature Medicine", "doi": "10.1038/nm.4222", "pmid": "27841876", "pmcid": "PMC5806691", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5806691/", "type": "cohort", "summary": "This mostly preclinical study fed spermidine to aging mice and salt-sensitive rats and paired it with dietary questionnaire data from a human cohort. Spermidine extended mouse lifespan, preserved heart function via autophagy, and lowered blood pressure in rats, while higher dietary intake in humans tracked with lower blood pressure and cardiovascular disease. The core evidence is animal data plus observational human correlation, so it shows a plausible mechanism, not proof that supplements help people.", "highlight": "oral supplementation of the natural polyamine spermidine extends the lifespan of mice and exerts cardioprotective effects", "apa": "Eisenberg, T., Abdellatif, M., Schroeder, S., Primessnig, U., Stekovic, S., Pendl, T., Harger, A., Schipke, J., Zimmermann, A., Schmidt, A., Tong, M., Ruckenstuhl, C., Dammbrueck, C., Gross, A. S., Herbst, V., Magnes, C., Trausinger, G., Narath, S., Meinitzer, A., . . . Madeo, F. (2016). Cardioprotection and lifespan extension by the natural polyamine spermidine. <i>Nature Medicine</i>, <i>22</i>(12), 1428–1438. <a href=\"https://doi.org/10.1038/nm.4222\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/nm.4222</a>"}, {"title": "Higher spermidine intake is linked to lower mortality: a prospective population-based study.", "authors": "Kiechl S, Pechlaner R, Willeit P, et al.", "year": 2018, "journal": "The American Journal of Clinical Nutrition", "doi": "10.1093/ajcn/nqy102", "pmid": "29955838", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/29955838/", "type": "cohort", "summary": "The Bruneck Study followed 829 adults aged 45-84 for 20 years, estimating dietary spermidine with repeated food-frequency questionnaires. Each 1-SD higher spermidine intake was linked to 24% lower all-cause mortality (adjusted HR 0.76), a finding replicated in the SAPHIR cohort. This is observational: spermidine-rich foods like whole grains, legumes and mushrooms mark a healthier diet overall, so residual confounding is likely.", "highlight": "The age-, sex- and caloric ratio-adjusted HR for all-cause death per 1-SD higher spermidine intake was 0.74", "apa": "Kiechl, S., Pechlaner, R., Willeit, P., Notdurfter, M., Paulweber, B., Willeit, K., Werner, P., Ruckenstuhl, C., Iglseder, B., Weger, S., Mairhofer, B., Gartner, M., Kedenko, L., Chmelikova, M., Stekovic, S., Stuppner, H., Oberhollenzer, F., Kroemer, G., Mayr, M., . . . Willeit, J. (2018). Higher spermidine intake is linked to lower mortality: a prospective population-based study. <i>The American Journal of Clinical Nutrition</i>, <i>108</i>(2), 371–380. <a href=\"https://doi.org/10.1093/ajcn/nqy102\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/ajcn/nqy102</a>"}, {"title": "Effects of Spermidine Supplementation on Cognition and Biomarkers in Older Adults With Subjective Cognitive Decline: A Randomized Clinical Trial.", "authors": "Schwarz C, Benson GS, Horn N, et al.", "year": 2022, "journal": "JAMA Network Open", "doi": "10.1001/jamanetworkopen.2022.13875", "pmid": "35616942", "pmcid": "PMC9136623", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9136623/", "type": "RCT", "summary": "The SmartAge trial randomized 100 adults aged 60-90 with subjective memory complaints to a wheat-germ spermidine supplement (0.9 mg/day) or placebo for 12 months. Memory performance did not differ from placebo (between-group difference -0.03, P = .47), nor did secondary outcomes. This is the best human trial so far and it was null, though the dose was low; any hints on inflammation or verbal memory were exploratory.", "highlight": "longer-term spermidine supplementation in participants with subjective cognitive decline did not modify memory and biomarkers compared with placebo", "apa": "Schwarz, C., Benson, G. S., Horn, N., Wurdack, K., Grittner, U., Schilling, R., Märschenz, S., Köbe, T., Hofer, S. J., Magnes, C., Stekovic, S., Eisenberg, T., Sigrist, S. J., Schmitz, D., Wirth, M., Madeo, F., &amp; Flöel, A. (2022). Effects of Spermidine Supplementation on Cognition and Biomarkers in Older Adults With Subjective Cognitive Decline. <i>JAMA Network Open</i>, <i>5</i>(5), e2213875. <a href=\"https://doi.org/10.1001/jamanetworkopen.2022.13875\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jamanetworkopen.2022.13875</a>"}]}, {"id": "broccoli", "label": "Broccoli extract", "title": "Broccoli seed extract (sulforaphane)", "tier": "supplements", "group": null, "blurb": "Blueprint: 200 mg broccoli seed extract (20 mg glucoraphanin) in the Essential Capsules.", "sources": [{"title": "Rapid and sustainable detoxication of airborne pollutants by broccoli sprout beverage: results of a randomized clinical trial in China.", "authors": "Egner PA, Chen JG, Zarth AT, et al.", "year": 2014, "journal": "Cancer Prevention Research (Philadelphia, Pa.)", "doi": "10.1158/1940-6207.CAPR-14-0103", "pmid": "24913818", "pmcid": "PMC4125483", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4125483/", "type": "RCT", "summary": "A 12-week randomized placebo-controlled trial gave 291 adults in a heavily polluted region of Qidong, China a daily broccoli sprout beverage (600 μmol glucoraphanin plus 40 μmol sulforaphane). Urinary excretion of detoxified benzene rose 61% and acrolein 23% versus placebo, and the effect did not fade over 12 weeks. It measured detox biomarkers, not cancer or lung disease outcomes, so the long-term health payoff is assumed rather than shown.", "highlight": "Rapid and sustained, statistically significant (P ≤ 0.01) increases in the levels of excretion of the glutathione-derived conjugates of benzene (61%), acrolein (23%)", "apa": "Egner, P. A., Chen, J.-G., Zarth, A. T., Ng, D. K., Wang, J.-B., Kensler, K. H., Jacobson, L. P., Muñoz, A., Johnson, J. L., Groopman, J. D., Fahey, J. W., Talalay, P., Zhu, J., Chen, T.-Y., Qian, G.-S., Carmella, S. G., Hecht, S. S., &amp; Kensler, T. W. (2014). Rapid and Sustainable Detoxication of Airborne Pollutants by Broccoli Sprout Beverage: Results of a Randomized Clinical Trial in China. <i>Cancer Prevention Research</i>, <i>7</i>(8), 813–823. <a href=\"https://doi.org/10.1158/1940-6207.CAPR-14-0103\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1158/1940-6207.CAPR-14-0103</a>"}, {"title": "Effect of broccoli sprout extract and baseline gut microbiota on fasting blood glucose in prediabetes: a randomized, placebo-controlled trial.", "authors": "Dwibedi C, Axelsson AS, Abrahamsson B, et al.", "year": 2025, "journal": "Nature Microbiology", "doi": "10.1038/s41564-025-01932-w", "pmid": "39929977", "pmcid": "PMC11879859", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11879859/", "type": "RCT", "summary": "A double-blind trial randomized 74 drug-naive adults with prediabetes to broccoli sprout extract or placebo once daily for 12 weeks. Fasting glucose fell 0.2 mmol/L versus placebo, missing the prespecified 0.3 mmol/L target, though a subgroup whose gut bacteria better converted glucoraphanin to sulforaphane responded more strongly. The overall effect is small, and the responder finding is exploratory until replicated.", "highlight": "Gastro-intestinal side effects but no severe adverse events were observed in response to treatment. BSE did not meet the prespecified primary outcome", "apa": "Dwibedi, C., Axelsson, A. S., Abrahamsson, B., Fahey, J. W., Asplund, O., Hansson, O., Ahlqvist, E., Tremaroli, V., Bäckhed, F., &amp; Rosengren, A. H. (2025). Effect of broccoli sprout extract and baseline gut microbiota on fasting blood glucose in prediabetes: a randomized, placebo-controlled trial. <i>Nature Microbiology</i>, <i>10</i>(3), 681–693. <a href=\"https://doi.org/10.1038/s41564-025-01932-w\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41564-025-01932-w</a>"}, {"title": "Broccoli or Sulforaphane: Is It the Source or Dose That Matters?", "authors": "Yagishita Y, Fahey JW, Dinkova-Kostova AT, et al.", "year": 2019, "journal": "Molecules", "doi": "10.3390/molecules24193593", "pmid": "31590459", "pmcid": "PMC6804255", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6804255/", "type": "review", "summary": "This narrative review surveys more than 50 clinical trials of glucoraphanin and sulforaphane and compares formulations such as whole broccoli, sprouts, beverages and supplements. It finds that bioavailability varies widely by formulation, largely depending on whether active myrosinase or gut bacteria convert glucoraphanin into sulforaphane. Doses and products differ so much across studies that firm dosing advice is not yet possible, and validated human biomarkers are still lacking.", "highlight": "This review evaluates the current state of knowledge regarding the relationships between formulation (e.g., plants, sprouts, beverages, supplements), bioavailability and efficacy", "apa": "Yagishita, Y., Fahey, J. W., Dinkova-Kostova, A. T., &amp; Kensler, T. W. (2019). Broccoli or Sulforaphane: Is It the Source or Dose That Matters? <i>Molecules</i>, <i>24</i>(19), 3593. <a href=\"https://doi.org/10.3390/molecules24193593\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/molecules24193593</a>"}]}, {"id": "lutein_lycopene", "label": "Lutein + Lycopene", "title": "Lutein & lycopene", "tier": "supplements", "group": null, "blurb": "Blueprint: 15 mg each in the Advanced Antioxidants softgel.", "sources": [{"title": "The Effect of Lutein/Zeaxanthin Intake on Human Macular Pigment Optical Density: A Systematic Review and Meta-Analysis", "authors": "Wilson LM, Tharmarajah S, Jia Y, et al.", "year": 2021, "journal": "Advances in Nutrition", "doi": "10.1093/advances/nmab071", "pmid": "34157098", "pmcid": "PMC8634499", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8634499/", "type": "meta-analysis", "summary": "This systematic review and meta-analysis pooled 46 studies (3,189 adults with healthy eyes) testing lutein/zeaxanthin from supplements or food on macular pigment optical density (MPOD). Intakes under 5 mg/day showed no significant change, while 5 to under 20 mg/day raised MPOD by 0.04 units and 20 mg/day or more raised it by 0.11 units over 3-12 months. MPOD is a surrogate marker, and the authors note it is still unclear what dose or duration produces a clinically meaningful change in vision.", "highlight": "MPOD increased with lutein/zeaxanthin intake, particularly at higher doses, among adults with healthy eyes.", "apa": "Wilson, L. M., Tharmarajah, S., Jia, Y., Semba, R. D., Schaumberg, D. A., &amp; Robinson, K. A. (2021). The Effect of Lutein/Zeaxanthin Intake on Human Macular Pigment Optical Density: A Systematic Review and Meta-Analysis. <i>Advances in Nutrition</i>, <i>12</i>(6), 2244–2254. <a href=\"https://doi.org/10.1093/advances/nmab071\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/advances/nmab071</a>"}, {"title": "Tomato and lycopene supplementation and cardiovascular risk factors: A systematic review and meta-analysis", "authors": "Cheng HM, Koutsidis G, Lodge JK, et al.", "year": 2017, "journal": "Atherosclerosis", "doi": "10.1016/j.atherosclerosis.2017.01.009", "pmid": "28129549", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/28129549/", "type": "meta-analysis", "summary": "This meta-analysis pooled 21 intervention trials in adults testing tomato products or lycopene supplements on blood lipids, endothelial function, blood pressure and inflammation markers. Lycopene supplements lowered systolic blood pressure by 5.66 mmHg, while tomato products lowered LDL cholesterol by 0.22 mmol/L and improved flow-mediated dilation by 2.53%. Most other outcomes were unchanged, the trials were small and short, and these are risk-factor changes, not proof of fewer heart attacks or strokes.", "highlight": "increasing the intake of these has positive effects on blood lipids, blood pressure and endothelial function", "apa": "Cheng, H. M., Koutsidis, G., Lodge, J. K., Ashor, A., Siervo, M., &amp; Lara, J. (2017). Tomato and lycopene supplementation and cardiovascular risk factors: A systematic review and meta-analysis. <i>Atherosclerosis</i>, <i>257</i>, 100–108. <a href=\"https://doi.org/10.1016/j.atherosclerosis.2017.01.009\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.atherosclerosis.2017.01.009</a>"}, {"title": "Lutein + zeaxanthin and omega-3 fatty acids for age-related macular degeneration: the Age-Related Eye Disease Study 2 (AREDS2) randomized clinical trial", "authors": "Age-Related Eye Disease Study 2 Research Group", "year": 2013, "journal": "JAMA", "doi": "10.1001/jama.2013.4997", "pmid": "23644932", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/23644932/", "type": "RCT", "summary": "AREDS2 was a multicenter, double-masked, placebo-controlled factorial trial of 4,203 adults aged 50-85 at risk of advanced macular degeneration, testing lutein 10 mg plus zeaxanthin 2 mg (and/or fish oil) on top of the AREDS vitamin formula. Over a median 5 years, adding lutein/zeaxanthin did not significantly cut progression to advanced AMD in the primary analysis (31% placebo vs 29%; HR 0.90, 98.7% CI 0.76-1.07). The useful takeaway is narrower: lutein/zeaxanthin is a reasonable replacement for beta carotene in the AREDS formula because beta carotene was linked to more lung cancers in former smokers, and the benefit applies to people who already have intermediate AMD, not the general population.", "highlight": "lutein + zeaxanthin could be an appropriate carotenoid substitute in the AREDS formulation", "apa": "Age-Related Eye Disease Study 2 Research Group (2013). Lutein + Zeaxanthin and Omega-3 Fatty Acids for Age-Related Macular Degeneration. <i>Jama</i>, <i>309</i>(19), 2005. <a href=\"https://doi.org/10.1001/jama.2013.4997\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2013.4997</a>"}]}, {"id": "garlic", "label": "Garlic", "title": "Garlic", "tier": "supplements", "group": null, "blurb": "My addition as a supplement; Bryan eats garlic in his Super Veggie meal.", "sources": [{"title": "Garlic lowers blood pressure in hypertensive subjects, improves arterial stiffness and gut microbiota: A review and meta-analysis.", "authors": "Ried K", "year": 2020, "journal": "Experimental and Therapeutic Medicine", "doi": "10.3892/etm.2019.8374", "pmid": "32010325", "pmcid": "PMC6966103", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6966103/", "type": "meta-analysis", "summary": "This review and meta-analysis pooled 12 randomized trials with 553 people with high blood pressure who took garlic supplements, mostly aged garlic extract. Garlic lowered systolic pressure by about 8.3 mmHg and diastolic by 5.5 mmHg, comparable to a first-line blood pressure drug. The trials were small and much of the aged-garlic evidence comes from the author's own Kyolic studies, so an independent large trial would strengthen the case.", "highlight": "The meta-analysis of 12 trials and 553 hypertensive participants confirmed that garlic supplements lower systolic blood pressure (SBP)", "apa": "Ried, K. (2019). Garlic lowers blood pressure in hypertensive subjects, improves arterial stiffness and gut microbiota: A review and meta-analysis. <i>Experimental and Therapeutic Medicine</i>. <a href=\"https://doi.org/10.3892/etm.2019.8374\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3892/etm.2019.8374</a>"}, {"title": "Effects of Garlic on Glucose Parameters and Lipid Profile: A Systematic Review and Meta-Analysis on Randomized Controlled Trials.", "authors": "Zhao X, Cheng T, Xia H, et al.", "year": 2024, "journal": "Nutrients", "doi": "10.3390/nu16111692", "pmid": "38892625", "pmcid": "PMC11174586", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11174586/", "type": "meta-analysis", "summary": "This meta-analysis pooled randomized trials through February 2024 testing garlic or garlic supplements on blood sugar and lipids. Garlic lowered total cholesterol by about 14 mg/dL and LDL by about 8 mg/dL, raised HDL slightly, and reduced fasting glucose and HbA1c, but did not change triglycerides. The garlic forms and doses varied widely and heterogeneity was high, so the effect is modest and product-dependent.", "highlight": "The intervention of garlic is beneficial to control blood glucose and blood lipids in humans.", "apa": "Zhao, X., Cheng, T., Xia, H., Yang, Y., &amp; Wang, S. (2024). Effects of Garlic on Glucose Parameters and Lipid Profile: A Systematic Review and Meta-Analysis on Randomized Controlled Trials. <i>Nutrients</i>, <i>16</i>(11), 1692. <a href=\"https://doi.org/10.3390/nu16111692\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu16111692</a>"}, {"title": "Garlic for the common cold.", "authors": "Lissiman E, Bhasale AL, Cohen M", "year": 2014, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD006206.pub4", "pmid": "25386977", "pmcid": "PMC6465033", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6465033/", "type": "systematic review", "summary": "This Cochrane review searched for randomized trials of garlic to prevent or treat colds and found only one eligible trial, of 146 people taking an allicin supplement or placebo for 12 weeks. That trial reported 24 colds on garlic versus 65 on placebo, but recovery time was similar. One self-reported trial is not enough, and the authors conclude claims of effectiveness rely largely on poor-quality evidence.", "highlight": "There is insufficient clinical trial evidence regarding the effects of garlic in preventing or treating the common cold.", "apa": "Lissiman, E., Bhasale, A. L., &amp; Cohen, M. (2014). Garlic for the common cold. <i>Cochrane Database of Systematic Reviews</i>, <i>2020</i>(9). <a href=\"https://doi.org/10.1002/14651858.CD006206.pub4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD006206.pub4</a>"}]}, {"id": "chlorella", "label": "Chlorella", "title": "Chlorella", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": [{"title": "Effect of Chlorella supplementation on cardiovascular risk factors: A meta-analysis of randomized controlled trials.", "authors": "Fallah AA, Sarmast E, Habibian Dehkordi S, et al.", "year": 2018, "journal": "Clinical Nutrition", "doi": "10.1016/j.clnu.2017.09.019", "pmid": "29037431", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/29037431/", "type": "meta-analysis", "summary": "This meta-analysis pooled 19 randomized trials with 797 participants testing Chlorella on cardiovascular risk factors. Chlorella lowered total cholesterol by about 9 mg/dL, LDL by 8 mg/dL, systolic blood pressure by 4.5 mmHg and fasting glucose by 4 mg/dL, with no change in triglycerides, HDL or BMI. Benefits appeared mainly at 4 g/day or more for at least 8 weeks and in people with existing risk factors; trials were small.", "highlight": "Chlorella supplementation improved levels of TC, LDL-C, SBP, DBP, and FBG but the changes in TG, HDL-C, and BMI were not satisfactory", "apa": "Fallah, A. A., Sarmast, E., Habibian Dehkordi, S., Engardeh, J., Mahmoodnia, L., Khaledifar, A., &amp; Jafari, T. (2018). Effect of Chlorella supplementation on cardiovascular risk factors: A meta-analysis of randomized controlled trials. <i>Clinical Nutrition</i>, <i>37</i>(6), 1892–1901. <a href=\"https://doi.org/10.1016/j.clnu.2017.09.019\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.clnu.2017.09.019</a>"}, {"title": "Beneficial effects of Chlorella species supplementation in the general population: a GRADE-assessed systematic review and dose-response meta-analysis.", "authors": "Mardani H, Karimi MA, Sharifi M, et al.", "year": 2026, "journal": "Nutrition & Diabetes", "doi": "10.1038/s41387-026-00449-3", "pmid": "42420253", "pmcid": "PMC13631250", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13631250/", "type": "meta-analysis", "summary": "This GRADE-assessed meta-analysis pooled 24 studies of Chlorella in the general population, searched through February 2025. Chlorella produced small reductions in LDL (about 6 mg/dL), total cholesterol (8 mg/dL), body weight (1.3 kg), insulin resistance and hs-CRP. Certainty of evidence was rated low to very low for nearly every outcome, so these are hints, not established effects.", "highlight": "given the overall very low certainty of evidence based on the GRADE assessment, these results should be interpreted cautiously", "apa": "Mardani, H., Karimi, M. A., Sharifi, M., Ghazvineh, D., Yari, Z., &amp; Jafari, A. (2026). Beneficial effects of Chlorella species supplementation in the general population: a GRADE-assessed systematic review and dose–response meta-analysis. <i>Nutrition &amp;amp; Diabetes</i>, <i>16</i>(1), 44. <a href=\"https://doi.org/10.1038/s41387-026-00449-3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41387-026-00449-3</a>"}, {"title": "The Role of Chlorella and Spirulina as Adjuvants of Cardiovascular Risk Factor Control: A Systematic Review and Meta-Analysis of Randomised Controlled Trials.", "authors": "Pinto-Leite M, Martins D, Ferreira AC, et al.", "year": 2025, "journal": "Nutrients", "doi": "10.3390/nu17060943", "pmid": "40289965", "pmcid": "PMC11945647", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC11945647/", "type": "meta-analysis", "summary": "This meta-analysis pooled 12 randomized trials of Chlorella (168-279 participants per outcome) and 9 of Spirulina on blood pressure, lipids and glucose. It found Chlorella had a neutral effect on blood pressure and blood lipids, while Spirulina modestly lowered diastolic pressure. This contradicts earlier positive pooled results and shows the Chlorella evidence is small and inconsistent.", "highlight": "Our analysis showed that Chlorella supplementation had a neutral effect on BP and lipemia.", "apa": "Pinto-Leite, M., Martins, D., Ferreira, A. C., Silva, C., Trindade, F., Saraiva, F., Vitorino, R., Barros, R., Lima, P. A., Leite-Moreira, A., Ferreira, J. P., S. Barros, A., &amp; Miranda, I. M. (2025). The Role of Chlorella and Spirulina as Adjuvants of Cardiovascular Risk Factor Control: A Systematic Review and Meta-Analysis of Randomised Controlled Trials. <i>Nutrients</i>, <i>17</i>(6), 943. <a href=\"https://doi.org/10.3390/nu17060943\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/nu17060943</a>"}]}, {"id": "fenugreek", "label": "Fenugreek", "title": "Fenugreek", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack.", "sources": [{"title": "Effect of fenugreek (Trigonella foenum-graecum L.) intake on glycemia: a meta-analysis of clinical trials.", "authors": "Neelakantan N, Narayanan M, de Souza RJ, et al.", "year": 2014, "journal": "Nutr J", "doi": "10.1186/1475-2891-13-7", "pmid": "24438170", "pmcid": "PMC3901758", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC3901758/", "type": "meta-analysis", "summary": "This meta-analysis pooled 10 clinical trials lasting at least a week that compared fenugreek seed with a control. Fenugreek lowered fasting glucose by 0.96 mmol/L and HbA1c by 0.85 percentage points, but only in people with diabetes taking medium or high doses. Most trials were of low quality and results varied widely, so the effect in people with normal blood sugar is unproven.", "highlight": "Results from clinical trials support beneficial effects of fenugreek seeds on glycemic control in persons with diabetes.", "apa": "Neelakantan, N., Narayanan, M., de Souza, R. J., &amp; van Dam, R. M. (2014). Effect of fenugreek (Trigonella foenum-graecumL.) intake on glycemia: a meta-analysis of clinical trials. <i>Nutrition Journal</i>, <i>13</i>(1), 7. <a href=\"https://doi.org/10.1186/1475-2891-13-7\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1186/1475-2891-13-7</a>"}, {"title": "The Effect of Fenugreek in Type 2 Diabetes and Prediabetes: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.", "authors": "Kim J, Noh W, Kim A, et al.", "year": 2023, "journal": "Int J Mol Sci", "doi": "10.3390/ijms241813999", "pmid": "37762302", "pmcid": "PMC10531284", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10531284/", "type": "meta-analysis", "summary": "This newer meta-analysis pooled 10 randomized trials (706 people) of fenugreek in type 2 diabetes and prediabetes. Fenugreek lowered fasting glucose, 2-hour glucose, and HbA1c, and improved total cholesterol, triglycerides, and HDL, with only mild stomach side effects. It did not improve insulin resistance (HOMA-IR) and the trials were small, so it is an add-on for people with high blood sugar, not a treatment on its own.", "highlight": "Fenugreek significantly reduced FBG, 2-hPG, and HbA1c, but it did not significantly decrease HOMA-IR.", "apa": "Kim, J., Noh, W., Kim, A., Choi, Y., &amp; Kim, Y.-S. (2023). The Effect of Fenugreek in Type 2 Diabetes and Prediabetes: A Systematic Review and Meta-Analysis of Randomized Controlled Trials. <i>International Journal of Molecular Sciences</i>, <i>24</i>(18), 13999. <a href=\"https://doi.org/10.3390/ijms241813999\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/ijms241813999</a>"}, {"title": "Effects of oral fenugreek-derived preparations on testosterone-related outcomes in adult men: a systematic review and meta-analysis of randomized placebo-controlled trials.", "authors": "Yang P, Niu Z, Guo J, et al.", "year": 2026, "journal": "Front Nutr", "doi": "10.3389/fnut.2026.1903508", "pmid": "42688439", "pmcid": "PMC13534118", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13534118/", "type": "meta-analysis", "summary": "This 2026 meta-analysis reviewed 13 randomized placebo-controlled trials of fenugreek products in adult men, with 6 contributing to the total-testosterone analysis. It found a small rise in total testosterone (SMD 0.25) and no reliable change in free testosterone. No trial was at low risk of bias and certainty was rated very low, and many trials were industry-sponsored extracts, so testosterone claims are not supported.", "highlight": "Current evidence does not support clinical or commercial testosterone-boosting claims.", "apa": "Yang, P., Niu, Z., Guo, J., Huang, T., Chang, D., &amp; Huang, X. (2026). Effects of oral fenugreek-derived preparations on testosterone-related outcomes in adult men: a systematic review and meta-analysis of randomized placebo-controlled trials. <i>Frontiers in Nutrition</i>, <i>13</i>, 1903508. <a href=\"https://doi.org/10.3389/fnut.2026.1903508\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3389/fnut.2026.1903508</a>"}]}, {"id": "turmeric", "label": "Turmeric", "title": "Turmeric (curcumin)", "tier": "supplements", "group": null, "blurb": "My addition; not in the Blueprint stack. Take with black pepper and fat for absorption.", "sources": [{"title": "Efficacy of Turmeric Extracts and Curcumin for Alleviating the Symptoms of Joint Arthritis: A Systematic Review and Meta-Analysis of Randomized Clinical Trials.", "authors": "Daily JW, Yang M, Park S", "year": 2016, "journal": "J Med Food", "doi": "10.1089/jmf.2016.3705", "pmid": "27533649", "pmcid": "PMC5003001", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5003001/", "type": "meta-analysis", "summary": "This meta-analysis pooled 8 randomized trials of turmeric extract or curcumin (about 1,000 mg/day of curcumin) for arthritis, mostly knee osteoarthritis. Curcumin cut pain scores by about 2 points on a 10-point scale versus placebo and performed about the same as pain medication. The trials were few and small, so the authors say the evidence is promising but not definitive.", "highlight": "these RCTs provide scientific evidence that supports the efficacy of turmeric extract (about 1000 mg/day of curcumin) in the treatment of arthritis.", "apa": "Daily, J. W., Yang, M., &amp; Park, S. (2016). Efficacy of Turmeric Extracts and Curcumin for Alleviating the Symptoms of Joint Arthritis: A Systematic Review and Meta-Analysis of Randomized Clinical Trials. <i>Journal of Medicinal Food</i>, <i>19</i>(8), 717–729. <a href=\"https://doi.org/10.1089/jmf.2016.3705\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1089/jmf.2016.3705</a>"}, {"title": "Anti-inflammatory effects of oral supplementation with curcumin: a systematic review and meta-analysis of randomized controlled trials.", "authors": "Ferguson JJA, Abbott KA, Garg ML", "year": 2021, "journal": "Nutr Rev", "doi": "10.1093/nutrit/nuaa114", "pmid": "34378053", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/34378053/", "type": "meta-analysis", "summary": "This meta-analysis reviewed 32 randomized trials (2,038 people) of oral curcumin and blood markers of inflammation, pooling 28 of them. Curcumin lowered CRP by 1.55 mg/L and also reduced IL-6 and TNF-alpha. These are biomarker changes rather than disease outcomes, and the best dose, duration, and formulation remain unsettled.", "highlight": "These findings provide evidence for the anti-inflammatory effects of curcumin and support further investigation to confirm dose, duration, and formulation", "apa": "Ferguson, J. J. A., Abbott, K. A., &amp; Garg, M. L. (2020). Anti-inflammatory effects of oral supplementation with curcumin: a systematic review and meta-analysis of randomized controlled trials. <i>Nutrition Reviews</i>, <i>79</i>(9), 1043–1066. <a href=\"https://doi.org/10.1093/nutrit/nuaa114\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/nutrit/nuaa114</a>"}, {"title": "Curcumin: A Review of Its Effects on Human Health.", "authors": "Hewlings SJ, Kalman DS", "year": 2017, "journal": "Foods", "doi": "10.3390/foods6100092", "pmid": "29065496", "pmcid": "PMC5664031", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5664031/", "type": "review", "summary": "This narrative review surveys human research on curcumin for inflammation, arthritis, metabolic syndrome, and exercise recovery. Its key practical point is that plain curcumin is poorly absorbed and quickly cleared, and that pairing it with piperine from black pepper raised bioavailability by about 2,000% in early studies. It is a broad, positive overview rather than a systematic review, so treat its benefit claims as less rigorous than the bioavailability caveat.", "highlight": "Ingesting curcumin by itself does not lead to the associated health benefits due to its poor bioavailability", "apa": "Hewlings, S., &amp; Kalman, D. (2017). Curcumin: A Review of Its Effects on Human Health. <i>Foods</i>, <i>6</i>(10), 92. <a href=\"https://doi.org/10.3390/foods6100092\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.3390/foods6100092</a>"}]}, {"id": "run5k", "label": "Long run 5K+", "title": "Long run, 5K+", "tier": "weekly", "group": null, "blurb": "One easy long run a week of at least 5 km.", "sources": [{"title": "Is running associated with a lower risk of all-cause, cardiovascular and cancer mortality, and is the more the better? A systematic review and meta-analysis", "authors": "Pedisic Z, Shrestha N, Kovalchik S, et al.", "year": 2020, "journal": "British journal of sports medicine", "doi": "10.1136/bjsports-2018-100493", "pmid": "31685526", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/31685526/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 14 studies from six prospective cohorts with 232,149 participants and 25,951 deaths. Any running was associated with 27% lower all-cause, 30% lower cardiovascular and 23% lower cancer mortality compared with no running. No dose-response was found for frequency, duration, pace or volume, so a single weekly run captures much of the benefit and more is not clearly better.", "highlight": "Any amount of running, even just once a week, is better than no running", "apa": "Pedisic, Z., Shrestha, N., Kovalchik, S., Stamatakis, E., Liangruenrom, N., Grgic, J., Titze, S., Biddle, S. J., Bauman, A. E., &amp; Oja, P. (2019). Is running associated with a lower risk of all-cause, cardiovascular and cancer mortality, and is the more the better? A systematic review and meta-analysis. <i>British Journal of Sports Medicine</i>, <i>54</i>(15), 898–905. <a href=\"https://doi.org/10.1136/bjsports-2018-100493\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bjsports-2018-100493</a>"}, {"title": "Leisure-time running reduces all-cause and cardiovascular mortality risk", "authors": "Lee DC, Pate RR, Lavie CJ, et al.", "year": 2014, "journal": "Journal of the American College of Cardiology", "doi": "10.1016/j.jacc.2014.04.058", "pmid": "25082581", "pmcid": "PMC4131752", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4131752/", "type": "cohort", "summary": "Prospective cohort of 55,137 adults in the Aerobics Center Longitudinal Study followed for a mean of 15 years. Runners had 30% lower all-cause and 45% lower cardiovascular mortality than non-runners, about 3 extra years of life expectancy, and even under 6 miles a week was enough. It is observational and runners may differ from non-runners in other ways, but persistent runners over time saw the largest benefit.", "highlight": "Compared with nonrunners, runners had 30% and 45% lower adjusted risks of all-cause and cardiovascular mortality, respectively, with a 3-year life expectancy benefit", "apa": "Lee, D.-c., Pate, R. R., Lavie, C. J., Sui, X., Church, T. S., &amp; Blair, S. N. (2014). Leisure-Time Running Reduces All-Cause and Cardiovascular Mortality Risk. <i>Journal of the American College of Cardiology</i>, <i>64</i>(5), 472–481. <a href=\"https://doi.org/10.1016/j.jacc.2014.04.058\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jacc.2014.04.058</a>"}, {"title": "Cardiorespiratory fitness as a quantitative predictor of all-cause mortality and cardiovascular events in healthy men and women: a meta-analysis", "authors": "Kodama S, Saito K, Tanaka S, et al.", "year": 2009, "journal": "JAMA", "doi": "10.1001/jama.2009.681", "pmid": "19454641", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/19454641/", "type": "meta-analysis", "summary": "Meta-analysis of 33 cohort studies with about 103,000 healthy adults linking measured cardiorespiratory fitness to mortality and heart disease. Each 1-MET higher fitness level, roughly a 1 km/h faster running speed, was associated with 13% lower all-cause mortality and 15% lower cardiovascular events. Low-fit people (under 7.9 METs) had 70% higher mortality than high-fit people, so regular running is a practical way to move up the fitness scale.", "highlight": "Better CRF was associated with lower risk of all-cause mortality and CHD/CVD", "apa": "Kodama, S. (2009). Cardiorespiratory Fitness as a Quantitative Predictor of All-Cause Mortality and Cardiovascular Events in Healthy Men and Women. <i>Jama</i>, <i>301</i>(19), 2024. <a href=\"https://doi.org/10.1001/jama.2009.681\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2009.681</a>"}]}, {"id": "zone2", "label": "7 hrs Zone 2", "title": "7 hours of Zone 2", "tier": "weekly", "group": null, "blurb": "Seven hours a week of easy, conversational cardio (about 60–70% of max heart rate): you can talk, but not sing.", "sources": [{"title": "Leisure time physical activity and mortality: a detailed pooled analysis of the dose-response relationship", "authors": "Arem H, Moore SC, Patel A, Hartge P, et al.", "year": 2015, "journal": "JAMA Internal Medicine", "doi": "10.1001/jamainternmed.2015.0533", "pmid": "25844730", "pmcid": "PMC4451435", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4451435/", "type": "cohort", "summary": "This pooled six US and European cohorts covering 661,137 adults and 116,686 deaths over a median of 14 years of follow-up. Meeting the 150-minute moderate-activity minimum was linked to 31% lower mortality, with the benefit leveling off at 3-5 times that amount (39% lower) and no sign of harm at 10 times or more. It is observational and self-reported, so fitter, healthier people may simply exercise more, but the dose-response shape is consistent.", "highlight": "An upper threshold for mortality benefit occurred at 3 to 5 times the physical activity recommendation", "apa": "Arem, H., Moore, S. C., Patel, A., Hartge, P., Berrington de Gonzalez, A., Visvanathan, K., Campbell, P. T., Freedman, M., Weiderpass, E., Adami, H. O., Linet, M. S., Lee, I.-M., &amp; Matthews, C. E. (2015). Leisure Time Physical Activity and Mortality. <i>JAMA Internal Medicine</i>, <i>175</i>(6), 959. <a href=\"https://doi.org/10.1001/jamainternmed.2015.0533\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jamainternmed.2015.0533</a>"}, {"title": "Long-Term Leisure-Time Physical Activity Intensity and All-Cause and Cause-Specific Mortality: A Prospective Cohort of US Adults", "authors": "Lee DH, Rezende LFM, Joh HK, Keum N, et al.", "year": 2022, "journal": "Circulation", "doi": "10.1161/CIRCULATIONAHA.121.058162", "pmid": "35876019", "pmcid": "PMC9378548", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9378548/", "type": "cohort", "summary": "This study followed 116,221 US nurses and health professionals for 30 years, with activity reassessed up to 15 times, and recorded 47,596 deaths. Meeting the moderate-activity guideline (150-299 min/week) was tied to 19-25% lower mortality, and the near-maximum benefit came at about 300-600 min/week of moderate activity. Above that there was no clear extra benefit or harm, and the cohort is mostly white health professionals, so causation and generalizability are limited.", "highlight": "Meeting the long-term leisure-time MPA guideline (150-299 min/wk) was similarly associated with lower mortality", "apa": "Lee, D. H., Rezende, L. F., Joh, H.-K., Keum, N., Ferrari, G., Rey-Lopez, J. P., Rimm, E. B., Tabung, F. K., &amp; Giovannucci, E. L. (2022). Long-Term Leisure-Time Physical Activity Intensity and All-Cause and Cause-Specific Mortality: A Prospective Cohort of US Adults. <i>Circulation</i>, <i>146</i>(7), 523–534. <a href=\"https://doi.org/10.1161/CIRCULATIONAHA.121.058162\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/CIRCULATIONAHA.121.058162</a>"}, {"title": "Much Ado About Zone 2: A Narrative Review Assessing the Efficacy of Zone 2 Training for Improving Mitochondrial Capacity and Cardiorespiratory Fitness in the General Population", "authors": "Storoschuk KL, Moran-MacDonald A, Gibala MJ, Gurd BJ", "year": 2025, "journal": "Sports Medicine", "doi": "10.1007/s40279-025-02261-y", "pmid": "40560504", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/40560504/", "type": "review", "summary": "This narrative review examines the training-study evidence behind the popular claim that Zone 2 (below lactate threshold) is the best intensity for mitochondria and fat oxidation. It concludes the evidence does not support Zone 2 as optimal, and that higher intensities matter more when weekly training time is limited. Zone 2 is still useful as volume, but the specific mitochondrial hype comes mostly from observations of elite athletes, not trials in ordinary people.", "highlight": "We conclude that current evidence does not support Zone 2 training as the optimal intensity for improving mitochondrial or fatty acid oxidative capacity.", "apa": "Storoschuk, K. L., Moran-MacDonald, A., Gibala, M. J., &amp; Gurd, B. J. (2025). Much Ado About Zone 2: A Narrative Review Assessing the Efficacy of Zone 2 Training for Improving Mitochondrial Capacity and Cardiorespiratory Fitness in the General Population. <i>Sports Medicine</i>, <i>55</i>(7), 1611–1624. <a href=\"https://doi.org/10.1007/s40279-025-02261-y\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s40279-025-02261-y</a>"}]}, {"id": "zone5", "label": "Zone 5 training", "title": "Zone 5 training (VO2 max)", "tier": "weekly", "group": null, "blurb": "One session a week of near-max intervals. The best-studied version is the Norwegian 4×4 method from NTNU: after a warm-up, 4 minutes at 90–95% of max heart rate, then 3 minutes of easy recovery, repeated 4 times (about 40 minutes in all). It is the protocol most consistently shown to raise VO2 max.", "sources": [{"title": "Superior cardiovascular effect of aerobic interval training versus moderate continuous training in heart failure patients: a randomized study", "authors": "Wisløff U, Støylen A, Loennechen JP, Bruvold M, et al.", "year": 2007, "journal": "Circulation", "doi": "10.1161/CIRCULATIONAHA.106.675041", "pmid": "17548726", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/17548726/", "type": "RCT", "summary": "This trial randomized 27 elderly patients with post-heart-attack heart failure to 4x4-minute intervals at 95% of peak heart rate, moderate continuous training at 70%, or usual care, three times a week for 12 weeks. VO2peak rose 46% with intervals versus 14% with moderate training, and only the interval group showed reverse remodeling of the heart. It is the founding study of the Norwegian 4x4, but it was very small and a much larger later trial (SMARTEX-HF) did not confirm intervals were superior.", "highlight": "VO2peak increased more with aerobic interval training than moderate continuous training (46% versus 14%, P<0.001)", "apa": "Wisløff, U., Støylen, A., Loennechen, J. P., Bruvold, M., Rognmo, Ø., Haram, P. M., Tjønna, A. E., Helgerud, J., Slørdahl, S. A., Lee, S. J., Videm, V., Bye, A., Smith, G. L., Najjar, S. M., Ellingsen, Ø., &amp; Skjærpe, T. (2007). Superior Cardiovascular Effect of Aerobic Interval Training Versus Moderate Continuous Training in Heart Failure Patients. <i>Circulation</i>, <i>115</i>(24), 3086–3094. <a href=\"https://doi.org/10.1161/CIRCULATIONAHA.106.675041\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1161/CIRCULATIONAHA.106.675041</a>"}, {"title": "Effect of exercise training for five years on all cause mortality in older adults-the Generation 100 study: randomised controlled trial", "authors": "Stensvold D, Viken H, Steinshamn SL, Dalen H, et al.", "year": 2020, "journal": "BMJ", "doi": "10.1136/bmj.m3485", "pmid": "33028588", "pmcid": "PMC7539760", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7539760/", "type": "RCT", "summary": "Generation 100 randomized 1,567 Norwegians aged 70-77 to twice-weekly 4x4 intervals at about 90% of peak heart rate, moderate continuous training, or national activity guidelines for five years. Overall mortality did not differ between exercise and control groups, though HIIT trended lower (HR 0.63 vs control; 0.51 vs moderate training, confidence intervals crossing 1). The result is a trend, not proof, and the participants were already healthy and active, which made differences hard to detect.", "highlight": "we observed a lower all cause mortality trend after HIIT compared with controls and MICT", "apa": "Stensvold, D., Viken, H., Steinshamn, S. L., Dalen, H., Støylen, A., Loennechen, J. P., Reitlo, L. S., Zisko, N., Bækkerud, F. H., Tari, A. R., Sandbakk, S. B., Carlsen, T., Ingebrigtsen, J. E., Lydersen, S., Mattsson, E., Anderssen, S. A., Fiatarone Singh, M. A., Coombes, J. S., Skogvoll, E., . . . Wisløff, U. (2020). Effect of exercise training for five years on all cause mortality in older adults—the Generation 100 study: randomised controlled trial. <i>BMJ</i>, m3485. <a href=\"https://doi.org/10.1136/bmj.m3485\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bmj.m3485</a>"}, {"title": "Effectiveness of High-Intensity Interval Training (HIT) and Continuous Endurance Training for VO2max Improvements: A Systematic Review and Meta-Analysis of Controlled Trials", "authors": "Milanović Z, Sporiš G, Weston M", "year": 2015, "journal": "Sports Medicine", "doi": "10.1007/s40279-015-0365-0", "pmid": "26243014", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/26243014/", "type": "meta-analysis", "summary": "This meta-analysis pooled 28 controlled trials (723 healthy adults aged 18-45) comparing interval training, continuous endurance training and no exercise on VO2max. Both raised VO2max substantially (about 5.5 and 4.9 mL/kg/min versus controls), with intervals adding a small extra gain of about 1.2 mL/kg/min over continuous training. The edge for intervals is real but small, and the trials were short and mostly in young people.", "highlight": "Endurance training and HIT both elicit large improvements in the VO2max of healthy, young to middle-aged adults", "apa": "Milanović, Z., Sporiš, G., &amp; Weston, M. (2015). Effectiveness of High-Intensity Interval Training (HIT) and Continuous Endurance Training for VO2max Improvements: A Systematic Review and Meta-Analysis of Controlled Trials. <i>Sports Medicine</i>, <i>45</i>(10), 1469–1481. <a href=\"https://doi.org/10.1007/s40279-015-0365-0\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s40279-015-0365-0</a>"}]}, {"id": "stability", "label": "Stability training", "title": "Stability training", "tier": "weekly", "group": null, "blurb": "", "sources": [{"title": "Exercise for preventing falls in older people living in the community", "authors": "Sherrington C, Fairhall NJ, Wallbank GK, et al.", "year": 2019, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD012424.pub2", "pmid": "30703272", "pmcid": "PMC6360922", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6360922/", "type": "systematic review", "summary": "", "highlight": "Exercises that target balance, gait and muscle strength have been found to prevent falls in these people", "apa": "Sherrington, C., Fairhall, N. J., Wallbank, G. K., Tiedemann, A., Michaleff, Z. A., Howard, K., Clemson, L., Hopewell, S., &amp; Lamb, S. E. (2019). Exercise for preventing falls in older people living in the community. <i>Cochrane Database of Systematic Reviews</i>, <i>2019</i>(1). <a href=\"https://doi.org/10.1002/14651858.CD012424.pub2\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD012424.pub2</a>"}, {"title": "Successful 10-second one-legged stance performance predicts survival in middle-aged and older individuals", "authors": "Araujo CG, de Souza e Silva CG, Laukkanen JA, et al.", "year": 2022, "journal": "British Journal of Sports Medicine", "doi": "10.1136/bjsports-2021-105360", "pmid": "35728834", "pmcid": null, "url": "https://doi.org/10.1136/bjsports-2021-105360", "type": "cohort", "summary": "", "highlight": "Balance quickly diminishes after the mid-50s increasing the risk for falls and other adverse health outcomes", "apa": "Araujo, C. G., de Souza e Silva, C. G., Laukkanen, J. A., Fiatarone Singh, M., Kunutsor, S. K., Myers, J., Franca, J. F., &amp; Castro, C. L. (2022). Successful 10-second one-legged stance performance predicts survival in middle-aged and older individuals. <i>British Journal of Sports Medicine</i>, <i>56</i>(17), 975–980. <a href=\"https://doi.org/10.1136/bjsports-2021-105360\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/bjsports-2021-105360</a>"}, {"title": "Effects of Balance Training on Balance Performance in Healthy Older Adults: A Systematic Review and Meta-analysis", "authors": "Lesinski M, Hortobágyi T, Muehlbauer T, Gollhofer A, Granacher U", "year": 2015, "journal": "Sports Medicine", "doi": "10.1007/s40279-015-0375-y", "pmid": "26325622", "pmcid": "PMC4656699", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4656699/", "type": "meta-analysis", "summary": "", "highlight": "The effects of balance training (BT) in older adults on proxies of postural control and mobility are well documented", "apa": "Lesinski, M., Hortobágyi, T., Muehlbauer, T., Gollhofer, A., &amp; Granacher, U. (2015). Effects of Balance Training on Balance Performance in Healthy Older Adults: A Systematic Review and Meta-analysis. <i>Sports Medicine</i>, <i>45</i>(12), 1721–1738. <a href=\"https://doi.org/10.1007/s40279-015-0375-y\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1007/s40279-015-0375-y</a>"}]}, {"id": "social", "label": "Social time", "title": "Social time", "tier": "weekly", "group": null, "blurb": "Real time with friends or family, in person, every week.", "sources": [{"title": "Social relationships and mortality risk: a meta-analytic review", "authors": "Holt-Lunstad J, Smith TB, Layton JB", "year": 2010, "journal": "PLoS medicine", "doi": "10.1371/journal.pmed.1000316", "pmid": "20668659", "pmcid": "PMC2910600", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2910600/", "type": "meta-analysis", "summary": "Meta-analysis of 148 prospective studies (308,849 people, average follow-up about 7.5 years) on social relationships and mortality. People with stronger social relationships had 50% greater odds of survival (OR 1.50), and complex measures of social integration showed an even larger effect (OR 1.91). The authors compare the effect to smoking and exceeding obesity and inactivity, but these are observational data that cannot fully separate cause from confounding by health.", "highlight": "The influence of social relationships on risk for mortality is comparable with well-established risk factors for mortality", "apa": "Holt-Lunstad, J., Smith, T. B., &amp; Layton, J. B. (2010). Social Relationships and Mortality Risk: A Meta-analytic Review. <i>PLoS Medicine</i>, <i>7</i>(7), e1000316. <a href=\"https://doi.org/10.1371/journal.pmed.1000316\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1371/journal.pmed.1000316</a>"}, {"title": "Loneliness and social isolation as risk factors for mortality: a meta-analytic review", "authors": "Holt-Lunstad J, Smith TB, Baker M, et al.", "year": 2015, "journal": "Perspectives on psychological science : a journal of the Association for Psychological Science", "doi": "10.1177/1745691614568352", "pmid": "25910392", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/25910392/", "type": "meta-analysis", "summary": "Meta-analysis of prospective studies (70 studies, about 3.4 million people) on objective social isolation, subjective loneliness and living alone as predictors of death. After adjusting for confounders, social isolation raised the odds of death by 29%, loneliness by 26%, and living alone by 32%. Effects were stronger in people under 65, and like all such data it is observational, but it shows both being alone and feeling alone carry risk.", "highlight": "social isolation odds ratio (OR) = 1.29, loneliness OR = 1.26, and living alone OR = 1.32", "apa": "Holt-Lunstad, J., Smith, T. B., Baker, M., Harris, T., &amp; Stephenson, D. (2015). Loneliness and Social Isolation as Risk Factors for Mortality. <i>Perspectives on Psychological Science</i>, <i>10</i>(2), 227–237. <a href=\"https://doi.org/10.1177/1745691614568352\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1177/1745691614568352</a>"}, {"title": "Loneliness and social isolation as risk factors for coronary heart disease and stroke: systematic review and meta-analysis of longitudinal observational studies", "authors": "Valtorta NK, Kanaan M, Gilbody S, et al.", "year": 2016, "journal": "Heart (British Cardiac Society)", "doi": "10.1136/heartjnl-2015-308790", "pmid": "27091846", "pmcid": "PMC4941172", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4941172/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 16 longitudinal datasets (4,628 coronary heart disease and 3,002 stroke events over 3-21 years) in high-income countries. Poor social relationships were linked to a 29% higher risk of coronary heart disease (RR 1.29) and a 32% higher risk of stroke (RR 1.32). Confidence intervals were wide and it is unknown whether interventions that reduce loneliness lower these risks, but it points to cardiovascular disease as one pathway.", "highlight": "Poor social relationships were associated with a 29% increase in risk of incident CHD", "apa": "Valtorta, N. K., Kanaan, M., Gilbody, S., Ronzi, S., &amp; Hanratty, B. (2016). Loneliness and social isolation as risk factors for coronary heart disease and stroke: systematic review and meta-analysis of longitudinal observational studies. <i>Heart</i>, <i>102</i>(13), 1009–1016. <a href=\"https://doi.org/10.1136/heartjnl-2015-308790\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1136/heartjnl-2015-308790</a>"}]}, {"id": "nature", "label": "Time in nature", "title": "Time in nature", "tier": "weekly", "group": null, "blurb": "About two hours a week in parks, forests, beaches or trails. It can be split up across the week.", "sources": [{"title": "Spending at least 120 minutes a week in nature is associated with good health and wellbeing", "authors": "White MP, Alcock I, Grellier J, et al.", "year": 2019, "journal": "Scientific reports", "doi": "10.1038/s41598-019-44097-3", "pmid": "31197192", "pmcid": "PMC6565732", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6565732/", "type": "cohort", "summary": "Cross-sectional analysis of 19,806 adults from England's nationally representative MENE survey, relating time spent in nature in the past 7 days to self-reported health and wellbeing. People with at least 120 minutes of nature contact per week were more likely to report good health (OR 1.59) and high wellbeing (OR 1.23), with benefits peaking at 200-300 minutes and no gain below 120. It is cross-sectional and self-reported, so reverse causation is possible, but the 120 min/week threshold is a practical target and can be split across several visits.", "highlight": "Compared to no nature contact last week, the likelihood of reporting good health or high well-being became significantly greater with contact", "apa": "White, M. P., Alcock, I., Grellier, J., Wheeler, B. W., Hartig, T., Warber, S. L., Bone, A., Depledge, M. H., &amp; Fleming, L. E. (2019). Spending at least 120 minutes a week in nature is associated with good health and wellbeing. <i>Scientific Reports</i>, <i>9</i>(1), 7730. <a href=\"https://doi.org/10.1038/s41598-019-44097-3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41598-019-44097-3</a>"}, {"title": "The health benefits of the great outdoors: A systematic review and meta-analysis of greenspace exposure and health outcomes", "authors": "Twohig-Bennett C, Jones A", "year": 2018, "journal": "Environmental research", "doi": "10.1016/j.envres.2018.06.030", "pmid": "29982151", "pmcid": "PMC6562165", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6562165/", "type": "meta-analysis", "summary": "Systematic review and meta-analysis of 143 studies (103 observational, 40 interventional) covering about 100 health outcomes and greenspace exposure. Greater greenspace exposure was associated with lower cortisol, heart rate and diastolic blood pressure, 28% lower type 2 diabetes risk, and lower all-cause (OR 0.69) and cardiovascular mortality. Many pooled results came from poor-quality, highly heterogeneous studies, so the direction is consistent but the effect sizes are uncertain.", "highlight": "Greenspace exposure is associated with numerous health benefits in intervention and observational studies", "apa": "Twohig-Bennett, C., &amp; Jones, A. (2018). The health benefits of the great outdoors: A systematic review and meta-analysis of greenspace exposure and health outcomes. <i>Environmental Research</i>, <i>166</i>, 628–637. <a href=\"https://doi.org/10.1016/j.envres.2018.06.030\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.envres.2018.06.030</a>"}, {"title": "Green spaces and mortality: a systematic review and meta-analysis of cohort studies", "authors": "Rojas-Rueda D, Nieuwenhuijsen MJ, Gascon M, et al.", "year": 2019, "journal": "The Lancet. Planetary health", "doi": "10.1016/S2542-5196(19)30215-3", "pmid": "31777338", "pmcid": "PMC6873641", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6873641/", "type": "meta-analysis", "summary": "WHO-funded meta-analysis of 9 cohort studies (over 8.3 million people in seven countries) relating satellite-measured greenness around the home (NDVI) to all-cause mortality. Each 0.1 increase in greenness within 500 m of home was associated with a 4% lower risk of death (HR 0.96). This measures living near green space, not deliberately spending time in it, and heterogeneity was high, so it supports the general idea rather than a specific weekly dose.", "highlight": "We found evidence of an inverse association between surrounding greenness and all-cause mortality", "apa": "Rojas-Rueda, D., Nieuwenhuijsen, M. J., Gascon, M., Perez-Leon, D., &amp; Mudu, P. (2019). Green spaces and mortality: a systematic review and meta-analysis of cohort studies. <i>The Lancet Planetary Health</i>, <i>3</i>(11), e469–e477. <a href=\"https://doi.org/10.1016/S2542-5196(19)30215-3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/S2542-5196(19)30215-3</a>"}]}, {"id": "algae_dha_weekly", "label": "DHA", "title": "DHA", "tier": "supplements", "group": null, "blurb": "If you don't take algae omega-3 daily, a capsule (~250-500 mg DHA/EPA) two or three times a week is a low-effort way to keep levels up. Recommended by Mic the Vegan: Mic the Vegan: get ALA from chia, flax and walnuts, or take an algae-based DHA supplement two or three times a week, as many plant-based doctors suggest.", "rec_url": "https://www.youtube.com/watch?v=zKwnMCEp3HM", "sources": [{"title": "Blood docosahexaenoic acid and eicosapentaenoic acid in vegans: Associations with age and gender and effects of an algal-derived omega-3 fatty acid supplement", "authors": "Sarter B, Kelsey KS, Schwartz TA, et al.", "year": 2015, "journal": "Clinical Nutrition", "doi": "10.1016/j.clnu.2014.03.003", "pmid": "24679552", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/24679552/", "type": "cohort", "summary": "Cross-sectional measurement of the omega-3 index in 165 long-term vegans, plus an uncontrolled 4-month trial giving 254 mg/day of algal DHA+EPA to 46 vegans with an index below 4%. The average vegan index was 3.7%, and supplementation raised it from 3.1% to 4.8%. There was no placebo group and the dose was daily, so the weekly schedule is an extrapolation from how slowly red-cell omega-3 levels change.", "highlight": "The vegans responded robustly to a relatively low dose of a vegetarian omega-3 supplement", "apa": "Sarter, B., Kelsey, K. S., Schwartz, T. A., &amp; Harris, W. S. (2015). Blood docosahexaenoic acid and eicosapentaenoic acid in vegans: Associations with age and gender and effects of an algal-derived omega-3 fatty acid supplement. <i>Clinical Nutrition</i>, <i>34</i>(2), 212–218. <a href=\"https://doi.org/10.1016/j.clnu.2014.03.003\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.clnu.2014.03.003</a>"}, {"title": "Algal-oil capsules and cooked salmon: nutritionally equivalent sources of docosahexaenoic acid", "authors": "Arterburn LM, Oken HA, Bailey Hall E, et al.", "year": 2008, "journal": "Journal of the American Dietetic Association", "doi": "10.1016/j.jada.2008.04.020", "pmid": "18589030", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/18589030/", "type": "RCT", "summary": "Randomized open-label trial in 32 healthy adults comparing 600 mg/day DHA from algal-oil capsules with the same DHA from cooked salmon for two weeks. DHA rose about 80% in plasma phospholipids and about 25% in red blood cells in both groups, with no meaningful difference between them. It shows algae DHA is absorbed as well as fish DHA, but it is short, small and was run by an algal-oil manufacturer.", "highlight": "algal-oil DHA capsules represent a safe and convenient source of non-fish-derived DHA", "apa": "Arterburn, L. M., Oken, H. A., Bailey Hall, E., Hamersley, J., Kuratko, C. N., &amp; Hoffman, J. P. (2008). Algal-Oil Capsules and Cooked Salmon: Nutritionally Equivalent Sources of Docosahexaenoic Acid. <i>Journal of the American Dietetic Association</i>, <i>108</i>(7), 1204–1209. <a href=\"https://doi.org/10.1016/j.jada.2008.04.020\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jada.2008.04.020</a>"}, {"title": "Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease", "authors": "Abdelhamid AS, Brown TJ, Brainard JS, et al.", "year": 2020, "journal": "The Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD003177.pub5", "pmid": "32114706", "pmcid": "PMC7049091", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7049091/", "type": "meta-analysis", "summary": "Cochrane review of 86 randomized trials (162,796 people) lasting at least a year that raised long-chain omega-3 or ALA intake. Long-chain omega-3 had little or no effect on all-cause mortality (RR 0.97) but slightly reduced coronary heart disease events (RR 0.91) and lowered triglycerides about 15%. This is the honest ceiling: algae DHA fills a nutrient gap for plant-based eaters, but don't expect large heart-protection effects.", "highlight": "Moderate- and low-certainty evidence suggests that increasing LCn3 slightly reduces risk of coronary heart disease mortality and events", "apa": "Abdelhamid, A. S., Brown, T. J., Brainard, J. S., Biswas, P., Thorpe, G. C., Moore, H. J., Deane, K. H., Summerbell, C. D., Worthington, H. V., Song, F., &amp; Hooper, L. (2020). Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease. <i>Cochrane Database of Systematic Reviews</i>, <i>2020</i>(3). <a href=\"https://doi.org/10.1002/14651858.CD003177.pub5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD003177.pub5</a>"}]}, {"id": "run10k", "label": "Long run 10K+", "title": "Long run, 10K+", "tier": "monthly", "group": null, "blurb": "Once a month, go long: 10 km or more.", "sources": [{"title": "Association of Cardiorespiratory Fitness With Long-term Mortality Among Adults Undergoing Exercise Treadmill Testing", "authors": "Mandsager K, Harb S, Cremer P, et al.", "year": 2018, "journal": "JAMA network open", "doi": "10.1001/jamanetworkopen.2018.3605", "pmid": "30646252", "pmcid": "PMC6324439", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6324439/", "type": "cohort", "summary": "Retrospective cohort of 122,007 patients who had treadmill exercise testing at the Cleveland Clinic, followed for a median 8.4 years. Elite fitness was associated with 80% lower mortality than low fitness, and being unfit carried as much or more risk than smoking, diabetes or coronary disease. The cohort was patients referred for testing, not the general public, but no upper limit of benefit was seen for fitness.", "highlight": "Cardiorespiratory fitness is inversely associated with long-term mortality with no observed upper limit of benefit", "apa": "Mandsager, K., Harb, S., Cremer, P., Phelan, D., Nissen, S. E., &amp; Jaber, W. (2018). Association of Cardiorespiratory Fitness With Long-term Mortality Among Adults Undergoing Exercise Treadmill Testing. <i>JAMA Network Open</i>, <i>1</i>(6), e183605. <a href=\"https://doi.org/10.1001/jamanetworkopen.2018.3605\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jamanetworkopen.2018.3605</a>"}, {"title": "Cardiorespiratory Fitness and Mortality Risk Across the Spectra of Age, Race, and Sex", "authors": "Kokkinos P, Faselis C, Samuel IBH, et al.", "year": 2022, "journal": "Journal of the American College of Cardiology", "doi": "10.1016/j.jacc.2022.05.031", "pmid": "35926933", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/35926933/", "type": "cohort", "summary": "Cohort of 750,302 US veterans aged 30-95 with treadmill-measured fitness, followed for a median 10.2 years. The least fit 20% had about 4-fold higher mortality than the most fit, and the lowest risk was around 14 METs with no increase at extremely high fitness. The population was mostly older men, but the graded benefit held across age, sex and race.", "highlight": "Being unfit carried a greater risk than any of the cardiac risk factors examined", "apa": "Kokkinos, P., Faselis, C., Samuel, I. B. H., Pittaras, A., Doumas, M., Murphy, R., Heimall, M. S., Sui, X., Zhang, J., &amp; Myers, J. (2022). Cardiorespiratory Fitness and Mortality Risk Across the Spectra of Age, Race, and Sex. <i>Journal of the American College of Cardiology</i>, <i>80</i>(6), 598–609. <a href=\"https://doi.org/10.1016/j.jacc.2022.05.031\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.jacc.2022.05.031</a>"}, {"title": "Cardiac arrest during long-distance running races", "authors": "Kim JH, Malhotra R, Chiampas G, et al.", "year": 2012, "journal": "The New England journal of medicine", "doi": "10.1056/NEJMoa1106468", "pmid": "22236223", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22236223/", "type": "cohort", "summary": "Registry study of cardiac arrests among 10.9 million runners in US marathons and half-marathons from 2000 to 2010. Cardiac arrest occurred in 0.54 per 100,000 participants, higher in marathons (1.01 per 100,000) than half-marathons and mostly in men, often from hypertrophic cardiomyopathy or coronary disease. The absolute risk of long-distance running is very low, but it is not zero, so training up gradually and checking heart risk factors is sensible.", "highlight": "Marathons and half-marathons are associated with a low overall risk of cardiac arrest and sudden death", "apa": "Kim, J. H., Malhotra, R., Chiampas, G., d&#x27;Hemecourt, P., Troyanos, C., Cianca, J., Smith, R. N., Wang, T. J., Roberts, W. O., Thompson, P. D., &amp; Baggish, A. L. (2012). Cardiac Arrest during Long-Distance Running Races. <i>New England Journal of Medicine</i>, <i>366</i>(2), 130–140. <a href=\"https://doi.org/10.1056/NEJMoa1106468\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1056/NEJMoa1106468</a>"}]}, {"id": "coldplunge", "label": "Cold plunge", "title": "Cold plunge", "tier": "monthly", "group": null, "blurb": "Cold-water immersion, around 10–15°C for 2–5 minutes. Not right after strength training: it can blunt muscle growth.", "sources": [{"title": "Health effects of voluntary exposure to cold water - a continuing subject of debate", "authors": "Esperland D, de Weerd L, Mercer JB", "year": 2022, "journal": "International journal of circumpolar health", "doi": "10.1080/22423982.2022.2111789", "pmid": "36137565", "pmcid": "PMC9518606", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9518606/", "type": "systematic review", "summary": "Literature review of 104 studies on the health effects of voluntary cold-water immersion and winter swimming in humans. Cold water appears to reduce or brown body fat and improve insulin sensitivity, and some studies report benefits for mood and immunity. Most studies were small, often single-sex, and used different temperatures and protocols, so the authors conclude benefits remain unproven and a subject of debate.", "highlight": "Some of the studies indicate that voluntary exposure to cold water has some beneficial health effects", "apa": "Espeland, D., de Weerd, L., &amp; Mercer, J. B. (2022). Health effects of voluntary exposure to cold water – a continuing subject of debate. <i>International Journal of Circumpolar Health</i>, <i>81</i>(1), 2111789. <a href=\"https://doi.org/10.1080/22423982.2022.2111789\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1080/22423982.2022.2111789</a>"}, {"title": "The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial", "authors": "Buijze GA, Sierevelt IN, van der Heijden BC, et al.", "year": 2016, "journal": "PloS one", "doi": "10.1371/journal.pone.0161749", "pmid": "27631616", "pmcid": "PMC5025014", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5025014/", "type": "RCT", "summary": "Randomized trial of 3,018 Dutch adults assigned to finish daily showers with 30, 60 or 90 seconds of cold water, or a usual-shower control, for 30 days then at their discretion for 60 more days. The cold-shower groups had 29% fewer sickness-absence days from work (IRR 0.71), but no reduction in the number of days actually ill. The trial was unblinded and outcomes were self-reported, so the effect may reflect perception or resilience more than immunity; duration of cold did not matter.", "highlight": "A routine (hot-to-) cold shower resulted in a statistical reduction of self-reported sickness absence but not illness days", "apa": "Buijze, G. A., Sierevelt, I. N., van der Heijden, B. C. J. M., Dijkgraaf, M. G., &amp; Frings-Dresen, M. H. W. (2016). The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial. <i>Plos One</i>, <i>11</i>(9), e0161749. <a href=\"https://doi.org/10.1371/journal.pone.0161749\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1371/journal.pone.0161749</a>"}, {"title": "Post-exercise cold water immersion attenuates acute anabolic signalling and long-term adaptations in muscle to strength training", "authors": "Roberts LA, Raastad T, Markworth JF, et al.", "year": 2015, "journal": "The Journal of physiology", "doi": "10.1113/JP270570", "pmid": "26174323", "pmcid": "PMC4594298", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4594298/", "type": "RCT", "summary": "Two linked experiments: 21 active men strength trained for 12 weeks with either 10 minutes of cold-water immersion or active recovery after each session, plus a 9-man biopsy study of acute muscle signalling. The cold-water group gained less strength and muscle; type II fibre size rose 17% and myonuclei 26% with active recovery but not with cold immersion, and anabolic signalling was blunted. If building muscle is a goal, keep cold plunges away from lifting sessions (separate by several hours or do them on non-lifting days).", "highlight": "CWI attenuates the acute changes in satellite cell numbers and activity of kinases that regulate muscle hypertrophy", "apa": "Roberts, L. A., Raastad, T., Markworth, J. F., Figueiredo, V. C., Egner, I. M., Shield, A., Cameron‐Smith, D., Coombes, J. S., &amp; Peake, J. M. (2015). Post‐exercise cold water immersion attenuates acute anabolic signalling and long‐term adaptations in muscle to strength training. <i>The Journal of Physiology</i>, <i>593</i>(18), 4285–4301. <a href=\"https://doi.org/10.1113/JP270570\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1113/JP270570</a>"}]}, {"id": "fast24", "label": "24-hour fast", "title": "24-hour fast", "tier": "monthly", "group": null, "blurb": "Once a month: dinner to dinner, water, tea and black coffee only. Skip it if you are on insulin or glucose-lowering drugs without a doctor's plan.", "sources": [{"title": "Randomized controlled trial of once-per-week intermittent fasting for health improvement: the WONDERFUL trial", "authors": "Bartholomew CL, Muhlestein JB, May HT, et al.", "year": 2021, "journal": "European Heart Journal Open", "doi": "10.1093/ehjopen/oeab026", "pmid": "35919268", "pmcid": "PMC9241570", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9241570/", "type": "RCT", "summary": "Intermountain researchers randomized 103 adults with metabolic syndrome features and modestly high LDL to 24-hour water-only fasts (twice weekly for 4 weeks, then once weekly for 22 weeks) or normal eating. The fasting did not lower LDL (the primary outcome) but did improve insulin resistance (HOMA-IR -0.75 vs -0.10) and metabolic syndrome score. Dropout was high (only 71 of 103 finished) and the schedule was weekly, so a once-a-month 24-hour fast is a much smaller dose than what was tested.", "highlight": "A low-frequency intermittent fasting regimen did not reduce LDL-C or improve cognitive function but significantly reduced both HOMA-IR and MSS.", "apa": "Bartholomew, C. L., Muhlestein, J. B., May, H. T., Le, V. T., Galenko, O., Garrett, K. D., Brunker, C., Hopkins, R. O., Carlquist, J. F., Knowlton, K. U., Anderson, J. L., Bailey, B. W., &amp; Horne, B. D. (2021). Randomized controlled trial of once-per-week intermittent fasting for health improvement: the WONDERFUL trial. <i>European Heart Journal Open</i>, <i>1</i>(2), oeab026. <a href=\"https://doi.org/10.1093/ehjopen/oeab026\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1093/ehjopen/oeab026</a>"}, {"title": "Relation of routine, periodic fasting to risk of diabetes mellitus, and coronary artery disease in patients undergoing coronary angiography", "authors": "Horne BD, Muhlestein JB, May HT, et al.", "year": 2012, "journal": "American Journal of Cardiology", "doi": "10.1016/j.amjcard.2012.01.379", "pmid": "22425331", "pmcid": null, "url": "https://doi.org/10.1016/j.amjcard.2012.01.379", "type": "cohort", "summary": "Intermountain surveyed 200 patients having coronary angiography about routine periodic fasting (largely the monthly Latter-day Saint fast) and pooled them with 448 patients from an earlier study. Routine fasters had less diabetes (10.3% vs 22.0%, OR 0.41) and less coronary artery disease (63.2% vs 75.0%, OR 0.42). This is observational and fasters in Utah differ in religion and lifestyle from non-fasters, so it shows association, not that monthly fasting causes the benefit.", "highlight": "prospective hypothesis testing showed that routine periodic fasting was associated with a lower prevalence of DM in patients undergoing coronary angiography", "apa": "Horne, B. D., Muhlestein, J. B., May, H. T., Carlquist, J. F., Lappé, D. L., Bair, T. L., &amp; Anderson, J. L. (2012). Relation of Routine, Periodic Fasting to Risk of Diabetes Mellitus, and Coronary Artery Disease in Patients Undergoing Coronary Angiography. <i>The American Journal of Cardiology</i>, <i>109</i>(11), 1558–1562. <a href=\"https://doi.org/10.1016/j.amjcard.2012.01.379\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.amjcard.2012.01.379</a>"}, {"title": "Flipping the Metabolic Switch: Understanding and Applying the Health Benefits of Fasting", "authors": "Anton SD, Moehl K, Donahoo WT, et al.", "year": 2018, "journal": "Obesity (Silver Spring)", "doi": "10.1002/oby.22065", "pmid": "29086496", "pmcid": "PMC5783752", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5783752/", "type": "review", "summary": "This narrative review (Anton, Mattson and colleagues) describes what happens physiologically when a fast runs long enough to deplete liver glycogen and shift the body to burning fat and ketones. That 'metabolic switch' typically begins beyond about 12 hours without food, so a 24-hour fast clearly crosses it, and the authors argue it triggers stress-resistance and repair pathways. Much of the mechanistic support comes from animal studies, and the review itself calls for human trials that measure ketones to confirm dose and effect.", "highlight": "the point of negative energy balance at which liver glycogen stores are depleted and fatty acids are mobilized (typically beyond 12 hours after cessation of food intake)", "apa": "Anton, S. D., Moehl, K., Donahoo, W. T., Marosi, K., Lee, S. A., Mainous, A. G., Leeuwenburgh, C., &amp; Mattson, M. P. (2017). Flipping the Metabolic Switch: Understanding and Applying the Health Benefits of Fasting. <i>Obesity</i>, <i>26</i>(2), 254–268. <a href=\"https://doi.org/10.1002/oby.22065\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/oby.22065</a>"}]}, {"id": "parasite", "label": "Parasite cleanse", "title": "Parasite cleanse", "tier": "annual", "group": null, "blurb": "Once a year. The options: ivermectin (prescription), pyrantel pamoate (over the counter in the US), or papaya seeds with pumpkin seeds. The studies below were all done in people with confirmed infections, so a stool test first (ova & parasites) tells you whether there's anything to treat. Ask a doctor before taking ivermectin.", "sources": [{"title": "Ivermectin versus albendazole or thiabendazole for Strongyloides stercoralis infection.", "authors": "Henriquez-Camacho C, Gotuzzo E, Echevarria J, et al.", "year": 2016, "journal": "Cochrane Database of Systematic Reviews", "doi": "10.1002/14651858.CD007745.pub3", "pmid": "26778150", "pmcid": "PMC4916931", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4916931/", "type": "systematic review", "summary": "This Cochrane review pooled seven randomized trials (1147 participants) comparing ivermectin with albendazole or thiabendazole in people with confirmed chronic Strongyloides infection. Ivermectin cured more people than albendazole (risk ratio 1.79, moderate-quality evidence) and was at least as well tolerated, with no serious adverse events reported. It applies only to diagnosed infection, ivermectin is prescription-only in the US, and nothing here supports taking it as a routine yearly cleanse.", "highlight": "Ivermectin results in more people cured than albendazole, and is at least as well tolerated.", "apa": "Henriquez-Camacho, C., Gotuzzo, E., Echevarria, J., White Jr, A. C., Terashima, A., Samalvides, F., Pérez-Molina, J. A., &amp; Plana, M. N. (2016). Ivermectin versus albendazole or thiabendazole for\n                    Strongyloides stercoralis\n                    infection. <i>Cochrane Database of Systematic Reviews</i>, <i>2016</i>(1). <a href=\"https://doi.org/10.1002/14651858.CD007745.pub3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD007745.pub3</a>"}, {"title": "Efficacy of current drugs against soil-transmitted helminth infections: systematic review and meta-analysis.", "authors": "Keiser J, Utzinger J", "year": 2008, "journal": "JAMA", "doi": "10.1001/jama.299.16.1937", "pmid": "18430913", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/18430913/", "type": "meta-analysis", "summary": "This meta-analysis pooled 20 randomized trials of single-dose albendazole, mebendazole, levamisole and pyrantel pamoate against roundworm, hookworm and whipworm, mostly in children in highly endemic regions. Single-dose pyrantel pamoate, the main over-the-counter dewormer in the US, cured 88% of roundworm infections but only 31% of hookworm infections, and no pooled estimate was possible for whipworm. The pyrantel data are thin (131 and 152 patients), it does not cover many parasites, and the trials treated infected people rather than testing a yearly cleanse in healthy adults.", "highlight": "Single-dose oral albendazole, mebendazole, and pyrantel pamoate show high cure rates against A lumbricoides.", "apa": "Keiser, J., &amp; Utzinger, J. (2008). Efficacy of Current Drugs Against Soil-Transmitted Helminth Infections. <i>Jama</i>, <i>299</i>(16). <a href=\"https://doi.org/10.1001/jama.299.16.1937\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.299.16.1937</a>"}, {"title": "Effectiveness of dried Carica papaya seeds against human intestinal parasitosis: a pilot study.", "authors": "Okeniyi JA, Ogunlesi TA, Oyelami OA, Adeyemi LA", "year": 2007, "journal": "Journal of Medicinal Food", "doi": "10.1089/jmf.2005.065", "pmid": "17472487", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/17472487/", "type": "RCT", "summary": "This small randomized pilot trial gave 60 Nigerian children with parasites confirmed on stool microscopy a single 20 mL dose of either air-dried papaya seed and honey elixir or honey alone. Stools cleared of parasites in 77% of the papaya group versus 17% of the honey group at 7 days, with no harmful effects reported. It is one small, short trial in infected children in a high-prevalence setting with no comparison to standard drugs, so it does not show that papaya seeds work as a cleanse for people without an infection.", "highlight": "Significantly more subjects given CPH elixir than those given honey had their stools cleared of parasites", "apa": "Okeniyi, J. A., Ogunlesi, T. A., Oyelami, O. A., &amp; Adeyemi, L. A. (2007). Effectiveness of Dried\n                    Carica papaya\n                    Seeds Against Human Intestinal Parasitosis: A Pilot Study. <i>Journal of Medicinal Food</i>, <i>10</i>(1), 194–196. <a href=\"https://doi.org/10.1089/jmf.2005.065\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1089/jmf.2005.065</a>"}, {"title": "Usefulness of pumpkin seeds combined with areca nut extract in community-based treatment of human taeniasis in northwest Sichuan Province, China.", "authors": "Li T, Ito A, Chen X, et al.", "year": 2012, "journal": "Acta Tropica", "doi": "10.1016/j.actatropica.2012.08.002", "pmid": "22910218", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/22910218/", "type": "cohort", "summary": "This non-randomized community study in Sichuan, China, treated 115 suspected tapeworm cases with pumpkin seeds plus areca nut extract and compared small groups given either one alone. In the 45 confirmed cases, 89% expelled intact worms after the combination, usually within about 2 hours, while pumpkin seeds alone worked in 9 of 12 confirmed cases but took about 14 hours. The groups were small and not randomized, nearly half of patients had nausea or dizziness, and areca nut is a known carcinogen, so this is not support for eating pumpkin seeds as a routine cleanse.", "highlight": "The pumpkin seed/areca combined treatment was indicated to be safe and highly effective (89%) for human taeniasis.", "apa": "Li, T., Ito, A., Chen, X., Long, C., Okamoto, M., Raoul, F., Giraudoux, P., Yanagida, T., Nakao, M., Sako, Y., Xiao, N., &amp; Craig, P. S. (2012). Usefulness of pumpkin seeds combined with areca nut extract in community-based treatment of human taeniasis in northwest Sichuan Province, China. <i>Acta Tropica</i>, <i>124</i>(2), 152–157. <a href=\"https://doi.org/10.1016/j.actatropica.2012.08.002\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1016/j.actatropica.2012.08.002</a>"}]}, {"id": "bloodtest", "label": "Blood test", "title": "Annual blood test", "tier": "annual", "group": null, "blurb": "Once a year at minimum (Bryan Johnson draws blood every 3–6 months). The markers below are the ones in his Blueprint baseline panel.", "sources": [{"title": "General health checks in adults for reducing morbidity and mortality from disease", "authors": "Krogsbøll LT, Jørgensen KJ, Gøtzsche PC", "year": 2019, "journal": "The Cochrane database of systematic reviews", "doi": "10.1002/14651858.CD009009.pub3", "pmid": "30699470", "pmcid": "PMC6353639", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6353639/", "type": "systematic review", "summary": "Cochrane review of 17 randomised trials with about 252,000 adults comparing general health checks with no checks. Health checks had little or no effect on total mortality (RR 1.00), cancer mortality or cardiovascular mortality, based mostly on high-certainty evidence. This means broad untargeted checkups do not save lives on their own, so the value of a yearly blood test lies in specific, evidence-backed markers acted on when abnormal.", "highlight": "Health checks have little or no effect on total mortality (risk ratio (RR) 1.00, 95% confidence interval (CI) 0.97 to 1.03", "apa": "Krogsbøll, L. T., Jørgensen, K. J., &amp; Gøtzsche, P. C. (2019). General health checks in adults for reducing morbidity and mortality from disease. <i>Cochrane Database of Systematic Reviews</i>, <i>2019</i>(1). <a href=\"https://doi.org/10.1002/14651858.CD009009.pub3\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1002/14651858.CD009009.pub3</a>"}, {"title": "Screening for Prediabetes and Type 2 Diabetes: US Preventive Services Task Force Recommendation Statement", "authors": "US Preventive Services Task Force, Davidson KW, Barry MJ, et al.", "year": 2021, "journal": "JAMA", "doi": "10.1001/jama.2021.12531", "pmid": "34427594", "pmcid": null, "url": "https://pubmed.ncbi.nlm.nih.gov/34427594/", "type": "guideline", "summary": "USPSTF recommendation statement based on a commissioned systematic review of screening for prediabetes and type 2 diabetes in asymptomatic adults. It concludes with moderate certainty that screening adults aged 35-70 with overweight or obesity, and referring those with prediabetes to prevention programs, has a moderate net benefit (B grade). The recommendation is targeted to a risk group rather than everyone, which is how screening tends to earn its benefit.", "highlight": "The USPSTF recommends screening for prediabetes and type 2 diabetes in adults aged 35 to 70 years who have overweight or obesity", "apa": "US Preventive Services Task Force, Davidson, K. W., Barry, M. J., Mangione, C. M., Cabana, M., Caughey, A. B., Davis, E. M., Donahue, K. E., Doubeni, C. A., Krist, A. H., Kubik, M., Li, L., Ogedegbe, G., Owens, D. K., Pbert, L., Silverstein, M., Stevermer, J., Tseng, C.-W., &amp; Wong, J. B. (2021). Screening for Prediabetes and Type 2 Diabetes. <i>Jama</i>, <i>326</i>(8), 736. <a href=\"https://doi.org/10.1001/jama.2021.12531\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jama.2021.12531</a>"}, {"title": "Apolipoprotein B Particles and Cardiovascular Disease: A Narrative Review", "authors": "Sniderman AD, Thanassoulis G, Glavinovic T, et al.", "year": 2019, "journal": "JAMA cardiology", "doi": "10.1001/jamacardio.2019.3780", "pmid": "31642874", "pmcid": "PMC7369156", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7369156/", "type": "review", "summary": "Narrative review in JAMA Cardiology of the biology and evidence behind apolipoprotein B as a measure of atherogenic lipoprotein particles. It argues apoB counts the particles that actually drive plaque and captures cardiovascular risk more accurately than LDL cholesterol or non-HDL cholesterol. It is a narrative review by advocates rather than a trial, but it makes a solid case for adding apoB to a routine lipid panel.", "highlight": "Apolipoprotein B unifies, amplifies, and simplifies the information from the conventional lipid markers as to the atherogenic risk attributable to the apoB lipoproteins", "apa": "Sniderman, A. D., Thanassoulis, G., Glavinovic, T., Navar, A. M., Pencina, M., Catapano, A., &amp; Ference, B. A. (2019). Apolipoprotein B Particles and Cardiovascular Disease. <i>JAMA Cardiology</i>, <i>4</i>(12), 1287. <a href=\"https://doi.org/10.1001/jamacardio.2019.3780\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1001/jamacardio.2019.3780</a>"}], "markers": [["Heart & lipids", "ApoB, Lp(a), LDL-C, LDL particle number & size, HDL-C, triglycerides, total & non-HDL cholesterol"], ["Blood sugar & metabolism", "fasting glucose, HbA1c, fasting insulin, leptin, uric acid"], ["Inflammation & immune", "hs-CRP, homocysteine, white blood cell count with differential, ANA, rheumatoid factor"], ["Complete blood count", "red blood cells, hemoglobin, hematocrit, MCV, MCH, RDW, platelets"], ["Liver, kidney & pancreas", "ALT, AST, GGT, alkaline phosphatase, bilirubin, albumin, total protein, creatinine, eGFR, BUN, amylase, lipase, urinalysis"], ["Electrolytes & minerals", "sodium, potassium, chloride, CO2, calcium, magnesium, zinc"], ["Vitamins & nutrients", "vitamin D, methylmalonic acid (for B12 status), ferritin, iron, iron-binding capacity, iron saturation, omega-3 index (EPA, DPA, DHA), omega-6/omega-3 ratio"], ["Hormones & thyroid", "TSH, free T4, free T3, TPO and thyroglobulin antibodies, total & free testosterone, estradiol, SHBG, DHEA-S, cortisol, LH, FSH, prolactin"], ["Toxins", "lead, mercury"], ["Sex-specific", "PSA (men), AMH (women)"], ["Brain", "pTau217, an early Alzheimer's risk marker, on Bryan's protocol"]], "markers_src": [["Blueprint baseline biomarker panel", "https://immortals.com/pages/biomarkers"], ["Bryan Johnson's protocol", "https://protocol.bryanjohnson.com/"]]}, {"id": "fast3to5", "label": "3–5 day fast", "title": "3–5 day fast", "tier": "annual", "group": null, "blurb": "Once a year, water-only or a fasting-mimicking diet. Do it with medical supervision: electrolytes matter, and breaking it (refeeding) needs care.", "sources": [{"title": "Fasting-mimicking diet and markers/risk factors for aging, diabetes, cancer, and cardiovascular disease", "authors": "Wei M, Brandhorst S, Shelehchi M, et al.", "year": 2017, "journal": "Science Translational Medicine", "doi": "10.1126/scitranslmed.aai8700", "pmid": "28202779", "pmcid": "PMC6816332", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6816332/", "type": "RCT", "summary": "100 generally healthy US adults were randomized to normal eating or a 5-day low-calorie, low-protein fasting-mimicking diet (FMD) once a month for 3 months, with controls later crossed over. Three FMD cycles reduced body weight, trunk fat, blood pressure and IGF-1, with no serious adverse effects, and benefits were larger in people already at risk. It was short, unblinded, had notable dropout, and was run by the diet's inventor (Longo, who holds equity in the company selling it), so the results need independent confirmation.", "highlight": "Three FMD cycles reduced body weight, trunk, and total body fat; lowered blood pressure; and decreased insulin-like growth factor 1 (IGF-1).", "apa": "Wei, M., Brandhorst, S., Shelehchi, M., Mirzaei, H., Cheng, C. W., Budniak, J., Groshen, S., Mack, W. J., Guen, E., Di Biase, S., Cohen, P., Morgan, T. E., Dorff, T., Hong, K., Michalsen, A., Laviano, A., &amp; Longo, V. D. (2017). Fasting-mimicking diet and markers/risk factors for aging, diabetes, cancer, and cardiovascular disease. <i>Science Translational Medicine</i>, <i>9</i>(377), eaai8700. <a href=\"https://doi.org/10.1126/scitranslmed.aai8700\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1126/scitranslmed.aai8700</a>"}, {"title": "Fasting-mimicking diet causes hepatic and blood markers changes indicating reduced biological age and disease risk", "authors": "Brandhorst S, Levine ME, Wei M, et al.", "year": 2024, "journal": "Nature Communications", "doi": "10.1038/s41467-024-45260-9", "pmid": "38378685", "pmcid": "PMC10879164", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10879164/", "type": "RCT", "summary": "This is a secondary, exploratory analysis of blood samples and liver MRI from FMD trial participants, replicated in a second clinical study. Three monthly 5-day FMD cycles were linked to lower insulin resistance, less liver fat, a younger immune profile, and a 2.5-year drop in median biological age independent of weight loss. Biological-age scores are surrogate markers, not lived years, and the work comes from the same group with a commercial stake in the product.", "highlight": "3 FMD cycles were associated with a decrease of 2.5 years in median biological age, independent of weight loss", "apa": "Brandhorst, S., Levine, M. E., Wei, M., Shelehchi, M., Morgan, T. E., Nayak, K. S., Dorff, T., Hong, K., Crimmins, E. M., Cohen, P., &amp; Longo, V. D. (2024). Fasting-mimicking diet causes hepatic and blood markers changes indicating reduced biological age and disease risk. <i>Nature Communications</i>, <i>15</i>(1), 1309. <a href=\"https://doi.org/10.1038/s41467-024-45260-9\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1038/s41467-024-45260-9</a>"}, {"title": "Safety, health improvement and well-being during a 4 to 21-day fasting period in an observational study including 1422 subjects", "authors": "Wilhelmi de Toledo F, Grundler F, Bergouignan A, et al.", "year": 2019, "journal": "PLoS One", "doi": "10.1371/journal.pone.0209353", "pmid": "30601864", "pmcid": "PMC6314618", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6314618/", "type": "cohort", "summary": "This one-year observational study followed 1,422 people doing Buchinger fasts of 4 to 21 days (about 200-250 kcal/day of juice and broth) under daily medical supervision in a German clinic. Weight, waist and blood pressure fell, ketones rose, 93.2% reported no hunger, and adverse effects occurred in under 1%. There was no control group, the clinic ran the study, and participants were screened and supervised; people on insulin or blood-pressure drugs, those with eating disorders, and anyone fasting at home without guidance on medications and gradual refeeding should not assume the same safety record.", "highlight": "Adverse effects were reported in less than 1% of the participants.", "apa": "Wilhelmi de Toledo, F., Grundler, F., Bergouignan, A., Drinda, S., &amp; Michalsen, A. (2019). Safety, health improvement and well-being during a 4 to 21-day fasting period in an observational study including 1422 subjects. <i>Plos One</i>, <i>14</i>(1), e0209353. <a href=\"https://doi.org/10.1371/journal.pone.0209353\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.1371/journal.pone.0209353</a>"}]}];